def known_etf_route_metadata(symbol: str) -> dict[str, Any]:
    """Return provider-specific route metadata we can safely seed by ticker."""

    normalized_symbol = symbol.strip().upper()
    known_metadata = KNOWN_ETF_PROVIDER_METADATA_BY_SYMBOL.get(normalized_symbol)
    if known_metadata:
        return {
            "issuer": known_metadata.get("issuer"),
            "provider_aliases": dict(known_metadata.get("provider_aliases") or {}),
        }
    ishares_product_id = ISHARES_PRODUCT_IDS_BY_SYMBOL.get(normalized_symbol)
    if ishares_product_id:
        return {
            "issuer": "iShares",
            "provider_aliases": {
                "issuer_product_id": ishares_product_id,
            },
        }
    return {}


class IsharesHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """iShares holdings adapter with known product ids for tested ETFs."""

    api_base_url = (
        "https://www.blackrock.com/varnish-api/blk-one01-product-data/"
        "product-data/api/v2/get-product-data?"
    )
    dated_url_template_aliases = (
        "dated_holdings_url_template",
        "dated_source_url_template",
        "ishares_dated_holdings_url_template",
    )

    def resolve_source_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        if source_url:
            return source_url.strip()
        identifiers = identifiers or {}
        values = self._normalized_identifiers(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers,
        )
        product_id = values.get("issuer_product_id")
        if not product_id:
            return None
        query = urlencode(
            {
                "appSubType": "ISHARES",
                "appType": "PRODUCT_PAGE",
                "component": "holdings.all",
                "locale": "en_US",
                "portfolioId": product_id,
                "targetSite": "us-ishares",
                "userType": "individual",
                "excludeContent": "true",
                "includeConfig": "true",
            }
        )
        return f"{self.api_base_url}{query}"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        if source_url:
            return await super().fetch_latest(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                source_url=source_url,
                identifiers=identifiers,
            )

        resolved_source_url = self.resolve_source_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers or {},
        )
        if not resolved_source_url:
            return await super().fetch_latest(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                identifiers=identifiers,
            )

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            for attempt in range(2):
                try:
                    response = await client.get(
                        resolved_source_url,
                        headers=_holdings_request_headers(accept="application/json,*/*"),
                        follow_redirects=True,
                    )
                    break
                except httpx.TimeoutException:
                    if attempt:
                        raise
                    await asyncio.sleep(0.25)
        response.raise_for_status()
        payload = response.json()
        rows = self._parse_blackrock_holdings_payload(payload)
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json=payload,
            source_url=resolved_source_url,
            source_identifier=symbol.strip().upper(),
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "terms_note": self.config.terms_note,
                "route_resolution": "issuer_public_json_api",
                "source_format": "json",
                "composition_date": self._composition_date_from_payload(payload),
            },
        )

    def _normalized_identifiers(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None,
        identifiers: dict[str, str],
    ) -> dict[str, str]:
        values = super()._normalized_identifiers(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers,
        )
        known_product_id = ISHARES_PRODUCT_IDS_BY_SYMBOL.get(symbol.strip().upper())
        if known_product_id:
            values.setdefault("issuer_product_id", known_product_id)
            values.setdefault("fund_id", known_product_id)
            values.setdefault("product_id", known_product_id)
        return values

    def _parse_blackrock_holdings_payload(
        self, payload: dict[str, Any]
    ) -> list[CanonicalHoldingRow]:
        data_points = self._blackrock_holdings_data_points(payload)
        if not data_points:
            return []
        ticker_values = self._blackrock_values(data_points, "ticker")
        issue_values = self._blackrock_values(data_points, "issueName")
        row_count = max(len(ticker_values), len(issue_values))
        rows: list[CanonicalHoldingRow] = []
        for index in range(row_count):
            row = CanonicalHoldingRow(
                symbol=_clean(self._blackrock_value(data_points, "ticker", index)),
                name=_clean(self._blackrock_value(data_points, "issueName", index)),
                cusip=_clean(self._blackrock_value(data_points, "cusip", index)),
                isin=_clean(self._blackrock_value(data_points, "isin", index)),
                sedol=_clean(self._blackrock_value(data_points, "sedol", index)),
                weight=_decimal_percent_points(
                    self._blackrock_value(data_points, "holdingPercent", index)
                ),
                shares=_decimal(self._blackrock_value(data_points, "unitsHeld", index)),
                market_value=_decimal(self._blackrock_value(data_points, "marketValue", index)),
                currency=_clean(self._blackrock_value(data_points, "currencyCode", index)),
                country=_clean(self._blackrock_value(data_points, "countryOfRisk", index)),
                exchange=_clean(self._blackrock_value(data_points, "exchange", index)),
                holding_type=self._holding_type_from_asset_class(
                    self._blackrock_value(data_points, "assetClass", index)
                ),
                row_type="security",
                source_row_id=str(index + 1),
                extra_data={
                    "source": "blackrock_product_data_api",
                    "sector": _clean(self._blackrock_value(data_points, "sectorName", index)),
                },
            )
            if row.symbol or row.name or row.cusip or row.isin:
                rows.append(row)
        return rows

    @staticmethod
    def _blackrock_holdings_data_points(payload: dict[str, Any]) -> dict[str, Any]:
        if not isinstance(payload, dict):
            return {}
        holdings = payload.get("componentsByNameMap", {}).get("holdings", {})
        all_holdings = holdings.get("containersByNameMap", {}).get("all", {})
        data_points = all_holdings.get("dataPointsByNameMap", {})
        return data_points if isinstance(data_points, dict) else {}

    @staticmethod
    def _blackrock_values(data_points: dict[str, Any], key: str) -> list[Any]:
        data_point = data_points.get(key)
        if not isinstance(data_point, dict):
            return []
        values = data_point.get("value")
        if isinstance(values, list):
            return values
        formatted_values = data_point.get("formattedValue")
        if isinstance(formatted_values, list):
            return formatted_values
        return []

    @classmethod
    def _blackrock_value(cls, data_points: dict[str, Any], key: str, index: int) -> Any:
        values = cls._blackrock_values(data_points, key)
        if index < len(values):
            return values[index]
        return None

    @classmethod
    def _composition_date_from_payload(cls, payload: dict[str, Any]) -> str | None:
        value = cls._blackrock_holdings_data_points(payload).get("asOfDate", {}).get("value")
        if value is None:
            return None
        text = str(value)
        if len(text) != 8 or not text.isdigit():
            return None
        return f"{text[:4]}-{text[4:6]}-{text[6:8]}"

    @staticmethod
    def _holding_type_from_asset_class(value: Any) -> str:
        text = (_clean(value) or "").lower()
        if "cash" in text:
            return "cash"
        if "bond" in text or "fixed income" in text:
            return "fixed_income"
        return "equity"


ARK_HOLDINGS_FILE_STEMS: dict[str, str] = {
    "ARKB": "ARK_21SHARES_BITCOIN_ETF_ARKB_HOLDINGS",
    "ARKF": "ARK_FINTECH_INNOVATION_ETF_ARKF_HOLDINGS",
    "ARKG": "ARK_GENOMIC_REVOLUTION_ETF_ARKG_HOLDINGS",
    "ARKK": "ARK_INNOVATION_ETF_ARKK_HOLDINGS",
    "ARKQ": "ARK_AUTONOMOUS_TECHNOLOGY_&_ROBOTICS_ETF_ARKQ_HOLDINGS",
    "ARKW": "ARK_NEXT_GENERATION_INTERNET_ETF_ARKW_HOLDINGS",
    "ARKX": "ARK_SPACE_EXPLORATION_&_INNOVATION_ETF_ARKX_HOLDINGS",
    "IZRL": "ARK_ISRAEL_INNOVATIVE_TECHNOLOGY_ETF_IZRL_HOLDINGS",
    "PRNT": "THE_3D_PRINTING_ETF_PRNT_HOLDINGS",
}


class ArkHoldingsAdapter(IssuerCsvHoldingsAdapter):
    dated_url_template_aliases = (
        "dated_holdings_url_template",
        "dated_source_url_template",
        "ark_dated_holdings_url_template",
    )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        """Fetch ARK's verified fund-file CSV, never a generic fallback."""
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in ARK_HOLDINGS_FILE_STEMS:
            raise ValueError(
                f"ARK does not have a verified native holdings route for {normalized_symbol}."
            )
        resolved_source_url = self.resolve_source_url(
            symbol=normalized_symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        if not resolved_source_url or not urlparse(resolved_source_url).netloc.endswith(
            "ark-funds.com"
        ):
            raise ValueError(
                f"ARK holdings route for {normalized_symbol} must resolve to ark-funds.com."
            )
        return await self._fetch_explicit_issuer_csv(
            symbol=normalized_symbol,
            issuer_product_id=issuer_product_id or normalized_symbol,
            source_url=resolved_source_url,
            identifiers=identifiers,
            route_resolution="ark_fund_scoped_holdings_csv",
        )

    async def fetch_for_date(
        self,
        *,
        symbol: str,
        requested_date: date,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        """Fetch an explicitly configured historical artifact.

        Current ARK refreshes are restricted to the verified ark-funds.com
        route. Historical backfills may intentionally use an archived issuer
        route (or a controlled test fixture), so the configured dated template
        is accepted here and still passes the normal artifact identity checks
        in the refresh service.
        """
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in ARK_HOLDINGS_FILE_STEMS:
            raise ValueError(
                f"ARK does not have a verified native holdings route for {normalized_symbol}."
            )
        resolved_source_url = self.resolve_dated_source_url(
            symbol=normalized_symbol,
            requested_date=requested_date,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        if not resolved_source_url:
            raise ValueError(
                f"ark needs a dated holdings URL template for {normalized_symbol}; "
                "configure that provider's dated holdings URL template alias."
            )
        result = await self._fetch_explicit_issuer_csv(
            symbol=normalized_symbol,
            issuer_product_id=issuer_product_id or normalized_symbol,
            source_url=resolved_source_url,
            identifiers=identifiers,
            route_resolution="issuer_dated_profile_template",
        )
        result.legal_metadata = {
            **(result.legal_metadata or {}),
            "requested_holdings_date": requested_date.isoformat(),
        }
        return result

    def _normalized_identifiers(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None,
        identifiers: dict[str, str],
    ) -> dict[str, str]:
        values = super()._normalized_identifiers(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers,
        )
        holdings_file_name = ARK_HOLDINGS_FILE_STEMS.get(symbol.strip().upper())
        if holdings_file_name:
            values.setdefault("holdings_file_name", holdings_file_name)
        return values


class SpdrHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch State Street SPDR holdings from its fund-scoped daily workbook.

    SPDR publishes a stable XLSX layout per ETF.  Keeping the schema here avoids
    silently treating a changed issuer workbook as an arbitrary generic table.
    """

    _WORKBOOK_TEMPLATE = (
        "https://www.ssga.com/us/en/intermediary/etfs/library-content/"
        "products/fund-data/etfs/us/holdings-daily-us-en-{symbol_lower}.xlsx"
    )
    _REQUIRED_HEADERS = frozenset(
        {"Name", "Ticker", "Identifier", "SEDOL", "Weight", "Shares Held", "Local Currency"}
    )
    # Some SPDR distribution endpoints (and older issuer workbooks) expose a
    # smaller, still fund-scoped table.  It is a known SPDR schema, not a
    # generic CSV fallback: identity is taken from the workbook preamble and
    # the fields are normalized into the same canonical rows.
    _COMPACT_HEADERS = frozenset({"Ticker", "Name", "Weight (%)", "Shares", "Currency"})

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        normalized_symbol = symbol.strip().upper()
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500"),
            status="ready" if normalized_symbol else "needs_issuer_route",
            reason=(
                "State Street publishes this ETF's complete current holdings workbook on its official SPDR route."
                if normalized_symbol
                else "SPDR holdings require an ETF symbol."
            ),
            source_url=(self._workbook_url(normalized_symbol) if normalized_symbol else None),
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            raise ValueError("SPDR holdings require an ETF symbol.")
        resolved_source_url = self.resolve_source_url(
            symbol=normalized_symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        if not resolved_source_url:
            product_page_url = self.resolve_product_page_url(
                symbol=normalized_symbol,
                issuer_product_id=issuer_product_id,
                identifiers=identifiers,
            )
            if product_page_url:
                discovered_url = await self._discover_source_url_from_product_page(
                    symbol=normalized_symbol,
                    issuer_product_id=issuer_product_id,
                    identifiers=identifiers or {},
                )
                if discovered_url:
                    return await self._fetch_explicit_issuer_csv(
                        symbol=normalized_symbol,
                        issuer_product_id=issuer_product_id,
                        source_url=discovered_url,
                        identifiers=identifiers,
                        route_resolution="issuer_product_page_discovery",
                    )

        workbook_url = resolved_source_url or self._workbook_url(normalized_symbol)
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                workbook_url,
                headers=_holdings_request_headers(
                    accept="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,*/*"
                ),
                follow_redirects=True,
            )
        response.raise_for_status()
        rows, composition_date, fund_symbol = self._parse_workbook(
            response.content,
            symbol=normalized_symbol,
        )
        if fund_symbol != normalized_symbol:
            raise ValueError(
                f"SPDR workbook identity did not match requested ETF {normalized_symbol}."
            )
        if not rows:
            raise ValueError(f"SPDR workbook did not expose holdings for {normalized_symbol}.")
        workbook_rows = parse_xlsx_table(response.content)
        return HoldingsFetchResult(
            rows=rows,
            raw_text=_table_to_text(workbook_rows),
            raw_json={"source_format": "xlsx", "workbook_rows": workbook_rows},
            # httpx supplies ``response.url`` in production; keeping the
            # requested URL when a lightweight transport/fake omits it makes
            # the adapter deterministic without losing provenance.
            source_url=str(getattr(response, "url", workbook_url)),
            source_identifier=issuer_product_id,
            legal_metadata={
                "source_access": "spdr_fund_scoped_daily_holdings_xlsx",
                "source_provider": "spdr",
                "adapter_key": self.adapter_key,
                "source_format": "xlsx",
                "route_resolution": "spdr_symbol_daily_holdings_workbook",
                "snapshot_provenance": "spdr_native_daily_holdings_workbook",
                **({"composition_date": composition_date.isoformat()} if composition_date else {}),
            },
        )

    @classmethod
    def _workbook_url(cls, symbol: str) -> str:
        return cls._WORKBOOK_TEMPLATE.format(symbol_lower=symbol.lower())

    @classmethod
    def _parse_workbook(
        cls,
        raw_workbook: bytes,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None, str | None]:
        workbook_rows = parse_xlsx_table(raw_workbook)
        header_index = None
        compact_layout = False
        for index, row in enumerate(workbook_rows[:20]):
            headers = {_clean(value) or "" for value in row}
            if cls._REQUIRED_HEADERS.issubset(headers):
                header_index = index
                break
            if cls._COMPACT_HEADERS.issubset(headers):
                header_index = index
                compact_layout = True
                break
        if header_index is None:
            raise ValueError("SPDR workbook did not expose the expected holdings schema.")
        fund_symbol = next(
            (
                (_clean(row[1]) or "").upper()
                for row in workbook_rows[:header_index]
                if (_clean(row[0]) or "").rstrip(":").lower()
                in {"ticker symbol", "fund ticker", "ticker"}
                and len(row) > 1
            ),
            None,
        )
        composition_date = next(
            (
                cls._parse_as_of_date(_clean(row[1]))
                for row in workbook_rows[:header_index]
                if (_clean(row[0]) or "").rstrip(":").lower() == "holdings" and len(row) > 1
            ),
            None,
        )
        header = workbook_rows[header_index]
        rows: list[CanonicalHoldingRow] = []
        for position, raw_row in enumerate(workbook_rows[header_index + 1 :], start=1):
            raw = _row_dict(header, raw_row)
            name = _clean(raw.get("Name"))
            source_ticker = _clean(raw.get("Ticker"))
            identifier = _clean(raw.get("Identifier"))
            if not any((name, source_ticker, identifier)):
                continue
            holding_type, row_type = cls._classify_row(name=name, source_ticker=source_ticker)
            # SPDR appends legal/disclaimer text below the holdings table. Those
            # rows contain only a long name-like string and no ticker or stable
            # identifier; treating them as securities both pollutes the snapshot
            # and can overflow the canonical holding-name column. Keep genuine
            # cash/derivative rows (which are classified separately) intact.
            if len(name or "") > 300:
                continue
            if not source_ticker and not identifier and row_type != "cash":
                continue
            row_symbol = source_ticker if row_type == "security" else None
            rows.append(
                CanonicalHoldingRow(
                    symbol=row_symbol,
                    name=name,
                    cusip=identifier
                    if _looks_like_cusip(identifier) and row_type == "security"
                    else None,
                    sedol=_clean(raw.get("SEDOL")) if row_type == "security" else None,
                    weight=(
                        _decimal_percent_points(raw.get("Weight"))
                        if not compact_layout
                        else _decimal(raw.get("Weight (%)"))
                    ),
                    shares=_decimal(
                        raw.get("Shares Held") if not compact_layout else raw.get("Shares")
                    ),
                    currency=_clean(
                        raw.get("Local Currency") if not compact_layout else raw.get("Currency")
                    ),
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=f"spdr-{symbol}-{position}",
                    extra_data={
                        key: value for key, value in raw.items() if _clean(value) is not None
                    },
                )
            )
        return rows, composition_date, fund_symbol

    @staticmethod
    def _parse_as_of_date(value: str | None) -> date | None:
        match = re.search(r"(?:as of\s+)?(\d{1,2}-[A-Za-z]{3}-\d{4})", value or "", re.IGNORECASE)
        if match is None:
            return None
        try:
            return datetime.strptime(match.group(1), "%d-%b-%Y").date()
        except ValueError:
            return None

    @staticmethod
    def _classify_row(*, name: str | None, source_ticker: str | None) -> tuple[str, str]:
        text = " ".join(part for part in (name, source_ticker) if part).upper()
        if any(token in text for token in ("CASH", "MONEY MARKET", "TREASURY BILL")):
            return "cash", "cash"
        if any(token in text for token in ("OPTION", "FUTURE", "SWAP", "FORWARD")) or re.search(
            r"\b\d{6}[CP]\d{8}\b",
            text,
        ):
            return "derivative", "other"
        if " ETF" in text or " FUND" in text:
            return "fund", "security"
        return "equity", "security"


class VanguardHoldingsAdapter(IssuerCsvHoldingsAdapter):
    holding_types = (
        "stock",
        "bond",
        "short-term-reserve",
        "currency",
        "derivative",
        "commodity",
        "money-market",
    )

    def resolve_source_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        explicit = super().resolve_source_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        if explicit:
            return explicit
        identifiers = identifiers or {}
        # Keep probe output honest when the profile already supplies a
        # product page or SEC identity.  The fetch implementation may still
        # use Vanguard's public JSON route, but callers should see the route
        # metadata that made the profile eligible.
        product_page = _identifier(identifiers, *self.product_page_aliases)
        if product_page:
            return product_page
        sec_cik = _identifier(identifiers, "sec_cik")
        if sec_cik:
            return f"https://data.sec.gov/submissions/CIK{sec_cik.zfill(10)}.json"
        fund_id = _identifier(identifiers, "vanguard_fund_id", "fund_id", "issuer_product_id")
        lookup_id = (fund_id or issuer_product_id or symbol).strip().upper()
        if not lookup_id:
            return None
        return f"https://investor.vanguard.com/vmf/api/{lookup_id}/portfolio-holding/stock.json"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        identifiers = identifiers or {}
        normalized_symbol = symbol.strip().upper()
        lookup_id = (
            _identifier(identifiers, "vanguard_fund_id", "fund_id", "issuer_product_id")
            or issuer_product_id
            or normalized_symbol
        )
        if not lookup_id:
            return await super().fetch_latest(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                source_url=source_url,
                identifiers=identifiers,
            )

        rows: list[CanonicalHoldingRow] = []
        raw_payloads: dict[str, Any] = {}
        source_urls: list[str] = []
        as_of_dates: set[str] = set()
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            for holding_type in self.holding_types:
                resolved_source_url = (
                    source_url
                    if source_url and holding_type == "stock"
                    else (
                        "https://investor.vanguard.com/vmf/api/"
                        f"{lookup_id}/portfolio-holding/{holding_type}.json?start=1&count=20000"
                    )
                )
                response = await client.get(
                    resolved_source_url,
                    headers=_issuer_page_request_headers(accept="application/json,*/*"),
                    follow_redirects=True,
                )
                response.raise_for_status()
                payload = response.json()
                if not isinstance(payload, dict) or payload.get("status") in {404, "404"}:
                    continue
                parsed_rows = self._parse_vanguard_payload(
                    payload,
                    holding_type=holding_type,
                    row_offset=len(rows),
                )
                if not parsed_rows:
                    continue
                raw_payloads[holding_type] = payload
                source_urls.append(resolved_source_url)
                as_of_date = _clean(payload.get("asOfDate"))
                if as_of_date:
                    as_of_dates.add(as_of_date)
                rows.extend(parsed_rows)
                if source_url:
                    break

        if not rows:
            return await super().fetch_latest(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                source_url=source_url,
                identifiers=identifiers,
            )

        primary_source_url = (
            source_urls[0]
            if source_urls
            else self.resolve_source_url(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                source_url=source_url,
                identifiers=identifiers,
            )
        )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=json.dumps(raw_payloads),
            raw_json={"holdings_by_type": raw_payloads},
            source_url=primary_source_url,
            source_identifier=lookup_id,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "json",
                "route_resolution": "issuer_public_json_api",
                "holding_types": list(raw_payloads),
                "composition_date": min(as_of_dates) if as_of_dates else None,
                "as_of_date": min(as_of_dates) if as_of_dates else None,
                "terms_note": self.config.terms_note,
            },
        )

    def _parse_vanguard_payload(
        self,
        payload: dict[str, Any],
        *,
        holding_type: str,
        row_offset: int,
    ) -> list[CanonicalHoldingRow]:
        fund = payload.get("fund")
        entities = fund.get("entity") if isinstance(fund, dict) else None
        if isinstance(entities, dict):
            entities = [entities]
        if not isinstance(entities, list):
            return []

        rows: list[CanonicalHoldingRow] = []
        for index, item in enumerate(entities, start=1):
            if not isinstance(item, dict):
                continue
            symbol_value = _clean(item.get("ticker"))
            name = _clean(item.get("longName") or item.get("shortName") or item.get("securityName"))
            cusip = _clean(item.get("cusip"))
            isin = _clean(item.get("isin"))
            if not any([symbol_value, name, cusip, isin]):
                continue
            normalized_holding_type = (
                _clean(item.get("holdingType") or item.get("secMainType") or holding_type)
                or holding_type
            ).lower()
            row_type = "cash" if holding_type in {"currency", "money-market"} else "security"
            rows.append(
                CanonicalHoldingRow(
                    symbol=symbol_value,
                    name=name,
                    cusip=cusip,
                    isin=isin,
                    sedol=_clean(item.get("sedol")),
                    weight=_decimal_percent_points(item.get("percentWeight")),
                    shares=_decimal(item.get("sharesHeld")),
                    market_value=_decimal(item.get("marketValue")),
                    currency=_clean(item.get("currency")),
                    holding_type=normalized_holding_type,
                    row_type=row_type,
                    source_row_id=str(row_offset + index),
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        return rows


class WellingtonHoldingsAdapter(VanguardHoldingsAdapter):
    """Fetch the Vanguard-published portfolios for Wellington-managed US ETFs.

    Wellington manages these funds, while Vanguard is their legal issuer and the
    publisher of the complete portfolio API. Keeping that publisher boundary
    explicit avoids pretending Wellington exposes a separate public endpoint.
    """

    SUPPORTED_SYMBOLS = frozenset({"VDIG", "VUSG", "VUSV"})
    PRODUCT_PAGE_TEMPLATE = (
        "https://investor.vanguard.com/investment-products/etfs/profile/{symbol_lower}"
    )
    FALLBACK_FUND_IDS = {
        "VDIG": "V053",
        "VUSG": "V054",
        "VUSV": "V055",
    }

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in self.SUPPORTED_SYMBOLS:
            return super().probe(symbol=symbol, name=name, identifiers=identifiers)
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9000"),
            status="ready",
            reason=(
                "Wellington manages this US ETF and Vanguard publishes its complete "
                "public portfolio through the fund-scoped API."
            ),
            source_url=self.PRODUCT_PAGE_TEMPLATE.format(symbol_lower=normalized_symbol.lower()),
            issuer_product_id=self.FALLBACK_FUND_IDS[normalized_symbol],
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in self.SUPPORTED_SYMBOLS:
            raise ValueError(
                "Wellington's configured US ETF route supports only VUSV, VDIG, and VUSG."
            )
        if source_url is not None:
            raise ValueError("Wellington holdings use the verified Vanguard publisher route.")

        supplied_identifier = (
            _identifier(
                identifiers or {},
                "vanguard_fund_id",
                "fund_id",
                "issuer_product_id",
            )
            or issuer_product_id
        )
        if supplied_identifier and supplied_identifier.strip().upper() != normalized_symbol:
            raise ValueError(
                "Wellington ETF identifiers must match the requested Vanguard fund symbol."
            )

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            fund_id = await self._resolve_vanguard_fund_id(client, symbol=normalized_symbol)

        result = await self._fetch_vanguard_detail_holdings(
            symbol=normalized_symbol, fund_id=fund_id
        )
        if not result.rows:
            result = await self._fetch_vanguard_pcf(symbol=normalized_symbol, fund_id=fund_id)
        route_resolution = (result.legal_metadata or {}).get("route_resolution")
        if route_resolution != "vanguard_publisher_pcf_json_for_wellington_managed_etf":
            route_resolution = "vanguard_publisher_json_api_for_wellington_managed_etf"
        result.legal_metadata = {
            **(result.legal_metadata or {}),
            "source_access": self.config.source_access,
            "source_provider": "vanguard",
            "adapter_key": self.adapter_key,
            "route_resolution": route_resolution,
            "portfolio_manager": "wellington_management",
        }
        return result

    async def _fetch_vanguard_detail_holdings(
        self, *, symbol: str, fund_id: str
    ) -> HoldingsFetchResult:
        rows: list[CanonicalHoldingRow] = []
        raw_payloads: dict[str, Any] = {}
        source_urls: list[str] = []
        as_of_dates: set[str] = set()
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            for holding_type in self.holding_types:
                source_url = (
                    "https://investor.vanguard.com/vmf/api/"
                    f"{fund_id}/portfolio-holding/{holding_type}.json?start=1&count=20000"
                )
                response = await client.get(
                    source_url,
                    headers=_issuer_page_request_headers(accept="application/json,*/*"),
                    follow_redirects=True,
                )
                response.raise_for_status()
                payload = response.json()
                if not isinstance(payload, dict) or payload.get("status") in {404, "404"}:
                    continue
                parsed_rows = self._parse_vanguard_payload(
                    payload,
                    holding_type=holding_type,
                    row_offset=len(rows),
                )
                if not parsed_rows:
                    continue
                raw_payloads[holding_type] = payload
                source_urls.append(source_url)
                as_of_date = _clean(payload.get("asOfDate"))
                if as_of_date:
                    as_of_dates.add(as_of_date)
                rows.extend(parsed_rows)
        return HoldingsFetchResult(
            rows=rows,
            raw_text=json.dumps(raw_payloads),
            raw_json={"holdings_by_type": raw_payloads},
            source_url=source_urls[0]
            if source_urls
            else self.resolve_source_url(symbol=symbol, issuer_product_id=fund_id),
            source_identifier=fund_id,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": "vanguard",
                "adapter_key": self.adapter_key,
                "source_format": "json",
                "route_resolution": "vanguard_publisher_json_api_for_wellington_managed_etf",
                "holding_types": list(raw_payloads),
                "composition_date": min(as_of_dates) if as_of_dates else None,
                "as_of_date": min(as_of_dates) if as_of_dates else None,
                "terms_note": self.config.terms_note,
            },
        )

    async def _resolve_vanguard_fund_id(self, client: httpx.AsyncClient, *, symbol: str) -> str:
        product_page_url = self.PRODUCT_PAGE_TEMPLATE.format(symbol_lower=symbol.lower())
        response = await client.get(
            product_page_url,
            headers=_issuer_page_request_headers(accept="text/html,*/*"),
            follow_redirects=True,
        )
        response.raise_for_status()
        match = re.search(
            r'<script[^>]+id=["\']fundProfileData["\'][^>]*>(.*?)</script>',
            response.text,
            flags=re.IGNORECASE | re.DOTALL,
        )
        if match is None:
            return self.FALLBACK_FUND_IDS[symbol]
        try:
            payload = json.loads(html.unescape(match.group(1)))
        except json.JSONDecodeError:
            return self.FALLBACK_FUND_IDS[symbol]
        profile = payload.get("fundProfile") if isinstance(payload, dict) else None
        if not isinstance(profile, dict):
            return self.FALLBACK_FUND_IDS[symbol]
        page_ticker = _clean(profile.get("ticker"))
        long_name = _clean(profile.get("longName"))
        if page_ticker and page_ticker.upper() != symbol:
            raise ValueError("Wellington Vanguard product page resolved to the wrong ticker.")
        if long_name and "wellington" not in long_name.lower():
            raise ValueError(
                "Wellington Vanguard product page no longer identifies a Wellington ETF."
            )
        associated_ids = profile.get("associatedFundIds")
        fund_id = None
        if isinstance(associated_ids, dict):
            fund_id = _clean(associated_ids.get("etfFundId"))
        fund_id = fund_id or _clean(profile.get("fundId"))
        return fund_id or self.FALLBACK_FUND_IDS[symbol]

    async def _fetch_vanguard_pcf(self, *, symbol: str, fund_id: str) -> HoldingsFetchResult:
        source_url = (
            "https://investor.vanguard.com/vmf/api/"
            f"{fund_id}/portfolio-holding/pcf.json?start=1&count=20000"
        )
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                source_url,
                headers=_issuer_page_request_headers(accept="application/json,*/*"),
                follow_redirects=True,
            )
            response.raise_for_status()
            payload = response.json()
        rows = self._parse_vanguard_pcf_payload(payload, symbol=symbol, fund_id=fund_id)
        composition_date = self._parse_vanguard_pcf_date(
            payload.get("trdDate") or payload.get("trdDateStr")
        )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=json.dumps({"pcf": payload}),
            raw_json={"pcf": payload},
            source_url=source_url,
            source_identifier=fund_id,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": "vanguard",
                "adapter_key": self.adapter_key,
                "source_format": "json",
                "route_resolution": "vanguard_publisher_pcf_json_for_wellington_managed_etf",
                "holding_types": ["pcf"],
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _parse_vanguard_pcf_payload(
        payload: dict[str, Any],
        *,
        symbol: str,
        fund_id: str,
    ) -> list[CanonicalHoldingRow]:
        holdings = payload.get("holding") if isinstance(payload, dict) else None
        if not isinstance(holdings, list):
            return []
        rows: list[CanonicalHoldingRow] = []
        for index, item in enumerate(holdings, start=1):
            if not isinstance(item, dict):
                continue
            name = _clean(item.get("extraSecurityName") or item.get("shrtName"))
            ticker = _clean(item.get("extraTicker") or item.get("ticker"))
            cusip = _clean(item.get("extraCusip") or item.get("cusip"))
            isin = _clean(item.get("extraIsin") or item.get("isin"))
            sedol = _clean(item.get("extraSedol") or item.get("sedol"))
            if not any((name, ticker, cusip, isin, sedol)):
                continue
            asset_type = (_clean(item.get("assetType")) or "equity").lower()
            cash_designation = (_clean(item.get("cashDesignationFlag")) or "").lower()
            row_type = "cash" if asset_type == "cash" or cash_designation == "cash" else "security"
            rows.append(
                CanonicalHoldingRow(
                    symbol=ticker,
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    isin=isin,
                    sedol=sedol,
                    weight=_decimal_percent_points(item.get("weighting")),
                    shares=_decimal(item.get("shareQuantity") or item.get("faceAmt")),
                    market_value=_decimal(item.get("adjMarketValue") or item.get("marketValue")),
                    currency=_clean(item.get("currency")),
                    country=_clean(item.get("country") or item.get("countryName")),
                    exchange=_clean(item.get("primaryExchange")),
                    holding_type=asset_type,
                    row_type=row_type,
                    source_row_id=f"vanguard-pcf-{fund_id}-{index}",
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        return rows

    @staticmethod
    def _parse_vanguard_pcf_date(value: Any) -> date | None:
        text = _clean(value)
        if text is None:
            return None
        for pattern in ("%m/%d/%Y %H:%M:%S", "%m/%d/%Y", "%Y-%m-%d"):
            try:
                return datetime.strptime(text, pattern).date()
            except ValueError:
                continue
        return None


class InvescoHoldingsAdapter(IssuerCsvHoldingsAdapter):
    _PRODUCT_CATALOG_URL = (
        "https://dng-api.invesco.com/product/search?"
        "fq=countryCode:%22US%22&fq=language:%22en_us%22&fq=accountType:%22ETF%22&"
        "fq=contentType:%22Product%22&fq=shareClassStatus:%22open%22&"
        "q=_suggest_:*&fl=ticker,cusip,isin,accountName,title,url&rows=2000&start=0"
    )

    def __init__(self, config: IssuerCsvAdapterConfig) -> None:
        super().__init__(config)
        self._cusip_cache: dict[str, str] = {}

    @staticmethod
    def _holdings_url(cusip: str) -> str:
        return (
            "https://dng-api.invesco.com/cache/v1/accounts/en_US/shareclasses/"
            f"{cusip}/holdings/fund?idType=cusip&interval=monthly&productType=ETF"
        )

    async def _resolve_cusip(self, client: httpx.AsyncClient, symbol: str) -> str | None:
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            return None
        cached = self._cusip_cache.get(normalized_symbol)
        if cached:
            return cached
        response = await client.get(
            self._PRODUCT_CATALOG_URL,
            headers=_invesco_holdings_request_headers(),
            follow_redirects=True,
        )
        response.raise_for_status()
        payload = response.json()
        docs = payload.get("response", {}).get("docs", []) if isinstance(payload, dict) else []
        for document in docs if isinstance(docs, list) else []:
            if not isinstance(document, dict):
                continue
            ticker = _clean(document.get("ticker"))
            cusip = _clean(document.get("cusip"))
            if ticker and cusip and ticker.upper() == normalized_symbol:
                self._cusip_cache[normalized_symbol] = cusip
                return cusip
        return None

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name
        cusip = _identifier(identifiers, "cusip")
        if cusip:
            return HoldingsAdapterProbe(
                adapter_key=self.adapter_key,
                confidence=Decimal("0.9500"),
                status="ready",
                reason="Invesco exposes a public CUSIP-addressed holdings JSON endpoint.",
                source_url=self._holdings_url(cusip),
                issuer_product_id=cusip,
            )
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol:
            return HoldingsAdapterProbe(
                adapter_key=self.adapter_key,
                confidence=Decimal("0.9000"),
                status="ready",
                reason=(
                    "Invesco's public product catalog resolves the ETF ticker to a CUSIP "
                    "before the holdings request."
                ),
                source_url=self._PRODUCT_CATALOG_URL,
                issuer_product_id=normalized_symbol,
            )
        return super().probe(symbol=symbol, name="", identifiers=identifiers)

    def resolve_source_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        identifiers = identifiers or {}
        if source_url:
            return source_url.strip()
        explicit = _identifier(identifiers, *self.source_url_aliases)
        if explicit:
            return explicit
        cusip = _identifier(identifiers, "cusip")
        if cusip:
            return self._holdings_url(cusip)
        if _identifier(identifiers, *self.product_page_aliases):
            return None
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            return None
        return (
            "https://dng-api.invesco.com/cache/v1/accounts/en_US/shareclasses/"
            f"{normalized_symbol}/holdings/fund?idType=ticker&interval=monthly&productType=ETF"
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        identifiers = identifiers or {}
        explicit_source_url = source_url or _identifier(identifiers, *self.source_url_aliases)
        cusip = _identifier(identifiers, "cusip")
        # Older persisted route metadata used the ticker form, which Invesco's
        # holdings resource rejects. Re-resolve those routes through the public
        # catalog unless an explicit CUSIP has already been supplied.
        if explicit_source_url and "idType=ticker" in explicit_source_url and not cusip:
            explicit_source_url = None
        # Preserve the generic issuer-product-page discovery contract for
        # explicitly configured profiles.  The canonical Invesco path has no
        # product URL and therefore continues through catalog→CUSIP below;
        # custom/legacy profiles with a product page must not be forced onto
        # the catalog route.
        if (
            not explicit_source_url
            and not cusip
            and _identifier(identifiers, *self.product_page_aliases)
        ):
            return await super().fetch_latest(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                identifiers=identifiers,
            )
        route_resolution = "issuer_profile_metadata"
        try:
            async with httpx.AsyncClient(
                timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS
            ) as client:
                if explicit_source_url:
                    resolved_source_url = explicit_source_url
                else:
                    if not cusip:
                        cusip = await self._resolve_cusip(client, symbol)
                    if not cusip:
                        raise ValueError(f"Invesco product catalog has no CUSIP for {symbol}.")
                    resolved_source_url = self._holdings_url(cusip)
                    route_resolution = "issuer_public_json_catalog_cusip"
                response = await client.get(
                    resolved_source_url,
                    headers=_invesco_holdings_request_headers(),
                    follow_redirects=True,
                )
            response.raise_for_status()
            payload = response.json()
        except (httpx.HTTPError, requests.RequestException, ValueError) as route_error:
            if self.config.supports_sec_filing_fallback:
                sec_result = await self._fetch_latest_sec_filing_holdings(
                    symbol=symbol,
                    issuer_product_id=issuer_product_id,
                    identifiers=identifiers,
                )
                if sec_result is not None:
                    sec_result.legal_metadata = {
                        **(sec_result.legal_metadata or {}),
                        "issuer_route_failure": str(route_error),
                        "issuer_route_fallback": "sec_edgar_filing",
                    }
                    return sec_result
            raise
        holdings = payload.get("holdings") if isinstance(payload, dict) else None
        rows: list[CanonicalHoldingRow] = []
        for index, item in enumerate(holdings or [], start=1):
            if not isinstance(item, dict):
                continue
            symbol_value = _clean(item.get("ticker"))
            name = _clean(item.get("issuerName") or item.get("securityName"))
            if not any([symbol_value, name, item.get("cusip")]):
                continue
            holding_type = (_clean(item.get("securityTypeName")) or "security").lower()
            rows.append(
                CanonicalHoldingRow(
                    symbol=symbol_value,
                    name=name,
                    cusip=_clean(item.get("cusip")),
                    weight=_decimal_percent_points(item.get("percentageOfTotalNetAssets")),
                    shares=_decimal(item.get("units")),
                    currency=_clean(item.get("currency") or item.get("localCurrencyName")),
                    holding_type=holding_type,
                    row_type="cash" if holding_type in {"cash", "currency"} else "security",
                    source_row_id=str(index),
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json=payload,
            source_url=resolved_source_url,
            source_identifier=cusip or issuer_product_id or symbol.strip().upper(),
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "json",
                "route_resolution": route_resolution,
                "effective_date": payload.get("effectiveDate")
                if isinstance(payload, dict)
                else None,
                "effective_business_date": (
                    payload.get("effectiveBusinessDate") if isinstance(payload, dict) else None
                ),
                "total_number_of_holdings": (
                    payload.get("totalNumberOfHoldings") if isinstance(payload, dict) else None
                ),
                "terms_note": self.config.terms_note,
            },
        )


class SchwabHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Schwab's fund-scoped holdings CSV declared by its product page."""

    _PRODUCT_HOST = "www.schwabassetmanagement.com"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            raise ValueError("Schwab holdings require an ETF symbol.")
        holdings_url = source_url if self._is_native_holdings_url(source_url) else None
        if not holdings_url:
            page_url = self.resolve_product_page_url(
                symbol=normalized_symbol,
                issuer_product_id=issuer_product_id,
                identifiers=identifiers or {},
            )
            if not page_url or urlparse(page_url).netloc != self._PRODUCT_HOST:
                raise ValueError(
                    f"Schwab product page route is unavailable for {normalized_symbol}."
                )
            async with httpx.AsyncClient(
                timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS
            ) as client:
                page_response = await client.get(
                    page_url,
                    headers=_issuer_page_request_headers(accept="text/html,*/*"),
                    follow_redirects=True,
                )
            page_response.raise_for_status()
            holdings_url = _discover_holdings_download_url(
                str(getattr(page_response, "url", page_url)), page_response.text
            )
        if not self._is_native_holdings_url(holdings_url):
            raise ValueError(
                f"Schwab product page did not expose a fund-scoped native holdings CSV for {normalized_symbol}."
            )
        return await self._fetch_explicit_issuer_csv(
            symbol=normalized_symbol,
            issuer_product_id=issuer_product_id or normalized_symbol,
            source_url=holdings_url,
            identifiers=identifiers,
            route_resolution="schwab_product_page_declared_holdings_csv",
        )

    @classmethod
    def _is_native_holdings_url(cls, value: str | None) -> bool:
        if not value:
            return False
        parsed = urlparse(value)
        return parsed.netloc == cls._PRODUCT_HOST and parsed.path.lower().endswith(".csv")

    def source_request_headers(self, *, source_url: str) -> dict[str, str]:
        headers = _issuer_page_request_headers()
        headers["Referer"] = "https://www.schwabassetmanagement.com/"
        return headers


class GlobalXHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Global X fund-scoped holdings from its declared dated CSV artifact.

    Global X embeds the current complete holdings-file URL on each fund page.
    The URL is fund-specific and dated; resolving only that declared asset avoids
    the generic link-discovery path and prevents sibling-fund leakage.
    """

    _PRODUCT_PAGE_TEMPLATE = "https://www.globalxetfs.com/funds/{symbol_lower}/"
    _HOLDINGS_URL_PATTERN = re.compile(
        r"https://assets\.globalxetfs\.com/funds/holdings/"
        r"(?P<symbol>[a-z0-9_-]+)_full-holdings_(?P<as_of>\d{8})\.csv",
        re.IGNORECASE,
    )
    _REQUIRED_HEADERS = frozenset(
        {
            "% of Net Assets",
            "Ticker",
            "Name",
            "SEDOL",
            "Market Price ($)",
            "Shares Held",
            "Market Value ($)",
        }
    )

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            return HoldingsAdapterProbe(
                adapter_key=self.adapter_key,
                confidence=Decimal("0.5000"),
                status="needs_issuer_route",
                reason="Global X holdings require an ETF symbol to resolve its fund page.",
                required_identifiers=["symbol"],
            )
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500"),
            status="ready",
            reason="Global X publishes a fund-scoped complete holdings CSV from each ETF page.",
            source_url=self._product_page_url(normalized_symbol),
            issuer_product_id=normalized_symbol,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            raise ValueError("Global X holdings require an ETF symbol.")
        product_page_url = source_url or self._product_page_url(normalized_symbol)
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            product_page = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*"),
                follow_redirects=True,
            )
            product_page.raise_for_status()
            holdings_url = self._holdings_url_from_page(
                product_page.text,
                symbol=normalized_symbol,
            )
            holdings_response = await client.get(
                holdings_url,
                headers=_issuer_page_request_headers(accept="text/csv,text/plain,*/*"),
                follow_redirects=True,
            )
        holdings_response.raise_for_status()
        rows, composition_date = self._parse_holdings_csv(
            holdings_response.text,
            symbol=normalized_symbol,
        )
        if not rows:
            raise ValueError(
                f"Global X complete holdings CSV returned no rows for {normalized_symbol}."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=holdings_response.text,
            raw_json={"source_format": "csv"},
            source_url=str(holdings_response.url),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": "global_x_fund_page_declared_complete_holdings_csv",
                "source_provider": "global_x",
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "global_x_fund_page_declared_holdings_csv",
                "product_page_url": str(product_page.url),
                "snapshot_provenance": "global_x_native_dated_holdings_csv",
                **({"composition_date": composition_date.isoformat()} if composition_date else {}),
            },
        )

    @classmethod
    def _product_page_url(cls, symbol: str) -> str:
        return cls._PRODUCT_PAGE_TEMPLATE.format(symbol_lower=symbol.strip().lower())

    @classmethod
    def _holdings_url_from_page(cls, page_text: str, *, symbol: str) -> str:
        expected_symbol = symbol.strip().lower()
        candidates = [
            html.unescape(match.group(0))
            for match in cls._HOLDINGS_URL_PATTERN.finditer(page_text)
            if match.group("symbol").lower() == expected_symbol
        ]
        if not candidates:
            raise ValueError(
                f"Global X product page did not declare a complete holdings CSV for {symbol}."
            )
        return candidates[0]

    @classmethod
    def _parse_holdings_csv(
        cls,
        raw_csv: str,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        lines = [line for line in raw_csv.splitlines() if line.strip()]
        header_index = next(
            (
                index
                for index, line in enumerate(lines)
                if cls._REQUIRED_HEADERS.issubset(set(next(csv.reader([line]))))
            ),
            None,
        )
        if header_index is None:
            raise ValueError("Global X CSV did not expose the expected complete holdings schema.")
        composition_date = cls._composition_date(lines[:header_index])
        rows: list[CanonicalHoldingRow] = []
        for position, raw in enumerate(csv.DictReader(lines[header_index:]), start=1):
            name = _clean(raw.get("Name"))
            source_ticker = _clean(raw.get("Ticker"))
            row_type, holding_type = cls._classify_row(name=name, source_ticker=source_ticker)
            if not any([name, source_ticker, _clean(raw.get("SEDOL"))]):
                continue
            rows.append(
                CanonicalHoldingRow(
                    symbol=cls._tradable_symbol(source_ticker) if row_type == "security" else None,
                    name=name,
                    sedol=_clean(raw.get("SEDOL")) if row_type == "security" else None,
                    weight=_decimal_percent_points(raw.get("% of Net Assets")),
                    shares=_decimal(raw.get("Shares Held")),
                    market_value=_decimal(raw.get("Market Value ($)")),
                    currency="USD",
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=f"{symbol}:{position}",
                    extra_data={
                        "source_ticker": source_ticker,
                        "market_price": _clean(raw.get("Market Price ($)")),
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _composition_date(lines: list[str]) -> date | None:
        for line in lines:
            match = re.search(r"as of\s+(\d{2}/\d{2}/\d{4})", line, re.IGNORECASE)
            if match:
                return datetime.strptime(match.group(1), "%m/%d/%Y").date()
        return None

    @staticmethod
    def _tradable_symbol(value: str | None) -> str | None:
        if not value or not re.fullmatch(r"[A-Z][A-Z0-9.\-]{0,14}", value.upper()):
            return None
        return value.upper()

    @staticmethod
    def _classify_row(*, name: str | None, source_ticker: str | None) -> tuple[str, str]:
        text = " ".join(part for part in (name, source_ticker) if part).upper()
        if any(marker in text for marker in ("CASH", "PAYABLE", "RECEIVABLE")):
            return "cash", "cash"
        if any(marker in text for marker in (" OPTION", " FUTURE", " SWAP", " FORWARD", "NDX US ")):
            return "other", "derivative"
        if "FUND" in text or " ETF" in text:
            return "security", "fund"
        return "security", "equity"


