class IntechHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Intech's current fund-scoped daily holdings PDF from its ETF page."""

    PRODUCT_PAGE_URL = "https://www.intechetfs.com/intech-etfs/"
    _FUND_NAMES = {
        "LGDX": "Intech S&P Large Cap Diversified Alpha ETF",
        "SMDX": "Intech S&P Small-Mid Cap Diversified Alpha ETF",
    }
    _DAILY_PDF_RE = re.compile(
        r'data-ep-wrapper-link="\{&quot;url&quot;:&quot;'
        r'(?P<url>[^&"]*IntechETFs_(?P<symbol>LGDX|SMDX)-Holdings_[^&"]+\.pdf)'
        r"&quot;",
        re.IGNORECASE,
    )
    _PDF_ROW_RE = re.compile(
        r"^(?P<weekday>Mon|Tue|Wed|Thu|Fri|Sat|Sun)\s+"
        r"(?P<month>Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+"
        r"(?P<day>\d{1,2})\s+(?P<year>\d{4})\s+"
        r"(?P<account>[A-Z0-9.-]+)\s+(?P<ticker>\S+)\s+(?P<cusip>\S+)\s+"
        r"(?P<name>.*?)\s+(?P<shares>-?[\d,]+(?:\.\d+)?)\s+"
        r"(?P<price>-?[\d,]+(?:\.\d+)?)\s+(?P<market_value>-?[\d,]+(?:\.\d+)?)\s+"
        r"(?P<weight>-?[\d,]+(?:\.\d+)?)\s+(?P<net_assets>-?[\d,]+(?:\.\d+)?)\s+"
        r"(?P<shares_outstanding>-?[\d,]+(?:\.\d+)?)\s+"
        r"(?P<creation_units>-?[\d,]+(?:\.\d+)?)\s+(?P<money_market>[YN])$"
    )

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name, identifiers
        normalized_symbol = symbol.strip().upper()
        fund_name = self._FUND_NAMES.get(normalized_symbol)
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9000") if fund_name else Decimal("0.7000"),
            status="ready",
            reason=(
                "Intech publishes complete current daily holdings PDFs on its issuer-owned ETF page."
                if fund_name
                else "Intech publishes ETF holdings; the exact report is resolved from its ETF catalogue."
            ),
            source_url=self.PRODUCT_PAGE_URL,
            issuer_product_id=normalized_symbol or None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in self._FUND_NAMES:
            raise ValueError(f"No configured Intech ETF product route matches {normalized_symbol}.")
        product_page_url = source_url or self.PRODUCT_PAGE_URL
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            product_response = await self._get_with_timeout_retry(
                client,
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,*/*"),
            )
            product_response.raise_for_status()
            document_url = self._extract_daily_holdings_pdf_url(
                product_response.text,
                symbol=normalized_symbol,
            )
            if not document_url:
                raise ValueError(
                    f"Intech ETF page did not expose a current daily holdings PDF for {normalized_symbol}."
                )
            document_response = await self._get_with_timeout_retry(
                client,
                urljoin(str(product_response.url), document_url),
                headers=_holdings_request_headers(accept="application/pdf,*/*"),
            )
        document_response.raise_for_status()
        raw_text = self._extract_pdf_text(document_response.content)
        rows, composition_date = self._parse_daily_holdings_pdf(raw_text, symbol=normalized_symbol)
        if not rows:
            raise ValueError(f"Intech daily holdings PDF returned no rows for {normalized_symbol}.")
        return HoldingsFetchResult(
            rows=rows,
            raw_text=raw_text,
            raw_json={
                "source_format": "issuer_daily_holdings_pdf",
                "product_page_url": str(product_response.url),
            },
            source_url=str(document_response.url),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "pdf",
                "route_resolution": "issuer_product_page_current_daily_holdings_pdf",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    async def _get_with_timeout_retry(
        client: httpx.AsyncClient,
        url: str,
        *,
        headers: dict[str, str],
    ) -> httpx.Response:
        for attempt in range(3):
            try:
                return await client.get(url, headers=headers, follow_redirects=True)
            except httpx.TimeoutException:
                if attempt == 2:
                    raise
                await asyncio.sleep(0.25 * (attempt + 1))
        raise AssertionError("unreachable")

    @classmethod
    def _extract_daily_holdings_pdf_url(cls, raw_html: str, *, symbol: str) -> str | None:
        for match in cls._DAILY_PDF_RE.finditer(raw_html):
            if match.group("symbol").upper() != symbol:
                continue
            return html.unescape(match.group("url")).replace("\\/", "/")
        return None

    @staticmethod
    def _extract_pdf_text(raw_pdf: bytes) -> str:
        from pypdf import PdfReader  # noqa: PLC0415

        return "\n".join(page.extract_text() or "" for page in PdfReader(BytesIO(raw_pdf)).pages)

    @classmethod
    def _parse_daily_holdings_pdf(
        cls,
        raw_text: str,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for line in (line.strip() for line in raw_text.splitlines()):
            match = cls._PDF_ROW_RE.match(line)
            if not match or match.group("account").upper() != symbol:
                continue
            try:
                row_date = datetime.strptime(
                    " ".join((match.group("month"), match.group("day"), match.group("year"))),
                    "%b %d %Y",
                ).date()
            except ValueError:
                row_date = None
            if composition_date is None:
                composition_date = row_date
            is_cash = match.group("money_market").upper() == "Y"
            ticker = _clean(match.group("ticker"))
            cusip = _clean(match.group("cusip"))
            rows.append(
                CanonicalHoldingRow(
                    symbol=None if is_cash else ticker,
                    name=_clean(match.group("name")),
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    weight=_decimal(match.group("weight")),
                    shares=_decimal(match.group("shares")),
                    market_value=_decimal(match.group("market_value")),
                    currency="USD",
                    holding_type="cash" if is_cash else "equity",
                    row_type="cash" if is_cash else "security",
                    source_row_id=(
                        f"{symbol}:{len(rows) + 1}:{cusip or ticker or match.group('name')}"
                    ),
                    extra_data={
                        "source": "intech_current_daily_holdings_pdf",
                        "security_price": match.group("price"),
                        "net_assets": match.group("net_assets"),
                        "shares_outstanding": match.group("shares_outstanding"),
                        "creation_units": match.group("creation_units"),
                        "money_market_flag": match.group("money_market"),
                    },
                )
            )
        return rows, composition_date


class FrontierHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Frontier Asset's dated, fund-scoped daily ETF holdings export."""

    _FUNDS = {
        "FARX": ("absolute-return-etf", "Frontier Asset Absolute Return ETF"),
        "FCBD": ("core-bond-etf", "Frontier Asset Core Bond ETF"),
        "FGSM": ("global-small-cap-equity-etf", "Frontier Asset Global Small Cap Equity ETF"),
        "FINT": ("total-international-equity-etf", "Frontier Asset Total International Equity ETF"),
        "FLCE": ("us-large-cap-equity-etf", "Frontier Asset U.S. Large Cap Equity ETF"),
        "FOPC": ("opportunistic-credit-etf", "Frontier Asset Opportunistic Credit ETF"),
    }
    _PAGE_TEMPLATE = "https://funds.frontierasset.com/{slug}"
    _HOLDINGS_TEMPLATE = (
        "https://funds.frontierasset.com/assets/data/"
        "SEI_Frontier_Tradedate_Holdings_{date_code}.txt"
    )

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name, identifiers
        normalized_symbol = symbol.strip().upper()
        route = self._FUNDS.get(normalized_symbol)
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9000") if route else Decimal("0.7000"),
            status="ready",
            reason=(
                "Frontier Asset publishes a dated daily, fund-scoped holdings export."
                if route
                else "Frontier Asset publishes ETF holdings; the fund page determines the export scope."
            ),
            source_url=self._PAGE_TEMPLATE.format(slug=route[0]) if route else None,
            issuer_product_id=normalized_symbol or None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        route = self._FUNDS.get(normalized_symbol)
        if not route:
            raise ValueError(
                f"No configured Frontier Asset ETF product route matches {normalized_symbol}."
            )
        slug, expected_name = route
        product_page_url = source_url or self._PAGE_TEMPLATE.format(slug=slug)
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            product_response = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,*/*"),
                follow_redirects=True,
            )
            product_response.raise_for_status()
            self._validate_product_page(
                product_response.text,
                symbol=normalized_symbol,
                expected_name=expected_name,
            )
            for offset in range(15):
                report_date = date.today() - timedelta(days=offset)
                holdings_url = self._HOLDINGS_TEMPLATE.format(
                    date_code=report_date.strftime("%Y%m%d")
                )
                response = await client.get(
                    holdings_url,
                    headers=_holdings_request_headers(accept="text/plain,text/csv,*/*"),
                    follow_redirects=True,
                )
                if response.status_code == 404:
                    continue
                response.raise_for_status()
                rows, composition_date = self._parse_daily_holdings(
                    response.text,
                    symbol=normalized_symbol,
                )
                if not rows:
                    raise ValueError(
                        f"Frontier Asset daily holdings export contained no {normalized_symbol} rows."
                    )
                return HoldingsFetchResult(
                    rows=rows,
                    raw_text=response.text,
                    raw_json={
                        "source_format": "issuer_daily_pipe_delimited_holdings",
                        "product_page_url": str(product_response.url),
                    },
                    source_url=str(response.url),
                    source_identifier=normalized_symbol,
                    legal_metadata={
                        "source_access": self.config.source_access,
                        "source_provider": self.source_provider,
                        "adapter_key": self.adapter_key,
                        "source_format": "pipe_delimited_text",
                        "route_resolution": "frontier_dated_daily_fund_scoped_holdings_export",
                        "composition_date": composition_date.isoformat()
                        if composition_date
                        else None,
                        "as_of_date": composition_date.isoformat() if composition_date else None,
                        "terms_note": self.config.terms_note,
                    },
                )
        raise ValueError("Frontier Asset did not publish a holdings export in the last 15 days.")

    @staticmethod
    def _validate_product_page(raw_html: str, *, symbol: str, expected_name: str) -> None:
        ticker_match = re.search(r'data-ticker=["\'](?P<ticker>[^"\']+)["\']', raw_html, re.I)
        page_ticker = ticker_match.group("ticker").strip().upper() if ticker_match else None
        if page_ticker != symbol or expected_name.casefold() not in raw_html.casefold():
            raise ValueError(
                "Frontier Asset product page did not match the requested ETF identity."
            )

    @classmethod
    def _parse_daily_holdings(
        cls,
        raw_text: str,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for item in csv.DictReader(StringIO(raw_text), delimiter="|"):
            if _clean(item.get("fund_ticker")) != symbol:
                continue
            row_date = cls._parse_date(item.get("date"))
            if row_date and (composition_date is None or row_date > composition_date):
                composition_date = row_date
            name = _clean(item.get("security_description"))
            ticker = _clean(item.get("security_ticker"))
            cusip = _clean(item.get("security_cusip"))
            isin = _clean(item.get("security_isin"))
            sedol = _clean(item.get("security_sedol"))
            security_group = _clean(item.get("security_group"))
            security_type = _clean(item.get("security_type"))
            if not any([name, ticker, cusip, isin, sedol]):
                continue
            holding_type = cls._holding_type(
                security_group,
                security_type,
                name,
                ticker,
            )
            row_type = "cash" if holding_type == "cash" else "security"
            rows.append(
                CanonicalHoldingRow(
                    symbol=None if row_type == "cash" else ticker,
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    isin=isin if _looks_like_isin(isin) else None,
                    sedol=sedol if _looks_like_sedol(sedol) else None,
                    weight=_decimal_percent_points(item.get("percent_of_net_assets")),
                    shares=_decimal(item.get("quantity")),
                    market_value=_decimal(item.get("market_value")),
                    currency="USD",
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=(f"{symbol}:{len(rows) + 1}:{cusip or isin or ticker or name}"),
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _parse_date(value: str | None) -> date | None:
        text = _clean(value)
        if not text:
            return None
        try:
            return datetime.strptime(text, "%m/%d/%Y").date()
        except ValueError:
            return None

    @staticmethod
    def _holding_type(
        security_group: str | None,
        security_type: str | None,
        name: str | None,
        ticker: str | None,
    ) -> str:
        text = " ".join(
            part.upper() for part in (security_group, security_type, name, ticker) if part
        )
        if "CASH" in text or "MONEY MARKET" in text:
            return "cash"
        if any(term in text for term in ("BOND", "TREASURY", "FIXED INCOME")):
            return "fixed_income"
        if any(term in text for term in ("FUTURE", "OPTION", "SWAP", "FORWARD")):
            return "derivative"
        if "FUND" in text or "ETF" in text or "MUTUAL" in text:
            return "fund"
        return "equity"


class GooseHollowHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Goose Hollow's current holdings embedded in its issuer application script."""

    _PRODUCT_URL = "https://www.gham.co/"
    _HOLDINGS_SCRIPT_URL = "https://www.gham.co/assets/js/etf1_python.js"
    _FUNDS = {
        "GHTA": "Goose Hollow Tactical Allocation ETF",
    }
    _HOLDINGS_FRAGMENT_RE = re.compile(
        r"document\.getElementById\([\"']fund_holdings_table[\"']\)"
        r"\.innerHTML\s*\+=\s*[\"'](?P<fragment>(?:\\.|[^\"'])*)[\"'];",
        re.I | re.S,
    )

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name, identifiers
        normalized_symbol = symbol.strip().upper()
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9000") if normalized_symbol in self._FUNDS else Decimal("0.7000"),
            status="ready",
            reason=(
                "Goose Hollow publishes the current GHTA portfolio through its issuer application."
                if normalized_symbol in self._FUNDS
                else "Goose Hollow's public ETF application determines the portfolio scope."
            ),
            source_url=self._PRODUCT_URL if normalized_symbol in self._FUNDS else None,
            issuer_product_id=normalized_symbol or None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        expected_name = self._FUNDS.get(normalized_symbol)
        if expected_name is None:
            raise ValueError(
                f"No configured Goose Hollow ETF product route matches {normalized_symbol}."
            )
        product_page_url = source_url or self._PRODUCT_URL
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            product_response = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,*/*"),
                follow_redirects=True,
            )
            product_response.raise_for_status()
            self._validate_product_page(
                product_response.text,
                symbol=normalized_symbol,
                expected_name=expected_name,
            )
            script_response = await client.get(
                self._HOLDINGS_SCRIPT_URL,
                headers=_holdings_request_headers(
                    accept="application/javascript,text/javascript,*/*"
                ),
                follow_redirects=True,
            )
            script_response.raise_for_status()
        rows, composition_date = self._parse_holdings_script(script_response.text)
        if not rows:
            raise ValueError("Goose Hollow's public application returned no current holdings rows.")
        return HoldingsFetchResult(
            rows=rows,
            raw_text=script_response.text,
            raw_json={
                "source_format": "issuer_application_embedded_holdings_rows",
                "product_page_url": str(product_response.url),
            },
            source_url=str(script_response.url),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "javascript_embedded_html_rows",
                "route_resolution": "goose_hollow_issuer_application_holdings_script",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _validate_product_page(raw_html: str, *, symbol: str, expected_name: str) -> None:
        normalized_html = raw_html.casefold()
        if (
            symbol.casefold() not in normalized_html
            or expected_name.casefold() not in normalized_html
        ):
            raise ValueError("Goose Hollow product page did not match the requested ETF identity.")

    @classmethod
    def _parse_holdings_script(
        cls,
        raw_script: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        match = cls._HOLDINGS_FRAGMENT_RE.search(raw_script)
        if match is None:
            return [], None
        try:
            fragment = json.loads(f'"{match.group("fragment")}"')
        except json.JSONDecodeError as exc:
            raise ValueError(
                "Goose Hollow holdings script contains an invalid HTML fragment."
            ) from exc

        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for source_index, raw_row in enumerate(
            re.findall(r"<tr[^>]*>(.*?)</tr>", fragment, re.I | re.S),
            start=1,
        ):
            cells = [
                _clean(html.unescape(re.sub(r"<[^>]+>", "", cell)))
                for cell in re.findall(r"<td[^>]*>(.*?)</td>", raw_row, re.I | re.S)
            ]
            if len(cells) != 7:
                continue
            as_of, name, ticker, cusip, market_value, shares, weight = cells
            row_date = cls._parse_date(as_of)
            if row_date and (composition_date is None or row_date > composition_date):
                composition_date = row_date
            if not any([name, ticker, cusip, market_value, shares, weight]):
                continue
            holding_type = cls._holding_type(name=name, ticker=ticker)
            row_type = "cash" if holding_type == "cash" else "security"
            rows.append(
                CanonicalHoldingRow(
                    symbol=None if row_type == "cash" else ticker,
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    weight=_decimal(weight),
                    shares=_decimal(shares),
                    market_value=_decimal(market_value),
                    currency="USD",
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=f"GHTA:{source_index}:{cusip or ticker or name}",
                    extra_data={
                        "as_of_date": as_of,
                        "source_name": name,
                        "source_ticker": ticker,
                        "source_cusip": cusip,
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _parse_date(value: str | None) -> date | None:
        text = _clean(value)
        if not text:
            return None
        try:
            return datetime.strptime(text, "%Y-%m-%d").date()
        except ValueError:
            return None

    @staticmethod
    def _holding_type(*, name: str | None, ticker: str | None) -> str:
        text = " ".join(part.upper() for part in (name, ticker) if part)
        if "CASH" in text or "MONEY MARKET" in text:
            return "cash"
        if any(term in text for term in (" OPTION", " FUTURE", " SWAP", " FORWARD")) or re.search(
            r"\b[CP]\d+(?:\.\d+)?$",
            text,
        ):
            return "derivative"
        if "ETF" in text or "FUND" in text:
            return "fund"
        return "equity"


class GqgHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch GQG ETF holdings from the issuer's daily FilePoint export."""

    DAILY_HOLDINGS_TEMPLATE = (
        "https://gqg.filepoint.live/assets/data/" "SEI_GQG_Tradedate_Holdings_{report_date}.txt"
    )
    MAX_LOOKBACK_DAYS = 10

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name, identifiers
        normalized_symbol = symbol.strip().upper()
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9000"),
            status="ready" if normalized_symbol else "needs_issuer_route",
            reason=(
                "GQG publishes daily ETF holdings through its issuer-native FilePoint export."
                if normalized_symbol
                else "GQG holdings require an ETF symbol."
            ),
            source_url=(
                self.DAILY_HOLDINGS_TEMPLATE.format(report_date=date.today().strftime("%m%d%Y"))
                if normalized_symbol
                else None
            ),
            issuer_product_id=normalized_symbol or None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            raise ValueError("GQG holdings require an ETF symbol.")
        if source_url:
            return await self._fetch_daily_export(symbol=normalized_symbol, source_url=source_url)

        last_error: httpx.HTTPStatusError | None = None
        for offset in range(self.MAX_LOOKBACK_DAYS):
            report_date = date.today() - timedelta(days=offset)
            try:
                return await self.fetch_for_date(
                    symbol=normalized_symbol,
                    requested_date=report_date,
                )
            except httpx.HTTPStatusError as exc:
                if exc.response.status_code != 404:
                    raise
                last_error = exc
        if last_error is not None:
            raise last_error
        raise ValueError(f"GQG daily holdings export was unavailable for {normalized_symbol}.")

    async def fetch_for_date(
        self,
        *,
        symbol: str,
        requested_date: date,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            raise ValueError("GQG holdings require an ETF symbol.")
        daily_holdings_url = source_url or self.DAILY_HOLDINGS_TEMPLATE.format(
            report_date=requested_date.strftime("%m%d%Y")
        )
        return await self._fetch_daily_export(
            symbol=normalized_symbol, source_url=daily_holdings_url
        )

    async def _fetch_daily_export(self, *, symbol: str, source_url: str) -> HoldingsFetchResult:
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                source_url,
                headers=_holdings_request_headers(accept="text/plain,text/csv,*/*"),
                follow_redirects=True,
            )
        response.raise_for_status()
        rows, composition_date = self._parse_daily_holdings_export(response.text, symbol=symbol)
        if not rows:
            raise ValueError(f"GQG daily holdings export returned no rows for {symbol}.")
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json={"source_format": "issuer_daily_holdings_pipe_delimited"},
            source_url=str(response.url),
            source_identifier=symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "pipe_delimited",
                "route_resolution": "issuer_dated_daily_holdings_export",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _parse_daily_holdings_export(
        payload: str,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        reader = csv.DictReader(StringIO(payload), delimiter="|")
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for index, source_row in enumerate(reader):
            fund_ticker = (_clean(source_row.get("fund_ticker")) or "").upper()
            if fund_ticker != symbol:
                continue
            source_date = _clean(source_row.get("date"))
            if composition_date is None and source_date:
                try:
                    composition_date = datetime.strptime(source_date, "%m/%d/%Y").date()
                except ValueError:
                    pass
            security_group = (_clean(source_row.get("security_group")) or "").lower()
            security_type = (_clean(source_row.get("security_type")) or "").lower()
            description = _clean(source_row.get("security_description"))
            is_cash = "cash" in security_group or "cash" in security_type or description == "Cash"
            ticker = _clean(source_row.get("security_ticker"))
            identifier = _clean(source_row.get("security_cusip"))
            rows.append(
                CanonicalHoldingRow(
                    symbol=None if is_cash else ticker,
                    name=description,
                    cusip=identifier if _looks_like_cusip(identifier) else None,
                    isin=_clean(source_row.get("security_isin")),
                    sedol=_clean(source_row.get("security_sedol")),
                    weight=_decimal_percent_points(source_row.get("percent_of_net_assets")),
                    shares=_decimal(source_row.get("quantity")),
                    market_value=_decimal(source_row.get("market_value")),
                    holding_type="cash" if is_cash else "equity",
                    row_type="cash" if is_cash else "security",
                    source_row_id=f"{symbol}:{index}:{identifier or ticker or description or 'holding'}",
                    extra_data={
                        **{
                            key: value
                            for key, value in source_row.items()
                            if key is not None and _clean(value) is not None
                        },
                        "source": "gqg_filepoint_daily_holdings_export",
                    },
                )
            )
        return rows, composition_date


