class NightviewHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Nightview's NITE portfolio from its issuer-declared daily CSV."""

    _ROUTES = {
        "NITE": (
            "The Nightview Fund",
            "https://www.nightviewfund.com/",
            "https://www.nightviewfund.com/live_site_data/daily/NITE_fund_holdings.csv",
        ),
    }

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name
        normalized_symbol = symbol.strip().upper()
        route = self._ROUTES.get(normalized_symbol)
        has_sec_fallback = bool(_identifier(identifiers, "sec_cik", "cik"))
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500") if route else Decimal("0.3000"),
            status="ready" if route or has_sec_fallback else "needs_issuer_route",
            reason=(
                "Nightview publishes this ETF's complete current holdings CSV from its public fund page."
                if route
                else "No verified Nightview native holdings route is configured for this ETF; "
                "SEC EDGAR remains available as fallback."
                if has_sec_fallback
                else "No verified Nightview native holdings route is configured for this ETF."
            ),
            source_url=route[1] if route else None,
            issuer_product_id=normalized_symbol or None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        route = self._ROUTES.get(normalized_symbol)
        if route is None:
            raise ValueError(
                f"No verified Nightview native holdings route is configured for "
                f"{normalized_symbol or 'an empty symbol'}."
            )
        expected_fund_name, product_page_url, holdings_csv_url = route
        if source_url and source_url.rstrip("/") not in {
            product_page_url.rstrip("/"),
            holdings_csv_url.rstrip("/"),
        }:
            raise ValueError("Nightview holdings must use its official fund page or declared CSV.")

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            page_response = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*"),
                follow_redirects=True,
            )
            page_response.raise_for_status()
            self._validate_product_page(
                page_response.text,
                symbol=normalized_symbol,
                expected_fund_name=expected_fund_name,
                holdings_csv_url=holdings_csv_url,
            )
            holdings_response = await client.get(
                holdings_csv_url,
                headers=_holdings_request_headers(accept="text/csv,text/plain,*/*"),
                follow_redirects=True,
            )
            holdings_response.raise_for_status()

        rows, composition_date = self._parse_holdings_csv(
            holdings_response.text, symbol=normalized_symbol
        )
        if not rows:
            raise ValueError(
                f"Nightview's official {normalized_symbol} holdings CSV returned no portfolio rows."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=holdings_response.text,
            raw_json={
                "source_format": "issuer_product_page_declared_daily_holdings_csv",
                "row_count": len(rows),
            },
            source_url=str(holdings_response.url),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "nightview_product_page_declared_daily_holdings_csv",
                "product_page_url": str(page_response.url),
                "snapshot_provenance": "nightview_native_current_holdings_csv",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _validate_product_page(
        raw_html: str,
        *,
        symbol: str,
        expected_fund_name: str,
        holdings_csv_url: str,
    ) -> None:
        normalized_html = html.unescape(raw_html)
        if (
            expected_fund_name.lower() not in normalized_html.lower()
            or not re.search(rf"\b{re.escape(symbol)}\b", normalized_html, flags=re.IGNORECASE)
            or urlparse(holdings_csv_url).path not in normalized_html
        ):
            raise ValueError(
                "Nightview's official fund page did not declare its complete daily holdings CSV."
            )

    @staticmethod
    def _parse_holdings_csv(
        raw_csv: str, *, symbol: str
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        reader = csv.DictReader(StringIO(raw_csv))
        required_headers = {
            "SecurityDescription",
            "Report Date",
            "Sector",
            "Segment",
            "Category",
            "NetAssetsPercentage",
            "NetAssetsPercentageTimes100",
        }
        if not required_headers.issubset(set(reader.fieldnames or [])):
            return [], None

        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for index, raw in enumerate(reader, start=1):
            name = _clean(raw.get("SecurityDescription"))
            if name is None:
                continue
            source_date = _parse_issuer_date(raw.get("Report Date"))
            if source_date:
                composition_date = (
                    max(composition_date, source_date) if composition_date else source_date
                )
            source_text = " ".join(
                value.upper()
                for value in (name, _clean(raw.get("Segment")), _clean(raw.get("Category")))
                if value
            )
            is_cash = "CURRENCY" in source_text or name.upper() in {"US DOLLARS", "CASH"}
            rows.append(
                CanonicalHoldingRow(
                    # This issuer artifact deliberately contains names, not exchange symbols.
                    # Existing provider/identifier reconciliation decides whether a name can be
                    # safely materialized instead of manufacturing a ticker from display text.
                    symbol=None,
                    name=name,
                    weight=_decimal(raw.get("NetAssetsPercentage")),
                    currency="USD" if is_cash else None,
                    holding_type="cash" if is_cash else "equity",
                    row_type="cash" if is_cash else "security",
                    source_row_id=f"nightview-{symbol}-{index}",
                    extra_data={
                        key: value
                        for key, value in raw.items()
                        if key and _clean(value) is not None
                    },
                )
            )
        return rows, composition_date


class AcuitasHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Acuitas' public daily ETF holdings export."""

    DAILY_HOLDINGS_URL = (
        "https://phpstack-1541365-5956782.cloudwaysapps.com/" "Acuitas_WEB.40B6.B6_ETF_Holdings.csv"
    )

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name, identifiers
        normalized_symbol = symbol.strip().upper()
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9000"),
            status="ready" if normalized_symbol else "needs_issuer_route",
            reason=(
                "Acuitas publishes a complete daily ETF holdings CSV."
                if normalized_symbol
                else "Acuitas holdings require an ETF symbol."
            ),
            source_url=self.DAILY_HOLDINGS_URL if normalized_symbol else None,
            issuer_product_id=normalized_symbol or None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            raise ValueError("Acuitas holdings require an ETF symbol.")
        resolved_source_url = source_url or self.DAILY_HOLDINGS_URL
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                resolved_source_url,
                headers=_holdings_request_headers(accept="text/csv,text/plain,*/*"),
                follow_redirects=True,
            )
        response.raise_for_status()
        rows, composition_date = self._parse_daily_holdings_csv(
            response.text, symbol=normalized_symbol
        )
        if not rows:
            raise ValueError(
                f"Acuitas daily holdings CSV did not contain holdings for {normalized_symbol}."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json={"source_format": "issuer_daily_holdings_csv"},
            source_url=str(response.url),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "issuer_daily_holdings_csv",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _parse_daily_holdings_csv(
        payload: str,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        reader = csv.DictReader(StringIO(payload))
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for index, source_row in enumerate(reader):
            account = (_clean(source_row.get("Account")) or "").upper()
            if account != symbol:
                continue
            source_date = _clean(source_row.get("Date"))
            if composition_date is None and source_date:
                try:
                    composition_date = datetime.strptime(source_date, "%m/%d/%Y").date()
                except ValueError:
                    pass
            ticker = _clean(source_row.get("StockTicker"))
            name = _clean(source_row.get("SecurityName"))
            cash_flag = (_clean(source_row.get("MoneyMarketFlag")) or "").lower()
            is_cash = cash_flag in {"y", "yes", "true", "1"} or (
                not ticker and "cash" in (name or "").lower()
            )
            cusip = _clean(source_row.get("CUSIP"))
            rows.append(
                CanonicalHoldingRow(
                    symbol=None if is_cash else ticker,
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    # Acuitas publishes an explicit percent sign (for example, 0.23%),
                    # so _decimal already returns its canonical fractional weight.
                    weight=_decimal(source_row.get("Weightings")),
                    shares=_decimal(source_row.get("Shares")),
                    market_value=_decimal(source_row.get("MarketValue")),
                    holding_type="cash" if is_cash else "equity",
                    row_type="cash" if is_cash else "security",
                    source_row_id=f"{symbol}:{index}:{cusip or ticker or name or 'holding'}",
                    extra_data={
                        **{
                            key: value
                            for key, value in source_row.items()
                            if key is not None and _clean(value) is not None
                        },
                        "source": "acuitas_daily_holdings_csv",
                    },
                )
            )
        return rows, composition_date


