            is_derivative = bool(re.search(r"\b(?:FUT|FUTURE|OPTION|CALL|PUT)\b", text))
            is_fixed_income = any(marker in text for marker in ("TREASURY", "BILL", "BOND", "NOTE"))
            ticker = (source_symbol or "").upper()
