class CorgiHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Corgi's complete current ETF portfolio through its public fund API."""

    product_page_template = "https://corgifunds.com/{symbol_lower}"
    holdings_api_template = "https://corgifunds.com/api/data/holdings?ticker={symbol_upper}"

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name
        normalized_symbol = symbol.strip().upper()
        source_url = self.resolve_source_url(
            symbol=normalized_symbol,
            issuer_product_id=_identifier(identifiers, "issuer_product_id", "product_id"),
            source_url=_identifier(identifiers, *self.source_url_aliases),
            identifiers=identifiers,
        )
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9000") if source_url else Decimal("0.5000"),
            status="ready" if source_url else "needs_issuer_route",
            reason=(
                "Corgi publishes complete current ETF holdings through its public fund API."
                if source_url
                else "Corgi needs an ETF symbol to resolve its public fund page."
            ),
            source_url=source_url,
            issuer_product_id=normalized_symbol or None,
        )

    def resolve_source_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        del identifiers
        if source_url and "corgifunds.com" in source_url.lower():
            return source_url.strip()
        resolved_symbol = (issuer_product_id or symbol).strip().lower()
        return (
            self.product_page_template.format(symbol_lower=resolved_symbol)
            if resolved_symbol
            else None
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        product_page_url = self.resolve_source_url(
            symbol=normalized_symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        if not product_page_url:
            raise ValueError("Corgi holdings require an ETF symbol or public product page.")
        api_url = self.holdings_api_template.format(symbol_upper=normalized_symbol)
        page_headers = _issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*")
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            product_response = await client.get(
                product_page_url,
                headers=page_headers,
                follow_redirects=True,
            )
            product_response.raise_for_status()
            self._validate_product_page(product_response.text, symbol=normalized_symbol)
            holdings_response = await client.get(
                api_url,
                headers={
                    **_holdings_request_headers(accept="application/json,*/*"),
                    "Referer": str(product_response.url),
                },
                follow_redirects=True,
            )
            holdings_response.raise_for_status()
        payload = holdings_response.json()
        rows, composition_date = self._parse_holdings_payload(payload, symbol=normalized_symbol)
        if not rows:
            raise ValueError(
                f"Corgi holdings API returned no complete rows for {normalized_symbol}."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=holdings_response.text,
            raw_json={"holdings": payload} if isinstance(payload, list) else {"payload": payload},
            source_url=str(holdings_response.url),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "json",
                "route_resolution": "corgi_public_fund_holdings_api",
                "product_page_url": str(product_response.url),
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _validate_product_page(raw_html: str, *, symbol: str) -> None:
        if not re.search(rf"\b{re.escape(symbol)}\b", raw_html, re.IGNORECASE):
            raise ValueError(f"Corgi product page identity did not match requested ETF {symbol}.")

    @staticmethod
    def _parse_holdings_payload(
        payload: Any,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        if not isinstance(payload, list):
            return [], None
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for index, raw in enumerate(payload, start=1):
            if not isinstance(raw, dict):
                continue
            name = _clean(raw.get("security_name"))
            ticker = _clean(raw.get("security_ticker"))
            cusip = _clean(raw.get("security_cusip"))
            row_date = _clean(raw.get("position_date"))
            if row_date:
                try:
                    parsed = datetime.fromisoformat(row_date.replace("Z", "+00:00")).date()
                    if composition_date is None or parsed > composition_date:
                        composition_date = parsed
                except ValueError:
                    pass
            haystack = " ".join(part.lower() for part in (ticker, name, cusip) if part)
            is_cash = any(
                marker in haystack for marker in ("cash", "currency", "government obligations fund")
            )
            is_fixed_income = any(
                marker in haystack for marker in ("treasury bill", "bond", "note", "debt")
            )
            is_derivative = any(marker in haystack for marker in ("swap", "option", "future"))
            ticker_is_identifier = bool(ticker and cusip and ticker.upper() == cusip.upper())
            if not any([ticker, name, cusip, raw.get("market_value")]):
                continue
            rows.append(
                CanonicalHoldingRow(
                    symbol=(
                        None
                        if is_cash or is_fixed_income or is_derivative or ticker_is_identifier
                        else (ticker.upper() if ticker else None)
                    ),
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    weight=_decimal_percent_points(raw.get("weight_pct")),
                    shares=_decimal(raw.get("shares")),
                    market_value=_decimal(raw.get("market_value")),
                    currency="USD" if is_cash else None,
                    holding_type=(
                        "cash"
                        if is_cash
                        else (
                            "fixed_income"
                            if is_fixed_income
                            else ("derivative" if is_derivative else "equity")
                        )
                    ),
                    row_type="cash" if is_cash else "security",
                    source_row_id=f"{symbol}:{index}:{cusip or ticker or name or 'holding'}",
                    extra_data={
                        key: value for key, value in raw.items() if value not in (None, "")
                    },
                )
            )
        return rows, composition_date


class ConvergenceHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Convergence's current CLSE full-holdings CSV from its ETF page."""

    product_page_url = "https://www.investcip.com/etfstrategies.html"

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name, identifiers
        normalized_symbol = symbol.strip().upper()
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9000") if normalized_symbol == "CLSE" else Decimal("0.5000"),
            status="ready",
            reason=(
                "Convergence publishes CLSE's complete current holdings CSV from its public ETF page."
                if normalized_symbol == "CLSE"
                else "Convergence is configured; its currently verified public holdings route is CLSE."
            ),
            source_url=self.product_page_url,
            issuer_product_id=normalized_symbol or None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol != "CLSE":
            raise ValueError(
                "Convergence's verified public holdings route is currently limited to CLSE."
            )
        page_url = (
            source_url if source_url and "investcip.com" in source_url else self.product_page_url
        )
        page_headers = _issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*")
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            page_response = await client.get(page_url, headers=page_headers, follow_redirects=True)
            page_response.raise_for_status()
            csv_url = self._extract_holdings_csv_url(
                page_response.text,
                symbol=normalized_symbol,
                page_url=str(page_response.url),
            )
            csv_response = await client.get(
                csv_url,
                headers={
                    **_holdings_request_headers(accept="text/csv,application/octet-stream,*/*"),
                    "Referer": str(page_response.url),
                },
                follow_redirects=True,
            )
            csv_response.raise_for_status()
        rows, composition_date = self._parse_holdings_csv(
            csv_response.text, symbol=normalized_symbol
        )
        if not rows:
            raise ValueError("Convergence holdings CSV returned no complete rows for CLSE.")
        return HoldingsFetchResult(
            rows=rows,
            raw_text=csv_response.text,
            raw_json={"source_format": "csv", "row_count": len(rows)},
            source_url=str(csv_response.url),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "convergence_product_page_linked_holdings_csv",
                "product_page_url": str(page_response.url),
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _extract_holdings_csv_url(raw_html: str, *, symbol: str, page_url: str) -> str:
        if not re.search(rf"\b{re.escape(symbol)}\b", raw_html, re.IGNORECASE):
            raise ValueError(
                f"Convergence product page identity did not match requested ETF {symbol}."
            )
        match = re.search(
            rf"""href=["'](?P<url>[^"']*{re.escape(symbol)}Holdings\.csv)["']""",
            raw_html,
            re.IGNORECASE,
        )
        if match is None:
            raise ValueError(
                f"Convergence product page did not expose a complete CSV for {symbol}."
            )
        return urljoin(page_url, html.unescape(match.group("url")).strip())

    @staticmethod
    def _parse_holdings_csv(
        raw_csv: str, *, symbol: str
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for index, raw in enumerate(csv.DictReader(StringIO(raw_csv.strip())), start=1):
            ticker = _clean(raw.get("Ticker"))
            name = _clean(raw.get("Name"))
            cusip = _clean(raw.get("Cusip"))
            row_date = _clean(raw.get("Date"))
            if row_date:
                try:
                    parsed = datetime.strptime(row_date, "%m/%d/%Y").date()
                    if composition_date is None or parsed > composition_date:
                        composition_date = parsed
                except ValueError:
                    pass
            haystack = " ".join(part.lower() for part in (ticker, name) if part)
            is_cash = any(marker in haystack for marker in ("cash", "other assets", "liabilities"))
            is_short = _decimal(raw.get("Percent")) is not None and _decimal(raw.get("Percent")) < 0
            if not any([ticker, name, cusip, raw.get("MarketValue")]):
                continue
            rows.append(
                CanonicalHoldingRow(
                    symbol=None if is_cash else (ticker.upper() if ticker else None),
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    weight=_decimal(raw.get("Percent")),
                    shares=_decimal(raw.get("Units")),
                    market_value=_decimal(raw.get("MarketValue")),
                    currency="USD" if is_cash else None,
                    holding_type="cash" if is_cash else "equity",
                    row_type="cash" if is_cash else "security",
                    source_row_id=f"{symbol}:{index}:{cusip or ticker or name or 'holding'}",
                    extra_data={
                        **{key: value for key, value in raw.items() if value not in (None, "")},
                        "position_side": "short" if is_short else "long",
                    },
                )
            )
        return rows, composition_date


class DhandhoHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch the Pabrai Wagons ETF's issuer-published complete holdings PDF."""

    resources_url = "https://www.wagonsetf.com/ir"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        if symbol.strip().upper() != "WAGN":
            raise ValueError(
                "Dhandho's verified issuer-native holdings route currently supports WAGN."
            )
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            page = await client.get(
                source_url or self.resources_url,
                headers=_issuer_page_request_headers(accept="text/html,*/*"),
                follow_redirects=True,
            )
            page.raise_for_status()
            match = re.search(
                r'href=["\'](?P<url>[^"\']+\.pdf)["\'][^>]*>Complete Holdings\s*-\s*(?P<date>[^<]+)<',
                page.text,
                re.IGNORECASE,
            )
            if match is None:
                raise ValueError("Pabrai Wagons did not expose a complete holdings PDF.")
            pdf = await client.get(
                urljoin(str(page.url), html.unescape(match.group("url"))),
                headers=_holdings_request_headers(accept="application/pdf,*/*"),
                follow_redirects=True,
            )
            pdf.raise_for_status()
        rows, composition_date = self._parse_holdings_pdf(pdf.content)
        if not rows:
            raise ValueError(
                "Pabrai Wagons complete holdings PDF contained no parseable positions."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text="\n".join(row.name or "" for row in rows),
            raw_json={"source_format": "pdf"},
            source_url=str(pdf.url),
            source_identifier="WAGN",
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "pdf",
                "route_resolution": "issuer_resources_latest_complete_holdings_pdf",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "refresh_frequency": "periodic_issuer_report",
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _parse_holdings_pdf(raw_pdf: bytes) -> tuple[list[CanonicalHoldingRow], date | None]:
        from pypdf import PdfReader  # noqa: PLC0415

        text = "\n".join(page.extract_text() or "" for page in PdfReader(BytesIO(raw_pdf)).pages)
        return DhandhoHoldingsAdapter._parse_holdings_text(text)

    @staticmethod
    def _parse_holdings_text(text: str) -> tuple[list[CanonicalHoldingRow], date | None]:
        date_match = re.search(r"Schedule of Investments\s+([A-Z][a-z]+ \d{1,2}, \d{4})", text)
        composition_date = (
            datetime.strptime(date_match.group(1), "%B %d, %Y").date() if date_match else None
        )
        row_re = re.compile(
            r"^(?P<name>(?!TOTAL |Total |Liabilities )[A-Za-z].*?)\s+(?P<shares>[\d,]+)\s+(?:\$\s*)?(?P<value>[\d,]+)$"
        )
        rows: list[CanonicalHoldingRow] = []
        for line in (item.strip() for item in text.splitlines()):
            match = row_re.match(line)
            if match is None:
                continue
            name = match.group("name").strip()
            is_cash = "money market" in name.lower() or "treasury obligations" in name.lower()
            rows.append(
                CanonicalHoldingRow(
                    symbol=None,
                    name=name,
                    shares=_decimal(match.group("shares")),
                    market_value=_decimal(match.group("value")),
                    holding_type="cash" if is_cash else "equity",
                    row_type="cash" if is_cash else "security",
                    source_row_id=f"WAGN:{len(rows) + 1}",
                    extra_data={"source": "dhandho_complete_holdings_pdf"},
                )
            )
        return rows, composition_date


class WaterIslandHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch AltShares' issuer-published periodic portfolio-of-investments report."""

    PRODUCT_PAGE_URLS = {
        "ARB": "https://www.altsharesetfs.com/arb",
        "EVNT": "https://www.altsharesetfs.com/evnt",
    }
    FUND_NAMES = {
        "ARB": "AltShares Merger Arbitrage ETF",
        "EVNT": "AltShares Event-Driven ETF",
    }
    HOLDINGS_URL = "https://altshares.s3.amazonaws.com/filings/Quarterly_Holdings-Fiscal_Q3.pdf"
    _POSITION_RE = re.compile(
        r"(?P<name>[A-Z][^\n$]*?)\s{2,}(?P<shares>\(?[\d,]+\)?)\s+(?:\$\s*)?"
        r"(?P<value>\(?[\d,]+\)?)\s*(?=$|[A-Z])"
    )
    _CATEGORY_PREFIX_RE = re.compile(
        r"^(?:[A-Za-z&/\- ]+\s+-\s+\(?-?\d+(?:\.\d+)?%\)?(?:\s+\(Continued\))?\s*)+"
    )

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name
        normalized_symbol = symbol.strip().upper()
        product_page_url = self.PRODUCT_PAGE_URLS.get(normalized_symbol)
        has_sec_fallback = bool(_identifier(identifiers, "sec_cik", "cik"))
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9000") if product_page_url else Decimal("0.5000"),
            status="ready" if product_page_url or has_sec_fallback else "needs_issuer_route",
            reason=(
                "AltShares publishes this ETF's complete periodic portfolio-of-investments report."
                if product_page_url
                else "No verified AltShares ETF portfolio-report route is configured for this symbol; SEC EDGAR fallback is available."
                if has_sec_fallback
                else "No verified AltShares ETF portfolio-report route is configured for this symbol."
            ),
            source_url=product_page_url,
            issuer_product_id=normalized_symbol or None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        product_page_url = self.PRODUCT_PAGE_URLS.get(normalized_symbol)
        fund_name = self.FUND_NAMES.get(normalized_symbol)
        if product_page_url is None or fund_name is None:
            raise ValueError(
                f"No verified AltShares ETF portfolio-report route is configured for {normalized_symbol}."
            )
        report_url = (
            source_url
            if source_url and "altshares.s3.amazonaws.com" in source_url
            else self.HOLDINGS_URL
        )
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            product_page = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*"),
                follow_redirects=True,
            )
            product_page.raise_for_status()
            if normalized_symbol not in product_page.text.upper():
                raise ValueError(
                    f"AltShares product page identity did not match requested ETF {normalized_symbol}."
                )
            report = await client.get(
                report_url,
                headers=_holdings_request_headers(accept="application/pdf,*/*"),
                follow_redirects=True,
            )
            report.raise_for_status()
        rows, composition_date = self._parse_holdings_pdf(report.content, fund_name=fund_name)
        if not rows:
            raise ValueError(
                f"AltShares portfolio report contained no parseable positions for {normalized_symbol}."
            )
        for index, row in enumerate(rows, start=1):
            row.source_row_id = (
                f"{normalized_symbol}:{composition_date.isoformat() if composition_date else 'unknown'}:"
                f"{index}:{row.name or 'holding'}"
            )
            row.extra_data = {
                **row.extra_data,
                "source": "altshares_periodic_portfolio_of_investments_pdf",
            }
        return HoldingsFetchResult(
            rows=rows,
            raw_text="\n".join(row.name or "" for row in rows),
            raw_json={"source_format": "pdf", "fund_name": fund_name, "row_count": len(rows)},
            source_url=str(report.url),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "pdf",
                "route_resolution": "altshares_periodic_complete_portfolio_report",
                "product_page_url": str(product_page.url),
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "refresh_frequency": "periodic_issuer_report",
                "terms_note": self.config.terms_note,
            },
        )

    @classmethod
    def _parse_holdings_pdf(
        cls,
        raw_pdf: bytes,
        *,
        fund_name: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        from pypdf import PdfReader  # noqa: PLC0415

        text = "\n".join(
            page.extract_text() or ""
            for page in PdfReader(BytesIO(raw_pdf)).pages
            if fund_name.lower() in (page.extract_text() or "").lower()
        )
        return cls._parse_holdings_text(text, fund_name=fund_name)

    @classmethod
    def _parse_holdings_text(
        cls,
        text: str,
        *,
        fund_name: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        date_match = re.search(
            rf"{re.escape(fund_name)}\s+Portfolio of Investments\s+([A-Z][a-z]+ \d{{1,2}}, \d{{4}})",
            text,
        )
        composition_date = (
            datetime.strptime(date_match.group(1), "%B %d, %Y").date() if date_match else None
        )
        net_assets_matches = re.findall(r"NET ASSETS\s*-\s*100\.00%\s*\$?\s*([\d,]+)", text)
        net_assets = _decimal(net_assets_matches[0]) if net_assets_matches else None
        rows: list[CanonicalHoldingRow] = []
        is_short_section = False
        for raw_line in text.splitlines():
            line = raw_line.strip()
            if not line:
                continue
            if "SCHEDULE OF SECURITIES SOLD SHORT" in line.upper():
                is_short_section = True
                continue
            if line.upper().startswith(("TOTAL ", "NET ASSETS", "PORTFOLIO FOOTNOTES")):
                continue
            for match in cls._POSITION_RE.finditer(line):
                raw_name = cls._CATEGORY_PREFIX_RE.sub("", match.group("name")).strip()
                name = raw_name
                name = re.sub(r"^Money Market Funds\s+", "", name, flags=re.IGNORECASE)
                name = re.sub(r"\([a-z]\)$", "", name).strip()
                shares = _decimal(match.group("shares"))
                market_value = _decimal(match.group("value"))
                if not name or shares is None or market_value is None:
                    continue
                is_cash = "money market" in raw_name.lower() or "cash" in raw_name.lower()
                is_short = is_short_section or shares < 0 or market_value < 0
                rows.append(
                    CanonicalHoldingRow(
                        name=name,
                        shares=shares,
                        market_value=market_value,
                        weight=(market_value / net_assets if net_assets else None),
                        currency="USD",
                        holding_type="cash" if is_cash else "equity",
                        row_type="cash" if is_cash else "security",
                        extra_data={"position_side": "short" if is_short else "long"},
                    )
                )
        return rows, composition_date


class CanaryHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Canary Capital's issuer-owned current holdings table for each ETF."""

    PRODUCT_PAGE_TEMPLATE = "https://canaryetfs.com/{symbol_lower}/"
    _REQUIRED_HEADERS = {
        "date",
        "account",
        "name",
        "ticker",
        "quantity",
        "market value",
        "weightings",
    }

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name
        normalized_symbol = symbol.strip().upper()
        has_sec_fallback = bool(_identifier(identifiers, "sec_cik", "cik"))
        product_page_url = self.PRODUCT_PAGE_TEMPLATE.format(symbol_lower=normalized_symbol.lower())
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9000") if normalized_symbol else Decimal("0.5000"),
            status="ready" if normalized_symbol or has_sec_fallback else "needs_issuer_route",
            reason=(
                "Canary Capital publishes this ETF's current holdings in its issuer-owned product table."
                if normalized_symbol
                else "No Canary ETF symbol was supplied; SEC EDGAR fallback is available."
                if has_sec_fallback
                else "No Canary ETF symbol was supplied."
            ),
            source_url=product_page_url if normalized_symbol else None,
            issuer_product_id=normalized_symbol or None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            raise ValueError("Canary holdings require an ETF symbol.")
        product_page_url = source_url or self.PRODUCT_PAGE_TEMPLATE.format(
            symbol_lower=normalized_symbol.lower()
        )
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*"),
                follow_redirects=True,
            )
        if response.status_code == 403:
            fallback_response = await asyncio.to_thread(
                requests.get,
                product_page_url,
                headers={
                    **_issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*"),
                    "User-Agent": "curl/8.0",
                },
                timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS,
                allow_redirects=True,
            )
            fallback_response.raise_for_status()
            raw_html = fallback_response.text
            resolved_url = str(fallback_response.url)
        else:
            response.raise_for_status()
            raw_html = response.text
            resolved_url = str(response.url)
        rows, composition_date = self._parse_product_page(raw_html, symbol=normalized_symbol)
        if not rows:
            raise ValueError(
                f"Canary product page contained no current holdings rows for {normalized_symbol}."
            )
        for index, row in enumerate(rows, start=1):
            row.source_row_id = f"{normalized_symbol}:{composition_date or 'unknown'}:{index}"
            row.extra_data = {
                **row.extra_data,
                "source": "canary_product_page_current_holdings_table",
            }
        return HoldingsFetchResult(
            rows=rows,
            raw_text=raw_html,
            raw_json={"source_format": "html_table", "row_count": len(rows)},
            source_url=resolved_url,
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "html_table",
                "route_resolution": "canary_product_page_current_holdings_table",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "refresh_frequency": "issuer_current_product_page",
                "terms_note": self.config.terms_note,
            },
        )

    @classmethod
    def _parse_product_page(
        cls,
        raw_html: str,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        parser = _HTMLTablesParser()
        parser.feed(raw_html)
        normalized_symbol = symbol.strip().upper()
        for table in parser.tables:
            header_index = next(
                (
                    index
                    for index, row in enumerate(table[:20])
                    if cls._REQUIRED_HEADERS
                    <= {cell.strip().lower() for cell in row if _clean(cell)}
                ),
                None,
            )
            if header_index is None:
                continue
            header = table[header_index]
            records = [_row_dict(header, row) for row in table[header_index + 1 :]]
            matched = [
                record
                for record in records
                if _clean(_first(record, ["account"])) == normalized_symbol
            ]
            if not matched:
                continue
            rows = parse_holdings_table(
                [header, *[[record.get(column, "") for column in header] for record in matched]]
            )
            composition_dates: list[date] = []
            for record in matched:
                raw_date = _clean(_first(record, ["date"]))
                if raw_date is None:
                    continue
                try:
                    composition_dates.append(datetime.strptime(raw_date, "%m/%d/%Y").date())
                except ValueError:
                    continue
            return rows, max(composition_dates, default=None)
        return [], None


class CultivarHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch the complete current CVAR table published on Cultivar's fund page."""

    FUND_PAGE_URL = "https://cultivarfunds.com/funds/"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol != "CVAR":
            raise ValueError(
                f"No verified Cultivar current-holdings route is configured for {normalized_symbol}."
            )
        if source_url and source_url.rstrip("/") != self.FUND_PAGE_URL.rstrip("/"):
            raise ValueError("Cultivar holdings must use the verified official fund page.")
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await self._get_with_timeout_retry(
                client,
                self.FUND_PAGE_URL,
                headers=_issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*"),
            )
        response.raise_for_status()
        rows = parse_html_holdings_table_by_headers(
            response.text,
            required_headers={
                "ticker",
                "security description",
                "% of fund",
                "cusip",
                "shares",
                "market value",
            },
        )
        if not rows:
            raise ValueError("Cultivar fund page contained no parseable current holdings rows.")
        date_match = re.search(
            r"Fund Holdings as of\s+(\d{2}/\d{2}/\d{4})",
            response.text,
            re.IGNORECASE,
        )
        composition_date = (
            datetime.strptime(date_match.group(1), "%m/%d/%Y").date() if date_match else None
        )
        for index, row in enumerate(rows, start=1):
            row.source_row_id = f"CVAR:{composition_date or 'unknown'}:{index}"
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json={"source_format": "html_table", "row_count": len(rows)},
            source_url=str(response.url),
            source_identifier="CVAR",
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "html_table",
                "route_resolution": "cultivar_current_fund_page_holdings_table",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    async def _get_with_timeout_retry(
        client: httpx.AsyncClient,
        url: str,
        *,
        headers: dict[str, str],
    ) -> httpx.Response:
        # Cultivar's page can stall during the full issuer sweep; retry only that
        # transient failure without weakening page or table validation.
        for attempt in range(3):
            try:
                return await client.get(url, headers=headers, follow_redirects=True)
            except httpx.TimeoutException:
                if attempt == 2:
                    raise
                await asyncio.sleep(0.25 * (attempt + 1))
        raise AssertionError("unreachable")


class EMLesHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch EMLes' fund-specific full-holdings CSV from its public ETF pages."""

    product_page_urls = {
        "AMER": "https://emles.com/etf/emles-made-in-america/",
        "EOPS": "https://emles.com/etf/emles-alpha-opportunities-etf/",
        "LUXE": "https://emles.com/etf/emles-luxury-goods/",
        "FEDX": "https://emles.com/etf/emles-federal-contractors/",
        "REC": "https://emles.com/etf/emles-real-estate-credit/",
        "LIV": "https://emles.com/etf/emles-home-etf/",
    }
    holdings_url_template = "https://api.emles.com/download/holdings/{symbol}"

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name, identifiers
        normalized_symbol = symbol.strip().upper()
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9000")
            if normalized_symbol in self.product_page_urls
            else Decimal("0.5000"),
            status="ready",
            reason=(
                "EMLes publishes this fund's complete holdings CSV from its public ETF page."
                if normalized_symbol in self.product_page_urls
                else "EMLes is configured; its verified public holdings routes cover its listed ETF lineup."
            ),
            source_url=self.product_page_urls.get(normalized_symbol),
            issuer_product_id=normalized_symbol or None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        product_page_url = self.product_page_urls.get(normalized_symbol)
        if product_page_url is None:
            raise ValueError(
                f"EMLes has no verified public holdings route for {normalized_symbol}."
            )
        if source_url and "emles.com" in source_url.lower():
            product_page_url = source_url

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            page_response = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*"),
                follow_redirects=True,
            )
            page_response.raise_for_status()
            self._validate_product_page(page_response.text, symbol=normalized_symbol)
            holdings_response = await client.get(
                self.holdings_url_template.format(symbol=normalized_symbol),
                headers={
                    **_holdings_request_headers(accept="text/csv,text/plain,*/*"),
                    "Referer": str(page_response.url),
                },
                follow_redirects=True,
            )
            holdings_response.raise_for_status()

        rows, composition_date = self._parse_holdings_csv(
            holdings_response.text, symbol=normalized_symbol
        )
        if not rows:
            raise ValueError(
                f"EMLes full holdings CSV returned no parseable rows for {normalized_symbol}."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=holdings_response.text,
            raw_json={"source_format": "csv", "row_count": len(rows)},
            source_url=str(holdings_response.url),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "emles_public_fund_page_full_holdings_download",
                "product_page_url": str(page_response.url),
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _validate_product_page(raw_html: str, *, symbol: str) -> None:
        if (
            re.search(
                rf'<(?:as-of-date|top-holdings)\s+ticker=["\']{re.escape(symbol)}["\']',
                raw_html,
                re.IGNORECASE,
            )
            is None
        ):
            raise ValueError(f"EMLes product page identity did not match requested ETF {symbol}.")

    @staticmethod
    def _parse_holdings_csv(
        raw_csv: str, *, symbol: str
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for index, raw in enumerate(csv.DictReader(StringIO(raw_csv.strip())), start=1):
            row_date = _clean(raw.get("as_of_date") or raw.get("run_date"))
            if row_date:
                try:
                    parsed_date = date.fromisoformat(row_date)
                    if composition_date is None or parsed_date > composition_date:
                        composition_date = parsed_date
                except ValueError:
                    pass
            name = _clean(raw.get("name"))
            ticker = _clean(raw.get("ticker"))
            identifier = _clean(raw.get("identifier"))
            haystack = " ".join(part.lower() for part in (ticker, name) if part)
            is_cash = "cash" in haystack or "cash equivalent" in haystack
            if not any([ticker, name, identifier, raw.get("market_value")]):
                continue
            rows.append(
                CanonicalHoldingRow(
                    symbol=None if is_cash else (ticker.upper() if ticker else None),
                    name=name,
                    cusip=identifier if _looks_like_cusip(identifier) else None,
                    weight=_decimal_percent_points(raw.get("weight")),
                    shares=_decimal(raw.get("shares_held")),
                    market_value=_decimal(raw.get("market_value")),
                    currency="USD" if is_cash else None,
                    holding_type="cash" if is_cash else "equity",
                    row_type="cash" if is_cash else "security",
                    source_row_id=f"{symbol}:{index}:{identifier or ticker or name or 'holding'}",
                    extra_data={
                        key: value for key, value in raw.items() if value not in (None, "")
                    },
                )
            )
        return rows, composition_date


