class ArcherInvestmentHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Archer Growth ETF's current issuer-linked daily holdings CSV."""

    product_page_url = "https://www.thearcherfunds.com/archer-growth-etf"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, source_url, identifiers
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol != "ARWG":
            raise ValueError(
                "Archer Investment's verified issuer-native holdings route currently supports ARWG."
            )

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            page_response = await client.get(
                self.product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*"),
                follow_redirects=True,
            )
            page_response.raise_for_status()
            csv_url = self._discover_holdings_csv(
                page_response.text,
                symbol=normalized_symbol,
                page_url=str(page_response.url),
            )
            csv_response = await client.get(
                csv_url,
                headers={
                    **_holdings_request_headers(accept="text/csv,text/plain,*/*"),
                    "Referer": str(page_response.url),
                },
                follow_redirects=True,
            )
            csv_response.raise_for_status()

        rows, composition_date = self._parse_holdings_csv(
            csv_response.text, symbol=normalized_symbol
        )
        if not rows:
            raise ValueError(
                "Archer's issuer holdings CSV did not contain a complete ARWG portfolio."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=csv_response.text,
            raw_json={
                "source_format": "issuer_product_page_linked_daily_holdings_csv",
                "product_page_url": str(page_response.url),
                "row_count": len(rows),
            },
            source_url=str(csv_response.url),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "archer_investment_product_page_linked_daily_holdings_csv",
                "product_page_url": str(page_response.url),
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _discover_holdings_csv(raw_html: str, *, symbol: str, page_url: str) -> str:
        if not re.search(rf"\b{re.escape(symbol)}\b", raw_html, re.IGNORECASE):
            raise ValueError(f"Archer product page identity did not match requested ETF {symbol}.")
        matches = re.finditer(
            r"""href=["'](?P<url>[^"']+\.csv(?:\?[^"']*)?)["']""", raw_html, re.IGNORECASE
        )
        for match in matches:
            candidate = html.unescape(match.group("url")).strip()
            if "holding" in candidate.lower():
                return urljoin(page_url, candidate)
        raise ValueError(f"Archer product page did not link a complete holdings CSV for {symbol}.")

    @staticmethod
    def _parse_holdings_csv(
        raw_csv: str, *, symbol: str
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for index, raw in enumerate(csv.DictReader(StringIO(raw_csv.strip())), start=1):
            account = (_clean(raw.get("Account")) or "").upper()
            if account != symbol.upper():
                continue
            row_date = _clean(raw.get("Date"))
            if row_date:
                try:
                    parsed_date = datetime.strptime(row_date, "%m/%d/%Y").date()
                    if composition_date is None or parsed_date > composition_date:
                        composition_date = parsed_date
                except ValueError:
                    pass
            ticker = _clean(raw.get("StockTicker"))
            cusip = _clean(raw.get("CUSIP"))
            name = _clean(raw.get("SecurityName"))
            money_market_flag = _clean(raw.get("MoneyMarketFlag"))
            haystack = " ".join(part.lower() for part in (ticker, name, money_market_flag) if part)
            is_cash = bool(money_market_flag) or "cash" in haystack or "money market" in haystack
            if not any([ticker, cusip, name, raw.get("MarketValue")]):
                continue
            rows.append(
                CanonicalHoldingRow(
                    symbol=None if is_cash else (ticker.upper() if ticker else None),
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    weight=_decimal(raw.get("Weightings")),
                    shares=_decimal(raw.get("Shares")),
                    market_value=_decimal(raw.get("MarketValue")),
                    currency="USD" if is_cash else None,
                    holding_type="cash" if is_cash else "equity",
                    row_type="cash" if is_cash else "security",
                    source_row_id=f"{symbol}:{index}:{cusip or ticker or name or 'holding'}",
                    extra_data={
                        key: value for key, value in raw.items() if value not in (None, "")
                    },
                )
            )
        return rows, composition_date


class LibertyOneHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Liberty One ETF holdings through the issuer's page-scoped public API."""

    product_page_urls = {
        "SPCT": "https://www.libertyoneetf.com/funds/SPCT-Spectrum-ETF",
        "EASY": "https://www.libertyoneetf.com/funds/EASY-Defensive-Dividend-Growth-ETF.html",
        "LOTI": "https://www.libertyoneetf.com/funds/LOTI-Tactical-Income-ETF",
    }
    portfolio_name_fragments = {
        "SPCT": "LIBERTY ONE SPECTRUM ETF",
        "EASY": "LIBERTY ONE DEFENSIVE DIVIDEND GROWTH ETF",
        "LOTI": "LIBERTY ONE TACTICAL INCOME ETF",
    }
    holdings_api_url = "https://filepoint.live/liberty_getholdings_cached4.php"

    def resolve_product_page_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        del issuer_product_id, identifiers
        return self.product_page_urls.get(symbol.strip().upper())

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, source_url, identifiers
        normalized_symbol = symbol.strip().upper()
        product_page_url = self.resolve_product_page_url(symbol=normalized_symbol)
        if not product_page_url:
            raise ValueError(
                f"Liberty One's verified issuer-native holdings route does not include {normalized_symbol}."
            )

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            page_response = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*"),
                follow_redirects=True,
            )
            page_response.raise_for_status()
            portfolio_id = self._extract_portfolio_id(page_response.text, symbol=normalized_symbol)
            holdings_response = await self._post_with_timeout_retry(
                client,
                self.holdings_api_url,
                data={"fundID": portfolio_id},
                headers={
                    **_holdings_request_headers(accept="application/json,text/plain,*/*"),
                    "Referer": str(page_response.url),
                },
            )
            holdings_response.raise_for_status()

        payload = holdings_response.json()
        rows, composition_date = self._parse_holdings_payload(payload, symbol=normalized_symbol)
        if not rows:
            raise ValueError(
                f"Liberty One's issuer holdings API did not return a complete portfolio for {normalized_symbol}."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=holdings_response.text,
            raw_json={
                "source_format": "json",
                "product_page_url": str(page_response.url),
                "portfolio_id": portfolio_id,
                "row_count": len(rows),
            },
            source_url=str(holdings_response.url),
            source_identifier=portfolio_id,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "json",
                "route_resolution": "liberty_one_product_page_scoped_holdings_api",
                "product_page_url": str(page_response.url),
                "portfolio_id": portfolio_id,
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _extract_portfolio_id(raw_html: str, *, symbol: str) -> str:
        if not re.search(rf"\b{re.escape(symbol)}\b", raw_html, re.IGNORECASE):
            raise ValueError(
                f"Liberty One product page identity did not match requested ETF {symbol}."
            )
        match = re.search(
            r"""\bclass=["'][^"']*\bfundid\b[^"']*["'][^>]*\bdata-id=["'](?P<id>\d+)["']""",
            raw_html,
            re.IGNORECASE,
        )
        if match is None:
            raise ValueError(
                f"Liberty One product page did not expose a holdings portfolio ID for {symbol}."
            )
        return match.group("id")

    @staticmethod
    async def _get_with_timeout_retry(
        client: httpx.AsyncClient,
        url: str,
        *,
        headers: dict[str, str],
    ) -> httpx.Response:
        for attempt in range(3):
            try:
                return await client.get(url, headers=headers, follow_redirects=True)
            except httpx.TimeoutException:
                if attempt == 2:
                    raise
                await asyncio.sleep(0.25 * (attempt + 1))
        raise AssertionError("unreachable")

    @staticmethod
    async def _post_with_timeout_retry(
        client: httpx.AsyncClient,
        url: str,
        *,
        data: dict[str, str],
        headers: dict[str, str],
    ) -> httpx.Response:
        for attempt in range(3):
            try:
                return await client.post(url, data=data, headers=headers, follow_redirects=True)
            except httpx.TimeoutException:
                if attempt == 2:
                    raise
                await asyncio.sleep(0.25 * (attempt + 1))
        raise AssertionError("unreachable")

    @staticmethod
    def _parse_holdings_payload(
        payload: Any, *, symbol: str
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        if not isinstance(payload, list):
            return [], None
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for index, raw in enumerate(payload, start=1):
            if not isinstance(raw, dict):
                continue
            portfolio_name = _clean(raw.get("portfolioName") or raw.get("portoflioName"))
            expected_name = LibertyOneHoldingsAdapter.portfolio_name_fragments[symbol]
            if portfolio_name and expected_name not in portfolio_name.upper():
                continue
            as_of_date = _clean(raw.get("asOfDate"))
            if as_of_date:
                try:
                    parsed_date = datetime.fromisoformat(as_of_date.replace("Z", "+00:00")).date()
                    if composition_date is None or parsed_date > composition_date:
                        composition_date = parsed_date
                except ValueError:
                    pass
            raw_ticker = _clean(raw.get("securityTicker"))
            ticker, exchange = LibertyOneHoldingsAdapter._split_ticker(raw_ticker)
            identifier = _clean(raw.get("securityIdentifier"))
            name = _clean(raw.get("securityDescriptionLong") or raw.get("securityDescriptionShort"))
            segment = _clean(raw.get("segment"))
            haystack = " ".join(part.upper() for part in (ticker, name, segment) if part)
            is_cash = "CASH" in haystack or "MONEY MARKET" in haystack
            is_fixed_income = any(token in haystack for token in ("BOND", "NOTE", "FIXED INCOME"))
            if not any([ticker, identifier, name, raw.get("marketValueBase")]):
                continue
            rows.append(
                CanonicalHoldingRow(
                    symbol=None if is_cash or is_fixed_income else ticker,
                    name=name,
                    cusip=identifier if _looks_like_cusip(identifier) else None,
                    weight=_decimal(raw.get("marketValuePercent")),
                    shares=_decimal(raw.get("shares")),
                    market_value=_decimal(raw.get("marketValueBase")),
                    currency=_clean(raw.get("tradingCurrency")),
                    exchange=exchange,
                    holding_type="cash"
                    if is_cash
                    else ("fixed_income" if is_fixed_income else "equity"),
                    row_type="cash" if is_cash else "security",
                    source_row_id=f"{symbol}:{index}:{identifier or ticker or name or 'holding'}",
                    extra_data={
                        key: value for key, value in raw.items() if value not in (None, "")
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _split_ticker(raw_ticker: str | None) -> tuple[str | None, str | None]:
        if not raw_ticker:
            return None, None
        parts = raw_ticker.strip().upper().split()
        return (parts[0] if parts else None, parts[1] if len(parts) > 1 else None)


