class AptusHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Parse Aptus ETF holdings through the issuer's public WordPress API."""

    def resolve_product_page_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        explicit = super().resolve_product_page_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers,
        )
        if explicit:
            return explicit
        normalized_symbol = (issuer_product_id or symbol).strip().lower()
        if not normalized_symbol:
            return None
        return f"https://aptusetfs.com/{normalized_symbol}/"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        slug = (issuer_product_id or symbol).strip().lower()
        if not slug:
            raise ValueError("Aptus needs an ETF symbol for its holdings API.")
        api_url = (
            source_url
            if source_url and "/wp-json/wp/v2/pages" in source_url
            else f"https://aptusetfs.com/wp-json/wp/v2/pages?slug={slug}"
        )
        product_page_url = self.resolve_product_page_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers,
        )

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                api_url,
                headers={
                    **_holdings_request_headers(accept="application/json"),
                    "Referer": "https://aptusetfs.com/",
                },
                follow_redirects=True,
            )
        response.raise_for_status()
        payload = response.json()
        page = payload[0] if isinstance(payload, list) and payload else payload
        if not isinstance(page, dict):
            raise ValueError(f"Aptus holdings API returned no page for {symbol}.")
        content = page.get("content")
        raw_html = content.get("rendered") if isinstance(content, dict) else None
        if not isinstance(raw_html, str):
            raise ValueError(f"Aptus holdings API returned no holdings markup for {symbol}.")
        rows, composition_date = self._parse_product_page(raw_html)
        if not rows:
            raise ValueError(f"Aptus holdings API did not expose parseable holdings for {symbol}.")
        return HoldingsFetchResult(
            rows=rows,
            raw_text=raw_html,
            raw_json=page,
            source_url=str(response.url),
            source_identifier=issuer_product_id or symbol.strip().upper(),
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "html",
                "route_resolution": "issuer_wordpress_api_holdings_table",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "product_page_url": product_page_url,
                "terms_note": self.config.terms_note,
            },
        )

    @classmethod
    def _parse_product_page(cls, raw_html: str) -> tuple[list[CanonicalHoldingRow], date | None]:
        parser = _HTMLTablesParser()
        parser.feed(raw_html)
        composition_date = cls._extract_current_as_of_date(raw_html)
        for table in parser.tables:
            if not table:
                continue
            header_values = {str(value).strip().lower() for value in table[0] if _clean(value)}
            if not {"stock ticker", "cusip", "security desc", "weightings"} <= header_values:
                continue
            normalized_table = [
                [cls._normalize_header(value) for value in table[0]],
                *table[1:],
            ]
            rows = parse_holdings_table(normalized_table)
            if composition_date is None:
                composition_date = cls._extract_effective_date(rows)
            return rows, composition_date
        return [], composition_date

    @staticmethod
    def _normalize_header(value: Any) -> str:
        text = str(value).strip()
        lowered = text.lower()
        if lowered == "stock ticker":
            return "Ticker"
        if lowered == "security desc":
            return "Security Description"
        if lowered == "weightings":
            return "Weightings"
        return text

    @staticmethod
    def _extract_current_as_of_date(raw_html: str) -> date | None:
        match = re.search(
            r"Current\s+as\s+of\s+(\d{1,2}/\d{1,2}/\d{4})",
            raw_html,
            re.IGNORECASE,
        )
        if not match:
            return None
        try:
            return datetime.strptime(match.group(1), "%m/%d/%Y").date()
        except ValueError:
            return None

    @staticmethod
    def _extract_effective_date(rows: list[CanonicalHoldingRow]) -> date | None:
        for row in rows:
            text = _clean(row.extra_data.get("Effective Date"))
            if not text:
                continue
            try:
                return datetime.strptime(text, "%m/%d/%Y").date()
            except ValueError:
                continue
        return None


class ArrowHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Arrow ETF holdings from the issuer's public export endpoint."""

    PRODUCT_IDS = {
        "ARCM": "4",
    }
    PRODUCT_PAGE_MENU_IDS = {
        "ARCM": "518",
    }

    def resolve_source_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        if source_url:
            return source_url.strip()
        identifiers = identifiers or {}
        product_id = (
            issuer_product_id
            or _identifier(identifiers, "arrow_product_id", "product_id", "issuer_product_id")
            or self.PRODUCT_IDS.get(symbol.strip().upper())
        )
        if not product_id:
            return None
        return f"https://arrowfunds.com/ArrowSharesExport.aspx?ProductID={product_id}&type=holdings"

    def source_request_headers(self, *, source_url: str) -> dict[str, str]:
        return {
            **_holdings_request_headers(accept="text/csv,*/*"),
            "Referer": "https://arrowfunds.com/default.aspx?menuitemid=514",
        }

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        resolved_url = self.resolve_source_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        if not resolved_url:
            raise ValueError(f"Arrow needs a product id for {symbol}.")

        normalized_symbol = symbol.strip().upper()
        referer_menu_id = self.PRODUCT_PAGE_MENU_IDS.get(normalized_symbol)
        headers = self.source_request_headers(source_url=resolved_url)
        if referer_menu_id:
            headers["Referer"] = f"https://arrowfunds.com/default.aspx?menuitemid={referer_menu_id}"

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                resolved_url,
                headers=headers,
                follow_redirects=True,
            )
        response.raise_for_status()
        rows, composition_date = self._parse_arrow_csv(response.text)
        if not rows:
            raise ValueError(f"Arrow holdings export did not expose parseable rows for {symbol}.")

        source_identifier = (
            issuer_product_id
            or _identifier(identifiers or {}, "arrow_product_id", "product_id", "issuer_product_id")
            or self.PRODUCT_IDS.get(normalized_symbol)
        )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json=None,
            source_url=str(response.url),
            source_identifier=source_identifier,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "issuer_product_id_holdings_csv",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @classmethod
    def _parse_arrow_csv(cls, raw_csv: str) -> tuple[list[CanonicalHoldingRow], date | None]:
        cleaned_text = raw_csv.replace("<br>", "\n")
        lines = [
            line
            for line in cleaned_text.splitlines()
            if not line.strip().upper().startswith("SELECT ")
        ]
        reader = csv.reader(StringIO("\n".join(lines)))
        table = list(reader)
        composition_date = cls._extract_composition_date(table)
        header_index = next(
            (
                index
                for index, row in enumerate(table)
                if row and row[0].strip().lower() == "symbol"
            ),
            None,
        )
        if header_index is None:
            return [], composition_date

        header = table[header_index]
        rows: list[CanonicalHoldingRow] = []
        for index, raw_row in enumerate(table[header_index + 1 :], start=1):
            if not any(_clean(value) for value in raw_row):
                continue
            raw = _row_dict(header, raw_row)
            symbol = _clean(_first(raw, ["symbol"]))
            name = _clean(_first(raw, ["name"]))
            security_id = _clean(_first(raw, ["security id", "security identifier"]))
            cusip = security_id if _looks_like_cusip(security_id) else None
            weight = _decimal_percent_points(_first(raw, ["% of net assets"]))
            market_value = _decimal(_first(raw, ["market value ($)", "market value"]))
            country = _clean(_first(raw, ["country"]))
            if not any([symbol, name, cusip, weight, market_value]):
                continue
            holding_type = cls._classify_holding_type(name=name, symbol=symbol)
            row_type = "cash" if holding_type == "cash" else "security"
            rows.append(
                CanonicalHoldingRow(
                    symbol=symbol if row_type != "cash" else None,
                    name=name,
                    cusip=cusip,
                    weight=weight,
                    market_value=market_value,
                    country=country,
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=str(index),
                    extra_data={k: v for k, v in raw.items() if v not in (None, "")},
                )
            )
        return rows, composition_date

    @staticmethod
    def _extract_composition_date(table: list[list[str]]) -> date | None:
        for row in table[:20]:
            for cell in row:
                match = re.search(r"Holdings\s+as\s+of\s+(\d{1,2}/\d{1,2}/\d{4})", cell)
                if not match:
                    continue
                try:
                    return datetime.strptime(match.group(1), "%m/%d/%Y").date()
                except ValueError:
                    return None
        return None

    @staticmethod
    def _classify_holding_type(*, name: str | None, symbol: str | None) -> str:
        lowered_name = (name or "").strip().lower()
        upper_symbol = (symbol or "").strip().upper()
        if upper_symbol in {"CASH", "USD"} or lowered_name in {"cash", "us dollar", "u.s. dollar"}:
            return "cash"
        if " due " in lowered_name or re.search(r"\b\d+(?:\.\d+)?%\b", lowered_name):
            return "fixed_income"
        return "equity"


class AllianceBernsteinHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch AB ETF holdings through public AEM model JSON and linked workbooks."""

    PRODUCT_PAGE_URLS = {
        "FWD": (
            "https://www.alliancebernstein.com/us/en-us/investments/products/etf/"
            "equities/ab-disruptors-etf.-.00039J509.html"
        ),
    }

    def resolve_product_page_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        explicit = super().resolve_product_page_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers,
        )
        if explicit:
            return explicit
        return self.PRODUCT_PAGE_URLS.get(symbol.strip().upper())

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        product_page_url = source_url or self.resolve_product_page_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers,
        )
        if not product_page_url:
            raise ValueError(f"AllianceBernstein needs a product page URL for {symbol}.")

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            page_response = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,*/*"),
                follow_redirects=True,
            )
            page_response.raise_for_status()
            model_url = self._extract_model_url(page_response.text, base_url=str(page_response.url))
            if not model_url:
                raise ValueError(
                    f"AllianceBernstein product page did not expose a holdings model for {symbol}."
                )
            model_response = await client.get(
                model_url,
                headers={
                    **_issuer_page_request_headers(accept="application/json,*/*"),
                    "Referer": str(page_response.url),
                },
                follow_redirects=True,
            )
            model_response.raise_for_status()
            model_payload = model_response.json()
            holdings_url = self._latest_holdings_url(
                model_payload, base_url=str(model_response.url)
            )
            if not holdings_url:
                raise ValueError(
                    f"AllianceBernstein holdings model did not expose a workbook for {symbol}."
                )
            workbook_response = await client.get(
                holdings_url,
                headers={
                    **_holdings_request_headers(
                        accept=(
                            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,*/*"
                        )
                    ),
                    "Referer": str(page_response.url),
                },
                follow_redirects=True,
            )
            workbook_response.raise_for_status()

        workbook_rows = parse_xlsx_table(workbook_response.content)
        rows, composition_date, net_assets, base_currency = self._parse_workbook_rows(workbook_rows)
        if not rows:
            raise ValueError(
                f"AllianceBernstein holdings workbook did not expose parseable rows for {symbol}."
            )
        raw_text = _table_to_text(workbook_rows)
        return HoldingsFetchResult(
            rows=rows,
            raw_text=raw_text,
            raw_json={
                "source_format": "xlsx",
                "model_url": model_url,
                "workbook_url": str(workbook_response.url),
                "workbook_rows": workbook_rows,
            },
            source_url=str(workbook_response.url),
            source_identifier=issuer_product_id or symbol.strip().upper(),
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "xlsx",
                "route_resolution": "issuer_product_page_model_workbook",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "net_assets": str(net_assets) if net_assets is not None else None,
                "base_currency": base_currency,
                "product_page_url": str(page_response.url),
                "model_url": model_url,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _extract_model_url(raw_html: str, *, base_url: str) -> str | None:
        match = re.search(
            r"""data-portfolio-holding=["'](?P<url>[^"']+\.model\.json)["']""",
            raw_html,
            re.IGNORECASE,
        )
        if not match:
            return None
        return urljoin(base_url, html.unescape(match.group("url")))

    @staticmethod
    def _latest_holdings_url(payload: Any, *, base_url: str) -> str | None:
        if not isinstance(payload, dict):
            return None
        links = payload.get("links")
        if not isinstance(links, list):
            return None
        for link in links:
            if not isinstance(link, dict):
                continue
            url = _clean(link.get("url"))
            if url and url.lower().endswith((".xlsx", ".xlsm")):
                return urljoin(base_url, url)
        return None

    @classmethod
    def _parse_workbook_rows(
        cls,
        workbook_rows: list[list[Any]],
    ) -> tuple[list[CanonicalHoldingRow], date | None, Decimal | None, str | None]:
        composition_date = cls._extract_composition_date(workbook_rows)
        net_assets = cls._extract_net_assets(workbook_rows)
        base_currency = cls._extract_base_currency(workbook_rows)
        header_index = next(
            (
                index
                for index, row in enumerate(workbook_rows[:30])
                if {
                    "units/par value/ # of contracts",
                    "issue description/name",
                    "% of net assets",
                    "ticker",
                }
                <= {str(value).strip().lower() for value in row if _clean(value)}
            ),
            None,
        )
        if header_index is None:
            return [], composition_date, net_assets, base_currency

        header = workbook_rows[header_index]
        rows: list[CanonicalHoldingRow] = []
        for index, raw_row in enumerate(workbook_rows[header_index + 1 :], start=1):
            if not any(_clean(value) for value in raw_row):
                continue
            raw = _row_dict(header, raw_row)
            symbol = _clean(_first(raw, ["ticker"]))
            name = _clean(_first(raw, ["issue description/name"]))
            shares = _decimal(_first(raw, ["units/par value/ # of contracts"]))
            market_value = _decimal(_first(raw, ["accounting value (bc)"]))
            weight = _decimal(_first(raw, ["% of net assets"]))
            isin = _clean(_first(raw, ["isin (primary id)"]))
            cusip = _clean(_first(raw, ["cusip"]))
            sedol = _clean(_first(raw, ["sedol"]))
            if not any([symbol, name, isin, cusip, sedol, weight, shares, market_value]):
                continue
            holding_type = "cash" if (symbol or "").upper() in {"CASH", "USD"} else "equity"
            row_type = "cash" if holding_type == "cash" else "security"
            rows.append(
                CanonicalHoldingRow(
                    symbol=symbol if row_type != "cash" else None,
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    isin=isin,
                    sedol=sedol,
                    weight=weight,
                    shares=shares,
                    market_value=market_value,
                    currency=base_currency,
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=str(index),
                    extra_data={k: v for k, v in raw.items() if v not in (None, "")},
                )
            )
        return rows, composition_date, net_assets, base_currency

    @staticmethod
    def _extract_composition_date(workbook_rows: list[list[Any]]) -> date | None:
        for row in workbook_rows[:10]:
            for cell in row:
                match = re.search(r"Full\s+Holdings\s+as\s+of\s+(\d{1,2}/\d{1,2}/\d{4})", str(cell))
                if not match:
                    continue
                try:
                    return datetime.strptime(match.group(1), "%m/%d/%Y").date()
                except ValueError:
                    return None
        return None

    @staticmethod
    def _extract_net_assets(workbook_rows: list[list[Any]]) -> Decimal | None:
        for row in workbook_rows[:10]:
            for cell in row:
                match = re.search(r"Net\s+Assets\s+\$?([\d,]+(?:\.\d+)?)", str(cell))
                if match:
                    return _decimal(match.group(1))
        return None

    @staticmethod
    def _extract_base_currency(workbook_rows: list[list[Any]]) -> str | None:
        for row in workbook_rows[:10]:
            for cell in row:
                match = re.search(r"Base\s+Currency:\s*([A-Z]{3})", str(cell))
                if match:
                    return match.group(1)
        return None


class EquitableHoldingsAdapter(AllianceBernsteinHoldingsAdapter):
    """Fetch Equitable-owned AB ETF holdings through the AB publisher route."""

    SUPPORTED_SYMBOLS = {"FWD"}

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name
        normalized_symbol = symbol.strip().upper()
        supported = normalized_symbol in self.SUPPORTED_SYMBOLS
        has_sec_fallback = bool(_identifier(identifiers, "sec_cik", "cik"))
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500") if supported else Decimal("0.6000"),
            status="ready" if supported or has_sec_fallback else "needs_issuer_route",
            reason=(
                "Equitable-owned AllianceBernstein publishes complete current ETF "
                "holdings through AB's public product-page model workbook."
                if supported
                else (
                    "No verified Equitable/AllianceBernstein native holdings route "
                    "is configured for this ETF symbol; SEC EDGAR remains available as fallback."
                    if has_sec_fallback
                    else "No verified Equitable/AllianceBernstein native holdings route is configured for this ETF symbol."
                )
            ),
            source_url=self.PRODUCT_PAGE_URLS[normalized_symbol] if supported else None,
            issuer_product_id=normalized_symbol if supported else None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in self.SUPPORTED_SYMBOLS:
            raise ValueError(
                "Equitable has a verified AB-published public holdings route only for FWD."
            )
        result = await super().fetch_latest(
            symbol=normalized_symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        metadata = {
            **(result.legal_metadata or {}),
            "source_provider": self.source_provider,
            "adapter_key": self.adapter_key,
            "route_resolution": "alliancebernstein_publisher_model_workbook_for_equitable_owned_etf",
            "issuer_relationship": "Equitable parent identity / AllianceBernstein public ETF publisher",
            "snapshot_provenance": "equitable_alliancebernstein_native_holdings_workbook",
            "publisher": "alliancebernstein",
            "parent_issuer": "equitable_holdings",
        }
        return replace(result, legal_metadata=metadata)


class TwentyOneSharesHoldingsAdapter(IssuerCsvHoldingsAdapter):
    primary_base_url = "https://21sharesprimary.paradox-coworking.com"
    secondary_base_url = "https://21sharessecondary.paradox-coworking.com"

    def resolve_source_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        if source_url:
            return source_url.strip()
        normalized_symbol = (issuer_product_id or symbol).strip().upper()
        if not normalized_symbol:
            return None
        return f"{self.primary_base_url}/api/product_details/{normalized_symbol}"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = (issuer_product_id or symbol).strip().upper()
        primary_url = self.resolve_source_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        if not primary_url:
            return await super().fetch_latest(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                source_url=source_url,
                identifiers=identifiers,
            )

        source_urls = [
            primary_url,
            f"{self.secondary_base_url}/api/product_details/{normalized_symbol}",
        ]
        failures: list[str] = []
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            for resolved_source_url in source_urls:
                try:
                    response = await client.get(
                        resolved_source_url,
                        headers=self.source_request_headers(source_url=resolved_source_url),
                        follow_redirects=True,
                    )
                    response.raise_for_status()
                    payload = response.json()
                except Exception as exc:  # noqa: BLE001 - fall through to secondary API host.
                    failures.append(f"{resolved_source_url}: {exc}")
                    continue

                rows = self._parse_constituents(payload)
                if rows:
                    data = payload.get("data") if isinstance(payload, dict) else None
                    if not isinstance(data, dict):
                        data = {}
                    return HoldingsFetchResult(
                        rows=rows,
                        raw_text=response.text,
                        raw_json=payload,
                        source_url=str(getattr(response, "url", resolved_source_url)),
                        source_identifier=normalized_symbol,
                        legal_metadata={
                            "source_access": self.config.source_access,
                            "source_provider": self.source_provider,
                            "adapter_key": self.adapter_key,
                            "source_format": "json",
                            "route_resolution": "issuer_public_product_details_api",
                            "product_name": data.get("product_name"),
                            "jurisdiction": data.get("jurisdiction"),
                            "valuation_date": data.get("valuation_date"),
                            "composition_date": data.get("valuation_date"),
                            "as_of_date": data.get("valuation_date"),
                            "total_nav": data.get("total_nav"),
                            "total_units_outstanding": data.get("total_units_outstanding"),
                            "nav_per_unit": data.get("nav_per_unit"),
                            "terms_note": self.config.terms_note,
                        },
                    )
                failures.append(f"{resolved_source_url}: no constituent rows")

        raise ValueError(
            f"21Shares did not return parseable {normalized_symbol} holdings: "
            f"{'; '.join(failures)}"
        )

    def source_request_headers(self, *, source_url: str) -> dict[str, str]:
        headers = _issuer_page_request_headers(accept="application/json,*/*")
        headers["Origin"] = "https://www.21shares.com"
        headers["Referer"] = "https://www.21shares.com/"
        return headers

    def _parse_constituents(self, payload: dict[str, Any]) -> list[CanonicalHoldingRow]:
        data = payload.get("data") if isinstance(payload, dict) else None
        if not isinstance(data, dict):
            return []
        constituents = data.get("constituents")
        if not isinstance(constituents, list):
            return []

        rows: list[CanonicalHoldingRow] = []
        for index, item in enumerate(constituents, start=1):
            if not isinstance(item, dict):
                continue
            symbol_value = _clean(item.get("ticker"))
            name = _clean(item.get("name"))
            if not any([symbol_value, name, item.get("cusip")]):
                continue
            holding_type = "crypto" if symbol_value in {"BTC", "ETH", "SOL", "DOGE"} else "security"
            rows.append(
                CanonicalHoldingRow(
                    symbol=symbol_value,
                    name=name,
                    cusip=_clean(item.get("cusip")),
                    weight=_decimal(item.get("weight")),
                    shares=_decimal(item.get("quantity")),
                    market_value=_decimal(item.get("market_value")),
                    currency=_clean((data.get("currency") or {}).get("short_name"))
                    if isinstance(data.get("currency"), dict)
                    else None,
                    holding_type=holding_type,
                    row_type=holding_type,
                    source_row_id=str(index),
                    extra_data={
                        "price": item.get("price"),
                        "total_fiat": item.get("total_fiat"),
                        "amount_per_creation_unit": item.get("amount_per_creation_unit"),
                        "product_ticker": data.get("ticker"),
                        "valuation_date": data.get("valuation_date"),
                        **{key: value for key, value in item.items() if value not in (None, "")},
                    },
                )
            )
        return rows


class AmunHoldingsAdapter(TwentyOneSharesHoldingsAdapter):
    """Fetch Amun's U.S. ETF range from its 21Shares subsidiary API."""

    supported_symbols = {"ARKB", "TETH", "TOXR", "TSOL"}

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in self.supported_symbols:
            raise ValueError(
                "Amun's verified 21Shares U.S. holdings route only supports "
                f"{', '.join(sorted(self.supported_symbols))}; received {normalized_symbol}."
            )
        if source_url:
            raise ValueError("Amun holdings must use its verified 21Shares publisher route.")
        if issuer_product_id and issuer_product_id.strip().upper() != normalized_symbol:
            raise ValueError("Amun issuer product identity must match the requested ETF symbol.")

        source_urls = [
            f"{self.primary_base_url}/api/product_details/{normalized_symbol}",
            f"{self.secondary_base_url}/api/product_details/{normalized_symbol}",
        ]
        failures: list[str] = []
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            for resolved_source_url in source_urls:
                try:
                    response = await client.get(
                        resolved_source_url,
                        headers=self.source_request_headers(source_url=resolved_source_url),
                        follow_redirects=True,
                    )
                    response.raise_for_status()
                    payload = response.json()
                except Exception as exc:  # noqa: BLE001 - continue to the secondary issuer API host.
                    failures.append(f"{resolved_source_url}: {exc}")
                    continue

                rows = self._parse_constituents(payload)
                if not rows:
                    failures.append(f"{resolved_source_url}: no constituent rows")
                    continue
                data = payload.get("data") if isinstance(payload, dict) else None
                if not isinstance(data, dict):
                    data = {}
                return HoldingsFetchResult(
                    rows=rows,
                    raw_text=response.text,
                    raw_json=payload,
                    source_url=str(getattr(response, "url", resolved_source_url)),
                    source_identifier=normalized_symbol,
                    legal_metadata={
                        "source_access": self.config.source_access,
                        "source_provider": self.source_provider,
                        "adapter_key": self.adapter_key,
                        "source_format": "json",
                        "route_resolution": "amun_21shares_public_product_details_api",
                        "product_name": data.get("product_name"),
                        "jurisdiction": data.get("jurisdiction"),
                        "valuation_date": data.get("valuation_date"),
                        "composition_date": data.get("valuation_date"),
                        "as_of_date": data.get("valuation_date"),
                        "total_nav": data.get("total_nav"),
                        "total_units_outstanding": data.get("total_units_outstanding"),
                        "nav_per_unit": data.get("nav_per_unit"),
                        "publisher": "21shares",
                        "terms_note": self.config.terms_note,
                    },
                )

        raise ValueError(
            f"Amun's 21Shares publisher did not return parseable {normalized_symbol} holdings: "
            f"{'; '.join(failures)}"
        )


class YieldMaxHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch YieldMax's account-scoped daily Tidal holdings CSVs.

    YieldMax's funds publish derivatives alongside collateral.  The dedicated
    parser must therefore retain the portfolio rows without mistaking options or
    Treasury identifiers for platform-tradable ticker symbols.
    """

    _HOLDINGS_URL_TEMPLATE = (
        "https://yieldmaxetfs.com/wp-content/uploads/funds/"
        "{symbol_upper}/TidalFG_Holdings_{symbol_upper}.csv"
    )
    _REQUIRED_HEADERS = frozenset(
        {
            "Date",
            "Account",
            "StockTicker",
            "CUSIP",
            "SecurityName",
            "Shares",
            "MarketValue",
            "Weightings",
        }
    )

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        normalized_symbol = symbol.strip().upper()
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500"),
            status="ready" if normalized_symbol else "needs_issuer_route",
            reason=(
                "YieldMax publishes this ETF's complete current account-scoped holdings CSV on its official route."
                if normalized_symbol
                else "YieldMax holdings require an ETF symbol."
            ),
            source_url=(self._holdings_url(normalized_symbol) if normalized_symbol else None),
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            raise ValueError("YieldMax holdings require an ETF symbol.")
        holdings_url = source_url or self._holdings_url(normalized_symbol)
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                holdings_url,
                headers={
                    **_holdings_request_headers(accept="text/csv,text/plain,*/*"),
                    "Referer": f"https://yieldmaxetfs.com/our-etfs/{normalized_symbol.lower()}/",
                },
                follow_redirects=True,
            )
        response.raise_for_status()
        rows, composition_date = self._parse_holdings_csv(response.text, symbol=normalized_symbol)
        if not rows:
            raise ValueError(f"YieldMax holdings CSV did not expose rows for {normalized_symbol}.")
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            source_url=str(response.url),
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={
                "source_access": "yieldmax_fund_scoped_daily_holdings_csv",
                "source_provider": "yieldmax",
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "yieldmax_symbol_daily_holdings_csv",
                "snapshot_provenance": "yieldmax_native_daily_holdings_csv",
                **({"composition_date": composition_date.isoformat()} if composition_date else {}),
            },
        )

    @classmethod
    def _holdings_url(cls, symbol: str) -> str:
        return cls._HOLDINGS_URL_TEMPLATE.format(symbol_upper=symbol.upper())

    @classmethod
    def _parse_holdings_csv(
        cls,
        raw_csv: str,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        reader = csv.DictReader(StringIO(raw_csv.strip()))
        if not cls._REQUIRED_HEADERS.issubset(set(reader.fieldnames or [])):
            raise ValueError("YieldMax holdings CSV did not expose the expected account schema.")
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for position, raw in enumerate(reader, start=1):
            account = (_clean(raw.get("Account")) or "").upper()
            if account != symbol:
                continue
            row_date = cls._parse_date(raw.get("Date"))
            if composition_date is None:
                composition_date = row_date
            source_ticker = _clean(raw.get("StockTicker"))
            identifier = _clean(raw.get("CUSIP"))
            name = _clean(raw.get("SecurityName"))
            row_type, holding_type = cls._classify_row(
                source_ticker=source_ticker,
                identifier=identifier,
                name=name,
                money_market=_clean(raw.get("MoneyMarketFlag")),
            )
            parsed_symbol = cls._tradable_symbol(source_ticker) if row_type == "security" else None
            if not any((parsed_symbol, name, identifier, _clean(raw.get("MarketValue")))):
                continue
            rows.append(
                CanonicalHoldingRow(
                    symbol=parsed_symbol,
                    name=name,
                    cusip=identifier
                    if _looks_like_cusip(identifier) and row_type == "security"
                    else None,
                    weight=_decimal(raw.get("Weightings")),
                    shares=_decimal(raw.get("Shares")),
                    market_value=_decimal(raw.get("MarketValue")),
                    currency="USD",
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=f"yieldmax-{symbol}-{position}",
                    extra_data={
                        key: value for key, value in raw.items() if _clean(value) is not None
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _parse_date(value: Any) -> date | None:
        text = _clean(value)
        if text is None:
            return None
        try:
            return datetime.strptime(text, "%m/%d/%Y").date()
        except ValueError:
            return None

    @staticmethod
    def _tradable_symbol(value: str | None) -> str | None:
        candidate = _clean(value)
        if candidate is None:
            return None
        normalized = candidate.upper().strip()
        return normalized if re.fullmatch(r"[A-Z][A-Z0-9.-]{0,11}", normalized) else None

    @staticmethod
    def _classify_row(
        *,
        source_ticker: str | None,
        identifier: str | None,
        name: str | None,
        money_market: str | None,
    ) -> tuple[str, str]:
        text = " ".join(part.upper() for part in (source_ticker, identifier, name) if part)
        if (money_market or "").upper() == "Y" or "CASH" in text or "MONEY MARKET" in text:
            return "cash", "cash"
        if re.search(r"\b\d{6}[CP]\d{8}\b", text) or " OPTION" in text:
            return "other", "option"
        if any(marker in text for marker in ("TREASURY", "BILL", "NOTE", "BOND")):
            return "security", "fixed_income"
        if " ETF" in text or " FUND" in text:
            return "security", "fund"
        return "security", "equity"


class PraxisHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Praxis ETFs' complete daily holdings from their fund-scoped pages.

    Praxis publishes each ETF's complete account-scoped CSV through its
    dedicated Azure publisher.  Praxis's public site geo-blocks server-side
    clients, so route discovery cannot depend on its rendered fund page.  The
    verified catalogue and exact per-fund file convention remain scoped to
    Praxis and are not a generic cross-issuer fallback.
    """

    _PRODUCT_PAGE_URLS = {
        "PRXG": "https://www.praxisinvests.com/products/etfs/prxg-impact-large-cap-growth-etf/holdings",
        "PRXV": "https://www.praxisinvests.com/products/etfs/prxv-impact-large-cap-value-etf/holdings",
        "PRXI": "https://www.praxisinvests.com/products/etfs/prxi-impact-international-etf/holdings",
    }
    _HOLDINGS_URL_TEMPLATE = (
        "https://azr1webprodcdnst.blob.core.windows.net/praxisetf/{symbol}_Holdings.csv"
    )
    _REQUIRED_HEADERS = frozenset(
        {
            "Date",
            "Account",
            "StockTicker",
            "CUSIP",
            "SecurityName",
            "Shares",
            "MarketValue",
            "Weightings",
        }
    )

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        normalized_symbol = symbol.strip().upper()
        product_page_url = self._PRODUCT_PAGE_URLS.get(normalized_symbol)
        if product_page_url is None:
            # Keep the universal SEC fallback available for recognized Praxis
            # products that are outside the deliberately verified native list.
            return super().probe(symbol=symbol, name=name, identifiers=identifiers)
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500"),
            status="ready",
            reason="Praxis publishes this ETF's complete daily holdings CSV through its verified issuer route.",
            source_url=product_page_url,
            issuer_product_id=normalized_symbol or None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        product_page_url = self._PRODUCT_PAGE_URLS.get(normalized_symbol)
        if product_page_url is None:
            raise ValueError(
                f"Praxis does not have a verified native ETF holdings route for {normalized_symbol}."
            )

        holdings_url = self._HOLDINGS_URL_TEMPLATE.format(symbol=normalized_symbol)
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            csv_response = await client.get(
                holdings_url,
                headers={
                    **_holdings_request_headers(accept="text/csv,text/plain,*/*"),
                    "Referer": product_page_url,
                },
                follow_redirects=True,
            )
        csv_response.raise_for_status()
        rows, composition_date = self._parse_holdings_csv(
            csv_response.text,
            symbol=normalized_symbol,
        )
        if not rows:
            raise ValueError(f"Praxis holdings CSV did not expose rows for {normalized_symbol}.")
        return HoldingsFetchResult(
            rows=rows,
            raw_text=csv_response.text,
            source_url=str(csv_response.url),
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={
                "source_access": "praxis_publisher_daily_holdings_csv",
                "source_provider": "praxis",
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "praxis_verified_symbol_daily_holdings_csv",
                "product_page_url": product_page_url,
                "snapshot_provenance": "praxis_native_daily_holdings_csv",
                **({"composition_date": composition_date.isoformat()} if composition_date else {}),
                **({"as_of_date": composition_date.isoformat()} if composition_date else {}),
            },
        )

    @classmethod
    def _parse_holdings_csv(
        cls,
        raw_csv: str,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        reader = csv.DictReader(StringIO(raw_csv.strip()))
        if not cls._REQUIRED_HEADERS.issubset(set(reader.fieldnames or [])):
            raise ValueError("Praxis holdings CSV did not expose the expected account schema.")
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for position, raw in enumerate(reader, start=1):
            if (_clean(raw.get("Account")) or "").upper() != symbol:
                continue
            row_date = cls._parse_date(raw.get("Date"))
            if row_date is not None and (composition_date is None or row_date > composition_date):
                composition_date = row_date
            source_ticker = _clean(raw.get("StockTicker"))
            cusip = _clean(raw.get("CUSIP"))
            name = _clean(raw.get("SecurityName"))
            holding_type, row_type = cls._classify_holding(
                source_ticker=source_ticker,
                name=name,
                money_market=_clean(raw.get("MoneyMarketFlag")),
            )
            parsed_symbol = cls._tradable_symbol(source_ticker) if row_type == "security" else None
            if not any((parsed_symbol, name, cusip, _clean(raw.get("MarketValue")))):
                continue
            rows.append(
                CanonicalHoldingRow(
                    symbol=parsed_symbol,
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) and row_type == "security" else None,
                    weight=_decimal(raw.get("Weightings")),
                    shares=_decimal(raw.get("Shares")),
                    market_value=_decimal(raw.get("MarketValue")),
                    currency="USD",
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=f"praxis-{symbol}-{position}",
                    extra_data={
                        key: value for key, value in raw.items() if _clean(value) is not None
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _parse_date(value: Any) -> date | None:
        text = _clean(value)
        if text is None:
            return None
        try:
            return datetime.strptime(text, "%m/%d/%Y").date()
        except ValueError:
            return None

    @staticmethod
    def _tradable_symbol(value: str | None) -> str | None:
        candidate = _clean(value)
        if candidate is None:
            return None
        normalized = candidate.upper().strip()
        return normalized if re.fullmatch(r"[A-Z][A-Z0-9.-]{0,11}", normalized) else None

    @staticmethod
    def _classify_holding(
        *,
        source_ticker: str | None,
        name: str | None,
        money_market: str | None,
    ) -> tuple[str, str]:
        text = " ".join(part.upper() for part in (source_ticker, name) if part)
        if (money_market or "").upper() == "Y" or "CASH" in text or "MONEY MARKET" in text:
            return "cash", "cash"
        if any(marker in text for marker in ("TREASURY", "BILL", "NOTE", "BOND")):
            return "fixed_income", "security"
        if " ETF" in text or " FUND" in text or "TRUST" in text:
            return "fund", "security"
        return "equity", "security"


class BairdHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Read Strategas ETFs' complete issuer-published current holdings CSVs."""

    _SYMBOLS = frozenset({"SAGP", "SAMM", "SAMT"})
    _HOLDINGS_URL_TEMPLATE = "https://www.strategasetfs.com/holding/download/{symbol_lower}"
    route_resolution = "baird_strategas_symbol_holdings_csv"
    snapshot_provenance = "baird_strategas_native_current_holdings_csv"
    source_row_prefix = "baird"
    _REQUIRED_HEADERS = frozenset(
        {"ETF", "Ticker", "Description", "Date", "CUSIP", "SEDOL", "Quantity", "Weight"}
    )

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in self._SYMBOLS:
            return super().probe(symbol=symbol, name=name, identifiers=identifiers)
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500"),
            status="ready",
            reason="Strategas publishes this Baird ETF's complete current holdings CSV.",
            source_url=self._HOLDINGS_URL_TEMPLATE.format(symbol_lower=normalized_symbol.lower()),
            issuer_product_id=normalized_symbol,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del source_url, identifiers
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in self._SYMBOLS:
            raise ValueError(
                f"Baird does not have a verified native Strategas holdings route for {normalized_symbol}."
            )
        holdings_url = self._HOLDINGS_URL_TEMPLATE.format(symbol_lower=normalized_symbol.lower())
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                holdings_url,
                headers=_holdings_request_headers(accept="text/csv,text/plain,*/*"),
                follow_redirects=True,
            )
        response.raise_for_status()
        rows, composition_date = self._parse_holdings_csv(response.text, symbol=normalized_symbol)
        if not rows:
            raise ValueError(f"Baird holdings CSV did not expose rows for {normalized_symbol}.")
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            source_url=str(response.url),
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "publisher": "strategas_asset_management",
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": self.route_resolution,
                "snapshot_provenance": self.snapshot_provenance,
                "terms_note": self.config.terms_note,
                **({"composition_date": composition_date.isoformat()} if composition_date else {}),
                **({"as_of_date": composition_date.isoformat()} if composition_date else {}),
            },
        )

    @classmethod
    def _parse_holdings_csv(
        cls,
        raw_csv: str,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        reader = csv.DictReader(StringIO(raw_csv.strip()))
        if not cls._REQUIRED_HEADERS.issubset(set(reader.fieldnames or [])):
            raise ValueError("Baird holdings CSV did not expose the expected Strategas schema.")
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for position, raw in enumerate(reader, start=1):
            if (_clean(raw.get("ETF")) or "").upper() != symbol:
                continue
            row_date = cls._parse_date(raw.get("Date"))
            if row_date is not None and (composition_date is None or row_date > composition_date):
                composition_date = row_date
            ticker = cls._tradable_symbol(_clean(raw.get("Ticker")))
            name = _clean(raw.get("Description"))
            cusip = _clean(raw.get("CUSIP"))
            sedol = _clean(raw.get("SEDOL"))
            holding_type, row_type = cls._classify_holding(
                ticker=ticker,
                name=name,
                cusip=cusip,
                sedol=sedol,
            )
            if row_type != "security":
                ticker = None
            if not any((ticker, name, cusip, sedol, _clean(raw.get("Quantity")))):
                continue
            raw_weight = _clean(raw.get("Weight"))
            weight = (
                _decimal(raw_weight)
                if (raw_weight or "").endswith("%")
                else _decimal_percent_points(raw_weight)
            )
            rows.append(
                CanonicalHoldingRow(
                    symbol=ticker,
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) and row_type == "security" else None,
                    sedol=sedol if sedol and row_type == "security" else None,
                    weight=weight,
                    shares=_decimal(raw.get("Quantity")),
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=f"{cls.source_row_prefix}-{symbol}-{position}",
                    extra_data={
                        key: value for key, value in raw.items() if _clean(value) is not None
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _parse_date(value: Any) -> date | None:
        text = _clean(value)
        if text is None:
            return None
        try:
            return datetime.strptime(text, "%m/%d/%Y").date()
        except ValueError:
            return None

    @staticmethod
    def _tradable_symbol(value: str | None) -> str | None:
        candidate = _clean(value)
        if candidate is None:
            return None
        normalized = candidate.upper().strip()
        return normalized if re.fullmatch(r"[A-Z][A-Z0-9.-]{0,11}", normalized) else None

    @staticmethod
    def _classify_holding(
        *,
        ticker: str | None,
        name: str | None,
        cusip: str | None,
        sedol: str | None,
    ) -> tuple[str, str]:
        text = " ".join(part.upper() for part in (ticker, name, cusip, sedol) if part)
        if (
            ticker is None
            and not cusip
            and not sedol
            and any(
                marker in text
                for marker in ("CASH", "DOLLAR", "EURO", "YEN", "KRONA", "POUND", "CURRENCY")
            )
        ):
            return "cash", "cash"
        if re.search(r"\b\d{6}[CP]\d{8}\b", text) or " OPTION" in text:
            return "other", "option"
        if any(marker in text for marker in ("TREASURY", "BILL", "NOTE", "BOND")):
            return "fixed_income", "security"
        if " ETF" in text or " FUND" in text:
            return "fund", "security"
        return "equity", "security"


