class AffiliatedManagersGroupHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Parse AMG's complete issuer-published municipal ETF holdings table."""

    _SYMBOLS = frozenset({"MUNX"})
    _PRODUCT_PAGE_URLS = {
        "MUNX": "https://amgetfs.com/munx/",
    }
    _TABLE_ID = "holdings_table_munx"
    _REQUIRED_HEADERS = (
        "SECURITY NAME",
        "COUPON",
        "MATURITY",
        "CUSIP",
        "PAR VALUE",
        "MARKET VALUE",
        "% OF NET ASSETS",
    )

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        normalized_symbol = symbol.strip().upper()
        product_page_url = self._PRODUCT_PAGE_URLS.get(normalized_symbol)
        if product_page_url is None:
            return super().probe(symbol=symbol, name=name, identifiers=identifiers)
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500"),
            status="ready",
            reason="AMG publishes this ETF's complete current municipal-bond holdings table.",
            source_url=product_page_url,
            issuer_product_id=normalized_symbol,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del source_url, identifiers
        normalized_symbol = symbol.strip().upper()
        product_page_url = self._PRODUCT_PAGE_URLS.get(normalized_symbol)
        if product_page_url is None:
            raise ValueError(
                "Affiliated Managers Group does not have a verified native ETF holdings "
                f"route for {normalized_symbol}."
            )
        response = await self._fetch_product_page(product_page_url)
        rows, composition_date = self._parse_holdings_html(response.text, symbol=normalized_symbol)
        if not rows:
            raise ValueError(
                f"Affiliated Managers Group holdings page did not expose rows for {normalized_symbol}."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            source_url=str(response.url),
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={
                "source_access": "amg_public_munx_complete_holdings_table",
                "source_provider": "affiliated_managers_group",
                "adapter_key": self.adapter_key,
                "source_format": "html",
                "route_resolution": "amg_munx_product_page_holdings_table",
                "table_id": self._TABLE_ID,
                "snapshot_provenance": "amg_native_current_holdings_table",
                **({"composition_date": composition_date.isoformat()} if composition_date else {}),
                **({"as_of_date": composition_date.isoformat()} if composition_date else {}),
            },
        )

    @classmethod
    def _parse_holdings_html(
        cls,
        raw_html: str,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        parser = _HTMLTableByIdParser(table_id=cls._TABLE_ID)
        parser.feed(raw_html)
        headers = tuple(
            value.rstrip("▼").strip() for value in (parser.rows[0] if parser.rows else [])
        )
        if headers != cls._REQUIRED_HEADERS:
            raise ValueError(
                "Affiliated Managers Group holdings table did not expose its expected schema."
            )

        rows: list[CanonicalHoldingRow] = []
        for position, raw in enumerate(parser.rows[1:], start=1):
            if len(raw) != len(cls._REQUIRED_HEADERS):
                continue
            name, coupon, maturity, cusip, par_value, market_value, weight = raw
            cleaned_name = _clean(name)
            cleaned_cusip = _clean(cusip)
            text = " ".join(part.upper() for part in (cleaned_name, cleaned_cusip) if part)
            is_cash = "CASH" in text or "US DOLLAR" in text or "OTHER ASSETS" in text
            if not any((cleaned_name, cleaned_cusip, _clean(market_value), _clean(weight))):
                continue
            rows.append(
                CanonicalHoldingRow(
                    symbol=None,
                    name=cleaned_name,
                    cusip=(
                        cleaned_cusip if not is_cash and _looks_like_cusip(cleaned_cusip) else None
                    ),
                    # AMG renders net-assets weights with a trailing percent sign.
                    weight=_decimal(weight),
                    shares=_decimal(par_value),
                    market_value=_decimal(market_value),
                    currency="USD",
                    holding_type="cash" if is_cash else "fixed_income",
                    row_type="cash" if is_cash else "security",
                    source_row_id=f"amg-{symbol}-{position}",
                    extra_data={
                        "coupon": coupon,
                        "maturity": maturity,
                        "par_value": par_value,
                    },
                )
            )
        return rows, cls._extract_as_of_date(raw_html)

    @staticmethod
    def _extract_as_of_date(raw_html: str) -> date | None:
        match = re.search(r"\bAs\s+of\s+(\d{1,2}/\d{1,2}/\d{4})", raw_html, re.IGNORECASE)
        if not match:
            return None
        try:
            return datetime.strptime(match.group(1), "%m/%d/%Y").date()
        except ValueError:
            return None

    @staticmethod
    async def _fetch_product_page(url: str) -> httpx.Response | requests.Response:
        headers = _issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*")
        try:
            async with httpx.AsyncClient(
                timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS
            ) as client:
                response = await client.get(url, headers=headers, follow_redirects=True)
            response.raise_for_status()
            return response
        except httpx.HTTPStatusError as exc:
            if exc.response.status_code != 403:
                raise
        # AMG's public WordPress edge accepts this same issuer page through
        # requests while rejecting httpx's TLS fingerprint. This is deliberately
        # limited to AMG's verified MUNX route, not a generic fallback.
        response = await asyncio.to_thread(
            requests.get,
            url,
            headers=headers,
            timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS,
            allow_redirects=True,
        )
        response.raise_for_status()
        return response


class RaymondJamesHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Raymond James's issuer-published quarterly ETF investment schedules."""

    _DOCUMENT_BASE_URL = "https://funddocs.filepoint.com/RJETFs/assets/pdfs/"
    _FUNDS = {
        "RJDI": (
            "RJ Eagle GCM Dividend Select Income ETF",
            "RJ_RJDI_Q1.pdf",
        ),
        "RJMI": (
            "RJ Eagle Municipal Income ETF",
            "RJ_RJMI_Q1.pdf",
        ),
        "RJVI": (
            "RJ Eagle Vertical Income ETF",
            "RJ_RJVI_Q1.pdf",
        ),
    }
    _POSITION_RE = re.compile(
        r"^(?P<name>[A-Za-z][^\n]*?)\s+"
        r"(?:\$\s*)?(?P<shares>\(?[\d,]+(?:\.\d+)?\)?)\s+"
        r"(?:\$\s*)?(?P<value>\(?[\d,]+(?:\.\d+)?\)?)$"
    )

    def probe(
        self,
        *,
        symbol: str,
        name: str,
        identifiers: dict[str, str],
    ) -> HoldingsAdapterProbe:
        normalized_symbol = symbol.strip().upper()
        fund = self._FUNDS.get(normalized_symbol)
        if fund is None:
            return super().probe(symbol=symbol, name=name, identifiers=identifiers)
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500"),
            status="ready",
            reason="Raymond James publishes this ETF's complete quarterly schedule of investments.",
            source_url=urljoin(self._DOCUMENT_BASE_URL, fund[1]),
            issuer_product_id=normalized_symbol,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del source_url, identifiers
        normalized_symbol = symbol.strip().upper()
        fund = self._FUNDS.get(normalized_symbol)
        if fund is None:
            raise ValueError(
                "Raymond James does not have a verified native ETF holdings route for "
                f"{normalized_symbol}."
            )
        fund_name, document_name = fund
        document_url = urljoin(self._DOCUMENT_BASE_URL, document_name)
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                document_url,
                headers=_holdings_request_headers(accept="application/pdf,*/*"),
                follow_redirects=True,
            )
        response.raise_for_status()
        rows, composition_date = self._parse_holdings_pdf(
            response.content,
            symbol=normalized_symbol,
            fund_name=fund_name,
        )
        if not rows:
            raise ValueError(
                f"Raymond James's {normalized_symbol} investment schedule contained no parseable positions."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text="\n".join(row.name or "" for row in rows),
            raw_json={"source_format": "pdf", "document_name": document_name},
            source_url=str(response.url),
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "pdf",
                "route_resolution": "raymond_james_fund_portal_quarterly_investment_schedule",
                "document_name": document_name,
                "snapshot_provenance": "raymond_james_native_quarterly_investment_schedule",
                "refresh_frequency": "quarterly_issuer_report",
                **({"composition_date": composition_date.isoformat()} if composition_date else {}),
                **({"as_of_date": composition_date.isoformat()} if composition_date else {}),
            },
        )

    @classmethod
    def _parse_holdings_pdf(
        cls,
        raw_pdf: bytes,
        *,
        symbol: str,
        fund_name: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        from pypdf import PdfReader  # noqa: PLC0415

        text = "\n".join(page.extract_text() or "" for page in PdfReader(BytesIO(raw_pdf)).pages)
        return cls._parse_holdings_text(text, symbol=symbol, fund_name=fund_name)

    @classmethod
    def _parse_holdings_text(
        cls,
        text: str,
        *,
        symbol: str,
        fund_name: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        if fund_name.lower() not in text.lower():
            raise ValueError("Raymond James investment schedule did not match the requested ETF.")
        date_match = re.search(
            r"Schedule of Investments\s+([A-Z][a-z]+ \d{1,2}, \d{4})",
            text,
        )
        if date_match is None:
            raise ValueError("Raymond James investment schedule did not expose an as-of date.")
        composition_date = datetime.strptime(date_match.group(1), "%B %d, %Y").date()
        rows: list[CanonicalHoldingRow] = []
        for line in (item.strip() for item in text.splitlines()):
            match = cls._POSITION_RE.match(line)
            if match is None:
                continue
            name = match.group("name").strip()
            if name.upper().startswith(("NET ASSETS", "TOTAL INVESTMENTS", "TOTAL ASSETS")):
                continue
            shares = _decimal(match.group("shares"))
            market_value = _decimal(match.group("value"))
            if shares is None or market_value is None:
                continue
            normalized_name = name.upper()
            is_cash = any(
                marker in normalized_name
                for marker in (
                    "MONEY MARKET",
                    "CASH",
                    "REPURCHASE",
                    "TREASURY OBLIGATIONS",
                )
            )
            is_fixed_income = not is_cash and (
                bool(re.search(r"\b\d+(?:\.\d+)?%", name))
                or bool(re.search(r"\b\d{2}/\d{2}/\d{4}\b", name))
                or any(marker in normalized_name for marker in ("BOND", "NOTE", "TREASURY"))
            )
            rows.append(
                CanonicalHoldingRow(
                    symbol=None,
                    name=name,
                    shares=shares,
                    market_value=market_value,
                    currency="USD",
                    holding_type=(
                        "cash" if is_cash else "fixed_income" if is_fixed_income else "equity"
                    ),
                    row_type="cash" if is_cash else "security",
                    source_row_id=f"raymond-james-{symbol}-{len(rows) + 1}",
                    extra_data={
                        "source": "raymond_james_quarterly_investment_schedule",
                        "reported_quantity_label": "par" if is_fixed_income else "shares",
                    },
                )
            )
        return rows, composition_date


class OspreyHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Parse Osprey's issuer-published daily single-asset trust disclosures."""

    _FUNDS = {
        "OSOL": ("osol", "Osprey Solana Trust", "Sol", "Solana", "SOL"),
        "OBNB": ("obnb", "Osprey BNB Chain Trust", "BNB", "BNB Chain", "BNB"),
        "ODOT": ("odot", "Osprey Polkadot Trust", "Dot", "Polkadot", "DOT"),
        "OBNK": ("bonk", "Osprey BONK Trust", "Bonk", "BONK", "BONK"),
    }
    _PRODUCT_PAGE_TEMPLATE = "https://ospreyfunds.io/products/{slug}/"

    def probe(
        self,
        *,
        symbol: str,
        name: str,
        identifiers: dict[str, str],
    ) -> HoldingsAdapterProbe:
        normalized_symbol = symbol.strip().upper()
        fund = self._FUNDS.get(normalized_symbol)
        if fund is None:
            return super().probe(symbol=symbol, name=name, identifiers=identifiers)
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500"),
            status="ready",
            reason="Osprey publishes this trust's daily single-asset holdings per share.",
            source_url=self._PRODUCT_PAGE_TEMPLATE.format(slug=fund[0]),
            issuer_product_id=normalized_symbol,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del source_url, identifiers
        normalized_symbol = symbol.strip().upper()
        fund = self._FUNDS.get(normalized_symbol)
        if fund is None:
            raise ValueError(
                "Osprey does not have a verified native holdings route for " f"{normalized_symbol}."
            )
        product_page_url = self._PRODUCT_PAGE_TEMPLATE.format(slug=fund[0])
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*"),
                follow_redirects=True,
            )
        response.raise_for_status()
        row, composition_date = self._parse_holdings_html(
            response.text,
            symbol=normalized_symbol,
            expected_fund_name=fund[1],
            per_share_label=fund[2],
            asset_name=fund[3],
            asset_symbol=fund[4],
        )
        return HoldingsFetchResult(
            rows=[row],
            raw_text=response.text,
            raw_json={"source_format": "html", "single_asset_trust": True},
            source_url=str(response.url),
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "html",
                "route_resolution": "osprey_product_page_daily_single_asset_disclosure",
                "snapshot_provenance": "osprey_native_daily_asset_holdings",
                "refresh_frequency": "daily_issuer_disclosure",
                "composition_date": composition_date.isoformat(),
                "as_of_date": composition_date.isoformat(),
            },
        )

    @staticmethod
    def _parse_holdings_html(
        raw_html: str,
        *,
        symbol: str,
        expected_fund_name: str,
        per_share_label: str,
        asset_name: str,
        asset_symbol: str,
    ) -> tuple[CanonicalHoldingRow, date]:
        text = re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", html.unescape(raw_html)))
        if expected_fund_name.lower() not in text.lower():
            raise ValueError("Osprey product page did not match the requested trust.")
        aum_match = re.search(r"\bAUM†\s+\$?([\d,]+(?:\.\d+)?)", text)
        per_share_match = re.search(
            rf"\b{re.escape(per_share_label)}\s+Per\s+Share††\s+([\d,]+(?:\.\d+)?)",
            text,
        )
        as_of_match = re.search(
            r"holdings of the Trust as of\s+(\d{2}/\d{2}/\d{4})",
            text,
            re.IGNORECASE,
        )
        shares_match = re.search(r"Shares Outstanding\s+([\d,]+(?:\.\d+)?)", text)
        if not all((aum_match, per_share_match, as_of_match, shares_match)):
            raise ValueError("Osprey product page did not expose its expected holdings disclosure.")
        composition_date = datetime.strptime(as_of_match.group(1), "%m/%d/%Y").date()
        per_share = _decimal(per_share_match.group(1))
        shares_outstanding = _decimal(shares_match.group(1))
        market_value = _decimal(aum_match.group(1))
        assert per_share is not None and shares_outstanding is not None and market_value is not None
        return (
            CanonicalHoldingRow(
                symbol=asset_symbol,
                name=asset_name,
                shares=per_share * shares_outstanding,
                market_value=market_value,
                weight=Decimal("1"),
                holding_type="crypto",
                row_type="security",
                source_row_id=f"osprey-{symbol}-{composition_date.isoformat()}",
                extra_data={
                    "source": "osprey_daily_single_asset_disclosure",
                    "asset_units_per_share": str(per_share),
                    "trust_shares_outstanding": str(shares_outstanding),
                },
            ),
            composition_date,
        )


class RedwoodHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Redwood's complete LeaderShares ETF holdings from issuer CSV downloads."""

    _FUNDS: dict[str, tuple[str, str]] = {
        "LSAT": (
            "leadershares-tactical-focused-etf",
            "Leadershares Alphafactor Tactical Focused ETF",
        ),
        "DYLD": (
            "leadershares-dynamic-yield-etf",
            "Leadershares Dynamic Yield ETF",
        ),
    }
    _CURRENCY_CODES = frozenset({"CAD", "EUR", "GBP", "JPY", "USD"})

    def probe(
        self,
        *,
        symbol: str,
        name: str,
        identifiers: dict[str, str],
    ) -> HoldingsAdapterProbe:
        normalized_symbol = symbol.strip().upper()
        fund = self._FUNDS.get(normalized_symbol)
        if fund is None:
            return super().probe(symbol=symbol, name=name, identifiers=identifiers)
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500"),
            status="ready",
            reason="Redwood publishes this LeaderShares ETF's complete current holdings CSV.",
            source_url=self._holdings_url(fund[0]),
            issuer_product_id=normalized_symbol,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del source_url, identifiers
        normalized_symbol = symbol.strip().upper()
        fund = self._FUNDS.get(normalized_symbol)
        if fund is None:
            raise ValueError(
                "Redwood does not have a verified native LeaderShares holdings route for "
                f"{normalized_symbol}."
            )
        slug, expected_fund_name = fund
        holdings_url = self._holdings_url(slug)
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        response: httpx.Response | None = None
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            for attempt in range(3):
                response = await self._get_with_timeout_retry(
                    client,
                    holdings_url,
                    headers=_holdings_request_headers(accept="text/csv,*/*"),
                )
                response.raise_for_status()
                try:
                    rows, composition_date = self._parse_holdings_csv(
                        response.text,
                        symbol=normalized_symbol,
                        expected_fund_name=expected_fund_name,
                    )
                except ValueError:
                    if attempt == 2:
                        raise
                    await asyncio.sleep(0.25 * (attempt + 1))
                    continue
                if rows:
                    break
                if attempt == 2:
                    break
                await asyncio.sleep(0.25 * (attempt + 1))
        if not rows:
            raise ValueError(f"Redwood returned no holdings for {normalized_symbol}.")
        if response is None or composition_date is None:
            raise ValueError(f"Redwood returned incomplete holdings for {normalized_symbol}.")
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json={"source_format": "csv"},
            source_url=str(response.url),
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "redwood_leadershares_fund_scoped_holdings_download",
                "snapshot_provenance": "redwood_native_current_holdings_csv",
                "composition_date": composition_date.isoformat(),
                "as_of_date": composition_date.isoformat(),
            },
        )

    @staticmethod
    def _holdings_url(slug: str) -> str:
        return "https://www.leadersharesetfs.com/funds/holdings-download?fund=" + slug

    @staticmethod
    async def _get_with_timeout_retry(
        client: httpx.AsyncClient,
        url: str,
        *,
        headers: dict[str, str],
    ) -> httpx.Response:
        for attempt in range(3):
            try:
                return await client.get(url, headers=headers, follow_redirects=True)
            except httpx.TimeoutException:
                if attempt == 2:
                    raise
                await asyncio.sleep(0.25 * (attempt + 1))
        raise AssertionError("unreachable")

    @classmethod
    def _parse_holdings_csv(
        cls,
        raw_csv: str,
        *,
        symbol: str,
        expected_fund_name: str,
    ) -> tuple[list[CanonicalHoldingRow], date]:
        lines = [line for line in raw_csv.splitlines() if line.strip()]
        if len(lines) < 3 or cls._normalized_name(lines[0]) != cls._normalized_name(
            expected_fund_name
        ):
            raise ValueError("Redwood holdings CSV did not match the requested ETF.")
        date_match = re.search(r"as of\s+(\d{2}/\d{2}/\d{4})", lines[1], re.IGNORECASE)
        if date_match is None:
            raise ValueError("Redwood holdings CSV did not expose an as-of date.")
        composition_date = datetime.strptime(date_match.group(1), "%m/%d/%Y").date()
        table_rows = list(csv.reader(lines[2:]))
        headers = [header.strip() for header in (table_rows[0] if table_rows else [])]
        required_headers = {
            "Name",
            "Security Identifier",
            "Symbol",
            "Net Assets %",
            "Shares Held",
            "Market Value",
        }
        if not required_headers.issubset(set(headers)):
            raise ValueError("Redwood holdings CSV did not expose the expected complete schema.")

        rows: list[CanonicalHoldingRow] = []
        for position, values in enumerate(table_rows[1:], start=1):
            raw = dict(zip(headers, values, strict=False))
            name = _clean(raw.get("Name"))
            source_symbol = _clean(raw.get("Symbol"))
            source_identifier = _clean(raw.get("Security Identifier"))
            row_type, holding_type = cls._classify_row(name=name, source_symbol=source_symbol)
            normalized_row_symbol = (
                cls._tradable_symbol(source_symbol) if row_type == "security" else None
            )
            if not any([normalized_row_symbol, name, source_identifier]):
                continue
            rows.append(
                CanonicalHoldingRow(
                    symbol=normalized_row_symbol,
                    name=name,
                    cusip=source_identifier if _looks_like_cusip(source_identifier) else None,
                    weight=_decimal_percent_points(raw.get("Net Assets %")),
                    shares=_decimal(raw.get("Shares Held")),
                    market_value=_decimal(raw.get("Market Value")),
                    currency="USD",
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=f"{symbol}:{position}",
                    extra_data={
                        "source_symbol": source_symbol,
                        "source_identifier": source_identifier,
                        "market_price": _clean(raw.get("Market Price")),
                        "market_value_percent": _clean(raw.get("Market Value %")),
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _normalized_name(value: str) -> str:
        return re.sub(r"[^a-z0-9]+", "", value.lower())

    @staticmethod
    def _tradable_symbol(value: str | None) -> str | None:
        if not value:
            return None
        candidate = value.strip().upper().removesuffix(" US")
        return candidate if re.fullmatch(r"[A-Z][A-Z0-9.\-]{0,14}", candidate) else None

    @staticmethod
    def _classify_row(*, name: str | None, source_symbol: str | None) -> tuple[str, str]:
        text = " ".join(part for part in (name, source_symbol) if part).upper()
        symbol = (source_symbol or "").strip().upper()
        if any(marker in text for marker in ("CASH", "SWEEP", "RECEIVABLE", "PAYABLE")):
            return "cash", "cash"
        if "DOLLAR" in text or symbol in RedwoodHoldingsAdapter._CURRENCY_CODES:
            return "cash", "forex"
        if any(marker in text for marker in ("OPTION", "FUTURE", "SWAP", "FORWARD")):
            return "other", "derivative"
        if "ETF" in text or "FUND" in text:
            return "security", "fund"
        if any(marker in text for marker in ("TREASURY", "BILL", "BOND", "NOTE")):
            return "security", "fixed_income"
        return "security", "equity"


class ProSharesHoldingsAdapter(IssuerCsvHoldingsAdapter):
    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        product_page_url = self.resolve_product_page_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers or {},
        )
        if not product_page_url:
            return await super().fetch_latest(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                source_url=source_url,
                identifiers=identifiers,
            )

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,*/*"),
                follow_redirects=True,
            )
        response.raise_for_status()
        rows = parse_html_holdings_table_by_id(response.text, table_id="holdings")
        if not rows:
            return await super().fetch_latest(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                source_url=source_url,
                identifiers=identifiers,
            )
        as_of_date = self._extract_as_of_date(response.text)
        return HoldingsFetchResult(
            source_url=str(response.url),
            source_identifier=issuer_product_id or symbol.strip().upper(),
            rows=rows,
            raw_text=response.text,
            raw_json=None,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "html",
                "route_resolution": "issuer_html_holdings_table",
                "table_id": "holdings",
                "composition_date": as_of_date.isoformat() if as_of_date else None,
                "as_of_date": as_of_date.isoformat() if as_of_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _extract_as_of_date(raw_html: str) -> date | None:
        match = re.search(r"\bas\s+of\s+(\d{1,2}/\d{1,2}/\d{4})", raw_html, re.IGNORECASE)
        if not match:
            return None
        try:
            return datetime.strptime(match.group(1), "%m/%d/%Y").date()
        except ValueError:
            return None


class RoundhillHoldingsAdapter(IssuerCsvHoldingsAdapter):
    daily_holdings_url_template = (
        "https://www.roundhillinvestments.com/assets/data/"
        "FilepointRoundhill.40RU.RU_Holdings_{date_mmddyyyy}.csv"
    )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        failures: list[str] = []
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            for days_back in range(16):
                source_date = date.today() - timedelta(days=days_back)
                resolved_source_url = self.daily_holdings_url_template.format(
                    date_mmddyyyy=source_date.strftime("%m%d%Y"),
                )
                try:
                    response = await client.get(
                        resolved_source_url,
                        headers=_holdings_request_headers(accept="text/csv,*/*"),
                        follow_redirects=True,
                    )
                    response.raise_for_status()
                except Exception as exc:  # noqa: BLE001 - try previous daily files.
                    failures.append(f"{source_date.isoformat()}: {exc}")
                    continue
                rows, composition_date = self._parse_roundhill_csv(
                    response.text,
                    account_symbol=normalized_symbol,
                )
                if rows:
                    return HoldingsFetchResult(
                        rows=rows,
                        raw_text=response.text,
                        raw_json=None,
                        source_url=str(response.url),
                        source_identifier=normalized_symbol,
                        legal_metadata={
                            "source_access": self.config.source_access,
                            "source_provider": self.source_provider,
                            "adapter_key": self.adapter_key,
                            "source_format": "csv",
                            "route_resolution": "issuer_daily_holdings_csv",
                            "composition_date": (
                                composition_date.isoformat() if composition_date else None
                            ),
                            "as_of_date": composition_date.isoformat()
                            if composition_date
                            else None,
                            "source_file_date": source_date.isoformat(),
                            "terms_note": self.config.terms_note,
                        },
                    )
                failures.append(f"{source_date.isoformat()}: no {normalized_symbol} rows")
        raise ValueError(
            f"Roundhill did not publish parseable {normalized_symbol} holdings "
            f"in the latest 16 daily files: {'; '.join(failures[-5:])}"
        )

    def _parse_roundhill_csv(
        self,
        raw_csv: str,
        *,
        account_symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        reader = csv.DictReader(StringIO(raw_csv.strip()))
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for index, item in enumerate(reader, start=1):
            if (item.get("Account") or "").strip().upper() != account_symbol:
                continue
            if composition_date is None:
                composition_date = self._parse_roundhill_date(item.get("Date"))
            raw_symbol = _clean(item.get("StockTicker"))
            holding_type = "cash" if raw_symbol == "Cash&Other" else "security"
            rows.append(
                CanonicalHoldingRow(
                    symbol=raw_symbol if holding_type != "cash" else None,
                    name=_clean(item.get("SecurityName")),
                    cusip=_clean(item.get("CUSIP")),
                    weight=_decimal(item.get("Weightings")),
                    shares=_decimal(item.get("Shares")),
                    market_value=_decimal(item.get("MarketValue")),
                    holding_type=holding_type,
                    row_type="cash" if holding_type == "cash" else "security",
                    source_row_id=str(index),
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _parse_roundhill_date(value: str | None) -> date | None:
        text = _clean(value)
        if not text:
            return None
        try:
            return datetime.strptime(text, "%m/%d/%Y").date()
        except ValueError:
            return None


class DefianceHoldingsAdapter(IssuerCsvHoldingsAdapter):
    def resolve_product_page_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        explicit = super().resolve_product_page_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers,
        )
        if explicit:
            return explicit
        normalized_symbol = symbol.strip().lower()
        if not normalized_symbol:
            return None
        return f"https://www.defianceetfs.com/{normalized_symbol}-full-holdings/"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        product_page_url = source_url or self.resolve_product_page_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers or {},
        )
        if not product_page_url:
            return await super().fetch_latest(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                source_url=source_url,
                identifiers=identifiers,
            )

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(accept="text/html,*/*"),
                follow_redirects=True,
            )
        response.raise_for_status()
        rows = parse_html_holdings_table_by_id(response.text, table_id="table-full-holdings")
        if not rows:
            return await super().fetch_latest(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                source_url=source_url,
                identifiers=identifiers,
            )
        as_of_date = self._extract_as_of_date(response.text)
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json=None,
            source_url=str(getattr(response, "url", product_page_url)),
            source_identifier=issuer_product_id or symbol.strip().upper(),
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "html",
                "route_resolution": "issuer_full_holdings_html_table",
                "table_id": "table-full-holdings",
                "composition_date": as_of_date.isoformat() if as_of_date else None,
                "as_of_date": as_of_date.isoformat() if as_of_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _extract_as_of_date(raw_html: str) -> date | None:
        match = re.search(r"\bData\s+as\s+of\s+(\d{1,2}/\d{1,2}/\d{4})", raw_html, re.IGNORECASE)
        if not match:
            return None
        try:
            return datetime.strptime(match.group(1), "%m/%d/%Y").date()
        except ValueError:
            return None


class AdvisorSharesHoldingsAdapter(IssuerCsvHoldingsAdapter):
    def resolve_source_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        if source_url:
            return source_url.strip()
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            return None
        return (
            "https://advisorshares.com/wp-content/uploads/csv/holdings/"
            f"AdvisorShares_{normalized_symbol}_Holdings_File.csv"
        )

    def source_request_headers(self, *, source_url: str) -> dict[str, str]:
        headers = _holdings_request_headers(accept="text/csv,*/*")
        headers["Referer"] = "https://advisorshares.com/"
        return headers

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        resolved_source_url = self.resolve_source_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers,
            source_url=source_url,
        )
        if not resolved_source_url:
            raise ValueError(f"AdvisorShares holdings route is unavailable for {normalized_symbol}")
        response = await asyncio.to_thread(
            requests.get,
            resolved_source_url,
            headers=self.source_request_headers(source_url=resolved_source_url),
            timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS,
        )
        response.raise_for_status()
        rows = parse_holdings_csv(response.text)
        result = HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json=None,
            source_url=str(getattr(response, "url", resolved_source_url)),
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={},
        )
        rows = [
            row
            for row in result.rows
            if str(row.extra_data.get("Account Symbol") or "").strip().upper()
            in {"", normalized_symbol}
        ]
        composition_date = self._extract_composition_date(rows)
        result.rows = rows
        result.legal_metadata = {
            **(result.legal_metadata or {}),
            "source_access": self.config.source_access,
            "source_provider": self.source_provider,
            "adapter_key": self.adapter_key,
            "source_format": "csv",
            "route_resolution": "issuer_symbol_holdings_csv",
            "composition_date": composition_date.isoformat() if composition_date else None,
            "as_of_date": composition_date.isoformat() if composition_date else None,
            "terms_note": self.config.terms_note,
        }
        return result

    @staticmethod
    def _extract_composition_date(rows: list[CanonicalHoldingRow]) -> date | None:
        for row in rows:
            text = _clean(row.extra_data.get("Date"))
            if not text:
                continue
            try:
                return datetime.strptime(text, "%m/%d/%Y").date()
            except ValueError:
                return None
        return None


class AngelOakHoldingsAdapter(IssuerCsvHoldingsAdapter):
    source_url = "https://angeloakcapital.com/secure-gs/Angel_Oak_ETF_Holdings.csv"

    def resolve_source_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        return source_url.strip() if source_url else self.source_url

    def source_request_headers(self, *, source_url: str) -> dict[str, str]:
        headers = _holdings_request_headers(accept="text/csv,application/octet-stream,*/*")
        headers["Referer"] = "https://angeloakcapital.com/investments/?aofund=&vehicle=etf"
        return headers

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = (issuer_product_id or symbol).strip().upper()
        resolved_source_url = self.resolve_source_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        if not resolved_source_url:
            raise ValueError(f"Angel Oak holdings route is unavailable for {normalized_symbol}.")

        response = await asyncio.to_thread(
            requests.get,
            resolved_source_url,
            headers=self.source_request_headers(source_url=resolved_source_url),
            timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS,
            allow_redirects=True,
        )
        response.raise_for_status()
        rows, composition_date = self._parse_angel_oak_csv(
            response.text,
            account_symbol=normalized_symbol,
        )
        if not rows:
            raise ValueError(
                f"Angel Oak did not publish parseable {normalized_symbol} rows "
                "in the current combined ETF holdings file."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json=None,
            source_url=str(getattr(response, "url", resolved_source_url)),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "issuer_combined_account_holdings_csv",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @classmethod
    def _parse_angel_oak_csv(
        cls,
        raw_csv: str,
        *,
        account_symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        reader = csv.DictReader(StringIO(raw_csv.strip()))
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for index, item in enumerate(reader, start=1):
            if (item.get("Account") or "").strip().upper() != account_symbol:
                continue
            row_date = cls._parse_angel_oak_date(item.get("Date"))
            if row_date and (composition_date is None or row_date > composition_date):
                composition_date = row_date
            raw_symbol = _clean(item.get("StockTicker"))
            cusip = _clean(item.get("CUSIP"))
            symbol = None if _looks_like_cusip(raw_symbol) else raw_symbol
            if cusip is None and _looks_like_cusip(raw_symbol):
                cusip = raw_symbol
            holding_type = cls._holding_type(
                symbol=symbol,
                name=_clean(item.get("SecurityName")),
                money_market_flag=item.get("MoneyMarketFlag"),
            )
            row_type = "cash" if holding_type == "cash" else "security"
            rows.append(
                CanonicalHoldingRow(
                    symbol=symbol if row_type != "cash" else None,
                    name=_clean(item.get("SecurityName")),
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    weight=_decimal(item.get("Weightings")),
                    shares=_decimal(item.get("Shares")),
                    market_value=_decimal(item.get("MarketValue")),
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=f"{account_symbol}-{index}",
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _parse_angel_oak_date(value: str | None) -> date | None:
        text = _clean(value)
        if not text:
            return None
        for fmt in ("%m/%d/%Y", "%m/%d/%y"):
            try:
                return datetime.strptime(text, fmt).date()
            except ValueError:
                continue
        return None

    @staticmethod
    def _holding_type(*, symbol: str | None, name: str | None, money_market_flag: Any) -> str:
        text = " ".join(
            part.upper()
            for part in [
                symbol,
                name,
                money_market_flag,
            ]
            if part
        )
        if "CASH" in text or "MONEY MARKET" in text or text.endswith(" MM"):
            return "cash"
        return "fixed_income"


class BrookfieldHoldingsAdapter(AngelOakHoldingsAdapter):
    """Fetch the Angel Oak-published portfolio for Brookfield's registered TRBF ETF.

    ETFDB identifies TRBF under Brookfield Asset Management, while Angel Oak is
    the legal issuer and publishes the complete, account-scoped holdings export.
    The narrow scope makes the publisher relationship explicit instead of using
    Angel Oak's aggregate file as an unbounded fallback for Brookfield.
    """

    SUPPORTED_SYMBOLS = frozenset({"TRBF"})

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in self.SUPPORTED_SYMBOLS:
            sec_cik = _identifier(identifiers, "sec_cik")
            if sec_cik:
                return HoldingsAdapterProbe(
                    adapter_key=self.adapter_key,
                    confidence=Decimal("0.7800"),
                    status="ready",
                    reason=(
                        "No native Brookfield publisher route is configured for this ETF "
                        "symbol, but SEC identifiers permit the EDGAR fallback."
                    ),
                    source_url=f"https://data.sec.gov/submissions/CIK{sec_cik.zfill(10)}.json",
                    issuer_product_id=_identifier(identifiers, "issuer_product_id", "fund_id"),
                )
            return HoldingsAdapterProbe(
                adapter_key=self.adapter_key,
                confidence=Decimal("0"),
                status="needs_provider_implementation",
                reason="No verified Brookfield publisher route is configured for this ETF symbol.",
                source_url=None,
                issuer_product_id=None,
            )
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9000"),
            status="ready",
            reason=(
                "Brookfield's registered TRBF ETF is legally issued by Angel Oak, which "
                "publishes its complete current account-scoped portfolio export."
            ),
            source_url=self.source_url,
            issuer_product_id=normalized_symbol,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in self.SUPPORTED_SYMBOLS:
            raise ValueError("Brookfield's configured US ETF route supports only TRBF.")
        if source_url is not None:
            raise ValueError("Brookfield holdings use the verified Angel Oak publisher route.")

        supplied_identifier = (
            _identifier(identifiers or {}, "issuer_product_id", "fund_id") or issuer_product_id
        )
        if supplied_identifier and supplied_identifier.strip().upper() != normalized_symbol:
            raise ValueError(
                "Brookfield ETF identifiers must match the requested TRBF fund symbol."
            )

        result = await super().fetch_latest(
            symbol=normalized_symbol,
            issuer_product_id=normalized_symbol,
            identifiers={},
        )
        result.legal_metadata = {
            **(result.legal_metadata or {}),
            "source_access": self.config.source_access,
            "source_provider": "angel_oak",
            "adapter_key": self.adapter_key,
            "route_resolution": "angel_oak_publisher_combined_account_holdings_csv_for_brookfield_managed_etf",
            "portfolio_manager": "brookfield_asset_management",
        }
        return result


class SterlingCapitalHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Sterling Capital's current ETF holdings from its fund-scoped PDF exports."""

    _FUND_BY_SYMBOL = {
        "SCEC": ("scec", "Enhanced Core Bond ETF"),
        "SCEP": ("scep", "Hedged Equity Premium Income ETF"),
        "SCMC": ("scmc", "Multi-Strategy Income ETF"),
        "SCNM": ("scnm", "National Municipal Bond ETF"),
        "SCSB": ("scsb", "Short-Term Corporate Bond ETF"),
        "SCUB": ("scub", "Ultra Short Bond ETF"),
    }
    _PDF_ROW_RE = re.compile(
        r"^(?P<cusip>[A-Z0-9]{9})\s+(?P<name>.+?)\s+"
        r"(?P<shares>\(?[\d,]+(?:\.\d+)?\)?)\s+"
        r"\$(?P<price>[\d,]+(?:\.\d+)?)\s+"
        r"(?P<weight>-?[\d.]+%)$"
    )

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name
        normalized_symbol = symbol.strip().upper()
        fund = self._FUND_BY_SYMBOL.get(normalized_symbol)
        has_sec_fallback = bool(_identifier(identifiers, "sec_cik", "cik"))
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500") if fund else Decimal("0.6000"),
            status="ready" if fund or has_sec_fallback else "needs_issuer_route",
            reason=(
                "Sterling Capital publishes this ETF's complete current holdings PDF on its public fund page."
                if fund
                else (
                    "No verified Sterling Capital public holdings route is configured for this ETF symbol; "
                    "SEC filing fallback is available."
                    if has_sec_fallback
                    else "No verified Sterling Capital public holdings route is configured for this ETF symbol."
                )
            ),
            source_url=self._holdings_url(fund[0]) if fund else None,
            issuer_product_id=normalized_symbol if fund else None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, source_url, identifiers
        normalized_symbol = symbol.strip().upper()
        fund = self._FUND_BY_SYMBOL.get(normalized_symbol)
        if fund is None:
            raise ValueError(
                f"No verified Sterling Capital public holdings route is configured for {normalized_symbol or 'an empty symbol'}."
            )
        slug, fund_name = fund
        holdings_url = self._holdings_url(slug)
        response = await asyncio.to_thread(
            requests.get,
            holdings_url,
            headers={
                **_holdings_request_headers(accept="application/pdf,*/*"),
                "Referer": f"https://sterlingcapital.com/investments/exchange-traded-funds/{slug}/",
            },
            timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS,
            allow_redirects=True,
        )
        response.raise_for_status()
        raw_text = self._extract_pdf_text(response.content)
        rows, composition_date = self._parse_holdings_text(
            raw_text,
            symbol=normalized_symbol,
            expected_fund_name=fund_name,
        )
        if not rows:
            raise ValueError(
                f"Sterling Capital's {normalized_symbol} holdings PDF returned no parseable positions."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=raw_text,
            raw_json={"source_format": "pdf", "fund_slug": slug, "row_count": len(rows)},
            source_url=str(getattr(response, "url", holdings_url)),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "pdf",
                "route_resolution": "issuer_fund_scoped_current_holdings_pdf",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
                "source_quality": "issuer_reported_current_holdings",
                "snapshot_provenance": "sterling_capital_issuer_native_holdings_pdf",
            },
        )

    @staticmethod
    def _holdings_url(slug: str) -> str:
        return (
            "https://sterlingcapital.com/investments/exchange-traded-funds/"
            f"{slug}/export-portfolio-holdings/"
        )

    @staticmethod
    def _extract_pdf_text(raw_pdf: bytes) -> str:
        from pypdf import PdfReader  # noqa: PLC0415

        reader = PdfReader(BytesIO(raw_pdf), strict=False)
        return "\n".join(page.extract_text() or "" for page in reader.pages)

    @classmethod
    def _parse_holdings_text(
        cls,
        raw_text: str,
        *,
        symbol: str,
        expected_fund_name: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        if (
            "STERLING CAPITAL" not in raw_text.upper()
            or expected_fund_name.upper() not in raw_text.upper()
        ):
            raise ValueError(
                f"Sterling Capital holdings PDF identity did not match requested ETF {symbol}."
            )
        date_match = re.search(r"As\s+of\s+(\d{2}\.\d{2}\.\d{4})", raw_text, re.IGNORECASE)
        composition_date = (
            datetime.strptime(date_match.group(1), "%m.%d.%Y").date() if date_match else None
        )
        rows: list[CanonicalHoldingRow] = []
        for source_row_id, line in enumerate(raw_text.splitlines(), start=1):
            match = cls._PDF_ROW_RE.match(re.sub(r"\s+", " ", line.strip()))
            if match is None:
                continue
            cusip = match.group("cusip").upper()
            name = match.group("name").strip()
            text = name.upper()
            is_cash = "MONEY MARKET" in text or "CASH" in text
            fixed_income_symbols = {"SCEC", "SCMC", "SCNM", "SCSB", "SCUB"}
            holding_type = (
                "cash"
                if is_cash
                else ("fixed_income" if symbol in fixed_income_symbols else "equity")
            )
            shares = _decimal(match.group("shares"))
            price = _decimal(match.group("price"))
            rows.append(
                CanonicalHoldingRow(
                    symbol=None,
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    weight=_decimal(match.group("weight")),
                    shares=shares,
                    market_value=(shares * price)
                    if shares is not None and price is not None
                    else None,
                    currency="USD",
                    holding_type=holding_type,
                    row_type="cash" if is_cash else "security",
                    source_row_id=f"{symbol}-{source_row_id}",
                    extra_data={
                        "source": "sterling_capital_issuer_holdings_pdf",
                        "price": match.group("price"),
                    },
                )
            )
        return rows, composition_date


class SterlingFundManagementHoldingsAdapter(SterlingCapitalHoldingsAdapter):
    """Fetch Sterling Fund Management's SCMC portfolio from its publisher disclosure.

    Sterling Fund Management is the registered issuer of SCMC, while Sterling
    Capital hosts the fund-scoped public PDF.  Keep that relationship explicit
    instead of silently routing this identity through the Sterling Capital
    adapter registration.
    """

    _FUND_BY_SYMBOL = {
        "SCMC": ("scmc", "Multi-Strategy Income ETF"),
    }

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name
        normalized_symbol = symbol.strip().upper()
        fund = self._FUND_BY_SYMBOL.get(normalized_symbol)
        has_sec_fallback = bool(_identifier(identifiers, "sec_cik", "cik"))
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500") if fund else Decimal("0.6000"),
            status="ready" if fund or has_sec_fallback else "needs_issuer_route",
            reason=(
                "Sterling Fund Management's SCMC portfolio is published in Sterling Capital's "
                "complete current fund-scoped holdings PDF."
                if fund
                else (
                    "No verified Sterling Fund Management public holdings route is configured for this ETF symbol; "
                    "SEC filing fallback is available."
                    if has_sec_fallback
                    else "No verified Sterling Fund Management public holdings route is configured for this ETF symbol."
                )
            ),
            source_url=self._holdings_url(fund[0]) if fund else None,
            issuer_product_id=normalized_symbol if fund else None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in self._FUND_BY_SYMBOL:
            raise ValueError(
                "Sterling Fund Management has a verified public holdings route only for SCMC."
            )
        result = await super().fetch_latest(
            symbol=normalized_symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        metadata = {
            **(result.legal_metadata or {}),
            "source_provider": self.source_provider,
            "adapter_key": self.adapter_key,
            "route_resolution": "sterling_capital_publisher_current_holdings_pdf_for_sterling_fund_scmc",
            "snapshot_provenance": "sterling_fund_management_issuer_native_holdings_pdf",
        }
        return replace(result, legal_metadata=metadata)


