class SymmetryHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Symmetry Panoramic SMOM holdings from its public FilePoint app."""

    PRODUCT_PAGE_URL = "https://panoramicfunds.com/symmetry-panoramic-sector-momentum-etf/"
    APP_URL = "https://smometf.filepoint.live/"
    APP_SCRIPT_URL = "https://smometf.filepoint.live/assets/js/app.js"
    HOLDINGS_URL_TEMPLATE = (
        "https://smometf.filepoint.live/assets/data/"
        "SEI_Symmetry_Tradedate_Holdings_{report_date}.txt"
    )
    SUPPORTED_SYMBOLS = {"SMOM"}
    EXPECTED_FUND_ID = "6420"
    EXPECTED_FUND_NAME = "Symmetry Panoramic Sector Momentum ETF"
    EXPECTED_FUND_CUSIP = "87190B888"

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name
        normalized_symbol = symbol.strip().upper()
        has_sec_fallback = bool(_identifier(identifiers, "sec_cik", "cik"))
        supported = normalized_symbol in self.SUPPORTED_SYMBOLS
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500") if supported else Decimal("0.3000"),
            status="ready" if supported or has_sec_fallback else "needs_issuer_route",
            reason=(
                "Symmetry publishes SMOM's complete current holdings through its "
                "public Panoramic Funds page and FilePoint app."
                if supported
                else "No verified Symmetry native holdings route is configured for this ETF; "
                "SEC EDGAR remains available as fallback."
                if has_sec_fallback
                else "No verified Symmetry native holdings route is configured for this ETF."
            ),
            source_url=self.PRODUCT_PAGE_URL if supported else None,
            issuer_product_id=normalized_symbol or None,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol not in self.SUPPORTED_SYMBOLS:
            raise ValueError(
                f"No verified Symmetry native holdings route is configured for "
                f"{normalized_symbol or 'an empty symbol'}."
            )
        if source_url and source_url.rstrip("/") not in {
            self.PRODUCT_PAGE_URL.rstrip("/"),
            self.APP_URL.rstrip("/"),
        }:
            raise ValueError(
                "Symmetry holdings must use the verified Panoramic product page or FilePoint app."
            )

        product_response = await self._fetch_public_url(
            self.PRODUCT_PAGE_URL,
            headers=_issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*"),
            allow_requests_fallback=True,
        )
        self._validate_product_page(product_response.text)
        app_response = await self._fetch_public_url(
            self.APP_URL,
            headers=_issuer_page_request_headers(accept="text/html,application/xhtml+xml,*/*"),
        )
        self._validate_filepoint_app(app_response.text)
        script_response = await self._fetch_public_url(
            self.APP_SCRIPT_URL,
            headers=_issuer_page_request_headers(
                accept="application/javascript,text/javascript,*/*"
            ),
        )
        self._validate_app_script(script_response.text)
        holdings_response = await self._fetch_latest_holdings_export()
        rows, composition_date = self._parse_holdings_export(holdings_response.text)
        if not rows:
            raise ValueError("Symmetry's FilePoint holdings export returned no SMOM rows.")
        return HoldingsFetchResult(
            rows=rows,
            raw_text=holdings_response.text,
            raw_json={
                "source_format": "issuer_filepoint_pipe_delimited_holdings_txt",
                "row_count": len(rows),
            },
            source_url=str(holdings_response.url),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "txt",
                "route_resolution": "symmetry_panoramic_filepoint_dated_complete_holdings_txt",
                "product_page_url": str(product_response.url),
                "filepoint_app_url": str(app_response.url),
                "fund_script_url": str(script_response.url),
                "snapshot_provenance": "symmetry_native_current_holdings_txt",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    async def _fetch_public_url(
        url: str,
        *,
        headers: dict[str, str],
        allow_requests_fallback: bool = False,
    ) -> httpx.Response | requests.Response:
        try:
            async with httpx.AsyncClient(
                timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS
            ) as client:
                response = await client.get(url, headers=headers, follow_redirects=True)
            response.raise_for_status()
            return response
        except httpx.HTTPStatusError as exc:
            if not allow_requests_fallback or exc.response.status_code != 403:
                raise
        response = await asyncio.to_thread(
            requests.get,
            url,
            headers=headers,
            timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS,
            allow_redirects=True,
        )
        response.raise_for_status()
        return response

    async def _fetch_latest_holdings_export(self) -> httpx.Response:
        headers = _holdings_request_headers(accept="text/plain,text/csv,*/*")
        headers["Referer"] = self.APP_URL
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            for offset in range(10):
                report_date = (date.today() - timedelta(days=offset)).strftime("%m%d%Y")
                url = self.HOLDINGS_URL_TEMPLATE.format(report_date=report_date)
                response = await client.get(url, headers=headers, follow_redirects=True)
                if response.status_code == 404:
                    continue
                response.raise_for_status()
                if response.text.strip():
                    return response
        raise ValueError("No recent Symmetry dated holdings export was available.")

    @classmethod
    def _validate_product_page(cls, raw_html: str) -> None:
        normalized_html = html.unescape(raw_html)
        if (
            "SMOM" not in normalized_html
            or "Sector Momentum ETF" not in normalized_html
            or cls.APP_URL not in normalized_html
        ):
            raise ValueError(
                "Symmetry's Panoramic product page did not declare the SMOM FilePoint app."
            )

    @classmethod
    def _validate_filepoint_app(cls, raw_html: str) -> None:
        normalized_html = html.unescape(raw_html)
        if (
            "Symmetry | FilePoint Framework" not in normalized_html
            or "assets/js/app.js" not in normalized_html
        ):
            raise ValueError("Symmetry's FilePoint app did not declare its application script.")

    @classmethod
    def _validate_app_script(cls, raw_script: str) -> None:
        if (
            "SEI_Symmetry_Tradedate_Holdings_" not in raw_script
            or "percent_of_net_assets" not in raw_script
        ):
            raise ValueError(
                "Symmetry's FilePoint app script did not declare its complete holdings export."
            )

    @classmethod
    def _parse_holdings_export(cls, raw_text: str) -> tuple[list[CanonicalHoldingRow], date | None]:
        reader = csv.DictReader(StringIO(raw_text), delimiter="|")
        required_headers = {
            "date",
            "fund_id",
            "fund_name",
            "fund_cusip",
            "fund_ticker",
            "security_cusip",
            "security_ticker",
            "security_description",
            "quantity",
            "market_value",
            "percent_of_net_assets",
        }
        if not required_headers.issubset(set(reader.fieldnames or [])):
            return [], None

        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for index, raw in enumerate(reader, start=1):
            if (_clean(raw.get("fund_ticker")) or "").upper() != "SMOM":
                continue
            if _clean(raw.get("fund_id")) != cls.EXPECTED_FUND_ID:
                continue
            if (_clean(raw.get("fund_name")) or "").lower() != cls.EXPECTED_FUND_NAME.lower():
                continue
            if _clean(raw.get("fund_cusip")) != cls.EXPECTED_FUND_CUSIP:
                continue
            source_date = _clean(raw.get("date"))
            if source_date:
                try:
                    parsed_date = datetime.strptime(source_date, "%m/%d/%Y").date()
                    composition_date = (
                        max(composition_date, parsed_date) if composition_date else parsed_date
                    )
                except ValueError:
                    pass
            name = _clean(raw.get("security_description"))
            raw_symbol = _clean(raw.get("security_ticker"))
            cusip = _clean(raw.get("security_cusip"))
            isin = _clean(raw.get("security_isin"))
            sedol = _clean(raw.get("security_sedol"))
            if not any((name, raw_symbol, cusip, isin, sedol)):
                continue
            holding_type, row_type = cls._classify_holding(
                security_group=_clean(raw.get("security_group")),
                security_type=_clean(raw.get("security_type")),
                name=name,
            )
            rows.append(
                CanonicalHoldingRow(
                    symbol=raw_symbol if row_type != "cash" and raw_symbol else None,
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    isin=isin or None,
                    sedol=sedol or None,
                    weight=_decimal_percent_points(raw.get("percent_of_net_assets")),
                    shares=_decimal(raw.get("quantity")),
                    market_value=_decimal(raw.get("market_value")),
                    currency="USD" if row_type == "cash" else None,
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=f"symmetry-SMOM-{index}",
                    extra_data={
                        key: value
                        for key, value in raw.items()
                        if key and _clean(value) is not None
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _classify_holding(
        *,
        security_group: str | None,
        security_type: str | None,
        name: str | None,
    ) -> tuple[str, str]:
        text = " ".join(part.upper() for part in (security_group, security_type, name) if part)
        if "CASH" in text:
            return "cash", "cash"
        if "MUTUAL FUND" in text or "ETF" in text or "FUND" in text:
            return "fund", "security"
        return "equity", "security"


class SwanGlobalHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Swan Global HEGD holdings from the issuer's public ETF product page."""

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        resolved_source_url = self.resolve_source_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        route_resolution = "issuer_profile_metadata"
        if not resolved_source_url:
            resolved_source_url = await self._discover_source_url_from_product_page(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                identifiers=identifiers or {},
            )
            route_resolution = "issuer_product_page_linked_holdings_csv"
        if not resolved_source_url:
            raise ValueError(f"Swan Global product page did not expose holdings CSV for {symbol}.")

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                resolved_source_url,
                headers=self.source_request_headers(source_url=resolved_source_url),
                follow_redirects=True,
            )
        response.raise_for_status()
        rows, composition_date = AllianzHoldingsAdapter._parse_allianz_csv(
            response.text,
            symbol=normalized_symbol,
        )
        if not rows:
            raise ValueError(f"Swan Global holdings CSV did not expose rows for {symbol}.")

        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json=None,
            source_url=str(getattr(response, "url", resolved_source_url)),
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": route_resolution,
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    def source_request_headers(self, *, source_url: str) -> dict[str, str]:
        headers = _holdings_request_headers(accept="text/csv,*/*")
        headers["Referer"] = "https://etfs.swanglobalinvestments.com/hedged-equity-etf/"
        return headers


class RunningOakHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Running Oak Efficient Growth ETF holdings from its FilePoint-backed feed."""

    PRODUCT_IDS = {
        "ROEQ": "1363",
    }

    def resolve_source_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        if source_url:
            return source_url.strip()
        product_id = (
            issuer_product_id
            or _identifier(identifiers or {}, "running_oak_fund_id", "fund_id", "issuer_product_id")
            or self.PRODUCT_IDS.get(symbol.strip().upper())
        )
        if not product_id:
            return None
        return f"https://filepoint.live/runningoak_holdings_{product_id}_data.json"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        resolved_source_url = self.resolve_source_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        if not resolved_source_url:
            raise ValueError(f"Running Oak needs a FilePoint fund id for {symbol}.")

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                resolved_source_url,
                headers=self.source_request_headers(source_url=resolved_source_url),
                follow_redirects=True,
            )
        response.raise_for_status()
        payload = response.json()
        rows, composition_date = self._parse_running_oak_json(payload)
        if not rows:
            raise ValueError(f"Running Oak holdings feed did not expose rows for {symbol}.")

        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json={"source_format": "json", "payload": payload},
            source_url=str(getattr(response, "url", resolved_source_url)),
            source_identifier=issuer_product_id or self.PRODUCT_IDS.get(symbol.strip().upper()),
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "json",
                "route_resolution": "issuer_filepoint_holdings_json",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    def source_request_headers(self, *, source_url: str) -> dict[str, str]:
        headers = _holdings_request_headers(accept="application/json,*/*")
        headers["Referer"] = "https://www.runningoaketfs.com/full-holdings.html"
        return headers

    @classmethod
    def _parse_running_oak_json(
        cls,
        payload: Any,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        if not isinstance(payload, list):
            return [], None
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for index, item in enumerate(payload, start=1):
            if not isinstance(item, dict):
                continue
            if composition_date is None:
                composition_date = cls._parse_as_of_date(item.get("asOfDate"))
            raw_symbol = _clean(item.get("securityTicker"))
            symbol, exchange = cls._split_security_ticker(raw_symbol)
            name = _clean(
                item.get("securityDescriptionLong") or item.get("securityDescriptionShort")
            )
            cusip = _clean(item.get("securityIdentifier"))
            if not any([symbol, name, cusip, item.get("marketValuePercent")]):
                continue
            holding_type = cls._classify_holding(item)
            row_type = "cash" if holding_type == "cash" else "security"
            rows.append(
                CanonicalHoldingRow(
                    symbol=symbol if row_type != "cash" else None,
                    name=name,
                    cusip=cusip if _looks_like_cusip(cusip) else None,
                    weight=_decimal(item.get("marketValuePercent")),
                    shares=_decimal(item.get("shares")),
                    market_value=_decimal(item.get("marketValueBase")),
                    currency=_clean(item.get("tradingCurrency")),
                    country=_clean(item.get("country")),
                    exchange=exchange,
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=str(index),
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _parse_as_of_date(value: Any) -> date | None:
        text = _clean(value)
        if not text:
            return None
        try:
            return datetime.fromisoformat(text.replace("Z", "+00:00")).date()
        except ValueError:
            return None

    @staticmethod
    def _split_security_ticker(value: str | None) -> tuple[str | None, str | None]:
        text = _clean(value)
        if not text:
            return None, None
        parts = text.split()
        if len(parts) == 2 and re.fullmatch(r"[A-Z][A-Z0-9.=-]{0,9}", parts[0].upper()):
            return parts[0].upper(), parts[1].upper()
        if re.fullmatch(r"[A-Z][A-Z0-9.=-]{0,9}", text.upper()):
            return text.upper(), None
        return None, None

    @staticmethod
    def _classify_holding(item: dict[str, Any]) -> str:
        segment = (_clean(item.get("segment")) or "").lower()
        ticker = (_clean(item.get("securityTicker")) or "").upper()
        name = (_clean(item.get("securityDescriptionLong")) or "").lower()
        if "cash" in segment or ticker in {"CASH", "USD", "RECPAY"} or name in {"cash"}:
            return "cash"
        if "option" in segment or re.search(r"\b\d{6}[CP]\d{8}\b", ticker):
            return "option"
        return "equity"


class HennessyHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Parse Hennessy ETF holdings from issuer-rendered product-page tables."""

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        resolved_source_url = self.resolve_product_page_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers or {},
        ) or self.resolve_source_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        if not resolved_source_url:
            raise ValueError(f"Hennessy needs an ETF product page for {symbol}.")

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                resolved_source_url,
                headers=self.source_request_headers(source_url=resolved_source_url),
                follow_redirects=True,
            )
        response.raise_for_status()
        rows = self._parse_hennessy_product_page(response.text)
        if not rows:
            raise ValueError(f"Hennessy product page did not expose holdings rows for {symbol}.")

        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json=None,
            source_url=str(getattr(response, "url", resolved_source_url)),
            source_identifier=issuer_product_id or symbol.strip().upper(),
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "html",
                "route_resolution": "issuer_product_page_holdings_table",
                "terms_note": self.config.terms_note,
            },
        )

    def source_request_headers(self, *, source_url: str) -> dict[str, str]:
        return _holdings_request_headers(accept="text/html,*/*")

    @classmethod
    def _parse_hennessy_product_page(cls, raw_html: str) -> list[CanonicalHoldingRow]:
        tables = re.findall(r"<table\b[^>]*>.*?</table>", raw_html, flags=re.IGNORECASE | re.DOTALL)
        best_rows: list[CanonicalHoldingRow] = []
        for table in tables:
            matrix = cls._html_table_to_matrix(table)
            if not matrix:
                continue
            header = [_clean(cell) or "" for cell in matrix[0]]
            normalized_header = {cell.lower() for cell in header}
            if not {
                "name",
                "ticker",
                "cusip",
                "shares",
                "market value",
                "% of net assets",
            }.issubset(normalized_header):
                continue
            rows: list[CanonicalHoldingRow] = []
            for position, values in enumerate(matrix[1:], start=1):
                raw = _row_dict(header, values)
                name = _clean(_first(raw, ["name"]))
                ticker = cls._clean_symbol(_first(raw, ["ticker"]))
                cusip = _clean(_first(raw, ["cusip"]))
                if not any([name, ticker, cusip]):
                    continue
                rows.append(
                    CanonicalHoldingRow(
                        symbol=ticker,
                        name=name,
                        cusip=cusip if _looks_like_cusip(cusip) else None,
                        weight=_decimal(_first(raw, ["% of net assets"])),
                        shares=_decimal(_first(raw, ["shares"])),
                        market_value=_decimal(_first(raw, ["market value"])),
                        currency="USD",
                        holding_type="equity",
                        row_type="security",
                        source_row_id=str(position),
                        extra_data={
                            key: value for key, value in raw.items() if value not in (None, "")
                        },
                    )
                )
            if rows:
                best_rows = max(best_rows, rows, key=len)
        return best_rows

    @staticmethod
    def _html_table_to_matrix(table_html: str) -> list[list[str]]:
        matrix: list[list[str]] = []
        for row_html in re.findall(
            r"<tr\b[^>]*>(.*?)</tr>",
            table_html,
            flags=re.IGNORECASE | re.DOTALL,
        ):
            cells = [
                _clean(html.unescape(re.sub(r"<[^>]+>", " ", cell))) or ""
                for cell in re.findall(
                    r"<t[dh]\b[^>]*>(.*?)</t[dh]>",
                    row_html,
                    flags=re.IGNORECASE | re.DOTALL,
                )
            ]
            if any(cells):
                matrix.append(cells)
        return matrix

    @staticmethod
    def _clean_symbol(value: Any) -> str | None:
        text = _clean(value)
        if not text:
            return None
        normalized = text.strip().upper()
        if re.fullmatch(r"[A-Z][A-Z0-9.=-]{0,9}", normalized):
            return normalized
        return None


class GoogleSheetsHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Shared parser for issuers that explicitly publish Google Sheets holdings CSVs."""

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        return await self._fetch_google_sheets_holdings_csv(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )

    async def _fetch_google_sheets_holdings_csv(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        """Fetch a CSV declared by an issuer's own product page.

        Providers retain their own ``fetch_latest`` methods and product-page
        allowlists.  This method is deliberately limited to the stable Google
        Sheets CSV transport and row layout shared by those publisher pages.
        """
        normalized_symbol = symbol.strip().upper()
        resolved_source_url = self.resolve_source_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        route_resolution = "issuer_profile_metadata"
        if not resolved_source_url:
            resolved_source_url = await self._discover_source_url_from_product_page(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                identifiers=identifiers or {},
            )
            route_resolution = "issuer_product_page_google_holdings_csv"
        if not resolved_source_url:
            raise ValueError(
                f"{self.source_provider} product page did not expose a holdings CSV for {symbol}."
            )

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                resolved_source_url,
                headers=self.source_request_headers(source_url=resolved_source_url),
                follow_redirects=True,
            )
        response.raise_for_status()
        rows, composition_date = self._parse_tapp_csv(response.text, symbol=normalized_symbol)
        if not rows:
            raise ValueError(
                f"{self.source_provider} holdings CSV did not expose rows for {symbol}."
            )

        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json=None,
            source_url=str(getattr(response, "url", resolved_source_url)),
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": route_resolution,
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    def source_request_headers(self, *, source_url: str) -> dict[str, str]:
        return {
            **_holdings_request_headers(accept="text/csv,*/*"),
            "Referer": "https://www.tappalphafunds.com/",
        }

    async def _discover_source_url_from_product_page(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None,
        identifiers: dict[str, str],
    ) -> str | None:
        product_page_url = self.resolve_product_page_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers,
        )
        if not product_page_url:
            return None
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                product_page_url,
                headers=_holdings_request_headers(accept="text/html,*/*"),
                follow_redirects=True,
            )
        response.raise_for_status()
        return self._discover_google_csv_export(response.text, base_url=str(response.url))

    @staticmethod
    def _discover_google_csv_export(raw_html: str, *, base_url: str) -> str | None:
        for match in re.finditer(
            r"<a\b(?P<attrs>[^>]*)>(?P<body>.*?)</a>",
            raw_html,
            re.IGNORECASE | re.DOTALL,
        ):
            body_text = " ".join(re.sub(r"<[^>]+>", " ", match.group("body")).split())
            attrs = match.group("attrs")
            href_match = re.search(r'href=["\']([^"\']+)["\']', attrs, re.IGNORECASE)
            if href_match is None:
                continue
            href = html.unescape(href_match.group(1))
            haystack = f"{body_text} {href}".lower()
            if "holdings" not in haystack or "docs.google.com/spreadsheets/export" not in href:
                continue
            parsed = urlparse(urljoin(base_url, href))
            if parsed.netloc.endswith("docs.google.com") and "/spreadsheets/export" in parsed.path:
                return urlunparse(parsed)
        return None

    @classmethod
    def _parse_tapp_csv(
        cls,
        raw_csv: str,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        table_rows = [
            row
            for row in csv.reader(StringIO(raw_csv.strip()))
            if any(_clean(cell) for cell in row)
        ]
        if not table_rows:
            return [], None
        header_index = next(
            (
                index
                for index, row in enumerate(table_rows[:20])
                if {"date", "account", "stock ticker", "security name"}.issubset(
                    {(_clean(cell) or "").lower() for cell in row}
                )
            ),
            None,
        )
        if header_index is None:
            return [], None
        header = table_rows[header_index]
        requested_symbol = symbol.strip().upper()
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for position, row in enumerate(table_rows[header_index + 1 :], start=1):
            raw = _row_dict(header, row)
            account = (_clean(_first(raw, ["account"])) or "").upper()
            if account and account != requested_symbol:
                continue
            row_date = cls._parse_tapp_date(_first(raw, ["date"]))
            if composition_date is None:
                composition_date = row_date
            raw_symbol = _clean(_first(raw, ["stock ticker", "stockticker", "ticker"]))
            name = _clean(_first(raw, ["security name", "securityname", "name"]))
            row_type, holding_type = cls._classify_holding(symbol=raw_symbol, name=name)
            cleaned_symbol = (
                cls._clean_symbol(raw_symbol) if holding_type not in {"cash", "swap"} else None
            )
            rows.append(
                CanonicalHoldingRow(
                    symbol=cleaned_symbol,
                    name=name,
                    cusip=(
                        _clean(_first(raw, ["cusip"]))
                        if _looks_like_cusip(_clean(_first(raw, ["cusip"])))
                        else None
                    ),
                    weight=_decimal(_first(raw, ["weightings", "weight", "% of net assets"])),
                    shares=_decimal(_first(raw, ["shares"])),
                    market_value=_decimal(_first(raw, ["market value", "marketvalue"])),
                    currency="USD",
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=str(position),
                    extra_data={
                        key: value for key, value in raw.items() if value not in (None, "")
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _parse_tapp_date(value: Any) -> date | None:
        text = _clean(value)
        if not text:
            return None
        for pattern in ("%m/%d/%Y", "%Y-%m-%d"):
            try:
                return datetime.strptime(text, pattern).date()
            except ValueError:
                continue
        return None

    @staticmethod
    def _clean_symbol(value: Any) -> str | None:
        text = _clean(value)
        if not text:
            return None
        normalized = text.strip().upper()
        if re.fullmatch(r"[A-Z][A-Z0-9.=-]{0,9}", normalized):
            return normalized
        return None

    @staticmethod
    def _classify_holding(*, symbol: str | None, name: str | None) -> tuple[str, str]:
        text = " ".join(part.upper() for part in (symbol, name) if part)
        if "CASH&OTHER" in text or "CASH & OTHER" in text or text == "CASH":
            return "cash", "cash"
        if "-TRS-" in text or " SWAP " in f" {text} ":
            return "security", "swap"
        if "FUND" in text:
            return "security", "fund"
        return "security", "equity"


class TappAlphaHoldingsAdapter(GoogleSheetsHoldingsAdapter):
    """Fetch TappAlpha holdings from the public API used by its ETF product pages."""

    public_api_url = "https://jdkfnvgkfwotjlyovbrk.supabase.co/functions/v1/fund-public-api"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del source_url, identifiers
        normalized_symbol = symbol.strip().upper()
        if not normalized_symbol:
            raise ValueError("TappAlpha holdings require an ETF symbol.")

        resolved_source_url = (
            f"{self.public_api_url}?{urlencode({'ticker': normalized_symbol, 'view': 'all'})}"
        )
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                resolved_source_url,
                headers={
                    **_holdings_request_headers(accept="application/json,*/*"),
                    "Origin": "https://www.tappalphafunds.com",
                    "Referer": f"https://www.tappalphafunds.com/etfs/{normalized_symbol.lower()}",
                },
                follow_redirects=True,
            )
        response.raise_for_status()
        payload = response.json()
        rows, composition_date = self._parse_public_api_payload(payload, symbol=normalized_symbol)
        if not rows:
            raise ValueError(
                f"TappAlpha public fund API returned no holdings rows for {normalized_symbol}."
            )

        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json=payload,
            source_url=str(response.url),
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "json",
                "route_resolution": "issuer_public_product_page_fund_api",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @classmethod
    def _parse_public_api_payload(
        cls,
        payload: Any,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        holdings = payload.get("holdings") if isinstance(payload, dict) else None
        if not isinstance(holdings, list):
            return [], None

        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for position, raw in enumerate(holdings, start=1):
            if not isinstance(raw, dict):
                continue
            row_date = cls._parse_tapp_date(raw.get("as_of_date"))
            if row_date and (composition_date is None or row_date > composition_date):
                composition_date = row_date
            raw_symbol = _clean(raw.get("security_ticker"))
            name = _clean(raw.get("security_name"))
            security_id = _clean(raw.get("security_id"))
            row_type, holding_type = cls._classify_holding(symbol=raw_symbol, name=name)
            clean_symbol = (
                cls._clean_symbol(raw_symbol) if holding_type not in {"cash", "swap"} else None
            )
            rows.append(
                CanonicalHoldingRow(
                    symbol=clean_symbol,
                    name=name,
                    cusip=security_id if _looks_like_cusip(security_id) else None,
                    isin=security_id
                    if security_id and re.fullmatch(r"[A-Z]{2}[A-Z0-9]{9}[0-9]", security_id)
                    else None,
                    weight=_decimal(raw.get("weight")),
                    shares=_decimal(raw.get("quantity")),
                    market_value=_decimal(raw.get("market_value")),
                    currency=_clean(raw.get("currency")),
                    country=_clean(raw.get("country")),
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=f"{symbol}:{position}:{security_id or raw_symbol or name or 'holding'}",
                    extra_data={
                        key: value for key, value in raw.items() if value not in (None, "")
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _classify_holding(*, symbol: str | None, name: str | None) -> tuple[str, str]:
        text = " ".join(part.upper() for part in (symbol, name) if part)
        if "-TRS-" in text or " SWAP " in f" {text} ":
            return "security", "swap"
        if "CASH" in text or "GOVERNMENT OBLIGATIONS FUND" in text:
            return "cash", "cash"
        return "security", "equity"


class TuttleHoldingsAdapter(GoogleSheetsHoldingsAdapter):
    """Fetch Tuttle-managed ETF holdings from public product-page Google CSV exports."""

    PUBLIC_API_URL = "https://jdkfnvgkfwotjlyovbrk.supabase.co/functions/v1/fund-public-api"
    # DRMP's current IncomeBlast product page is backed by the public fund API.
    # Keep the older Google-Sheets route for products that still publish it.
    PUBLIC_API_SYMBOLS = frozenset({"DRMP"})

    PRODUCT_PAGE_URLS: dict[str, str] = {
        "BITK": "https://www.incomeblastetfs.com/etf/bitk",
        "DRMP": "https://www.incomeblastetfs.com/etf/drmp",
        "MAGO": "https://www.incomeblastetfs.com/etf/mago",
        "MEMY": "https://www.incomeblastetfs.com/etf/memy",
        "SPCI": "https://www.incomeblastetfs.com/etf/spci",
    }

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol in self.PUBLIC_API_SYMBOLS:
            return await self._fetch_public_api_holdings(
                symbol=normalized_symbol,
                issuer_product_id=issuer_product_id,
            )
        return await self._fetch_google_sheets_holdings_csv(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )

    def resolve_product_page_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        explicit = super().resolve_product_page_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            identifiers=identifiers,
        )
        if explicit:
            return explicit
        normalized_symbol = symbol.strip().upper()
        return self.PRODUCT_PAGE_URLS.get(
            normalized_symbol,
            f"https://www.incomeblastetfs.com/etf/{normalized_symbol.lower()}",
        )

    async def _fetch_public_api_holdings(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None,
    ) -> HoldingsFetchResult:
        resolved_source_url = (
            f"{self.PUBLIC_API_URL}?{urlencode({'ticker': symbol, 'view': 'all'})}"
        )
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                resolved_source_url,
                headers={
                    **_holdings_request_headers(accept="application/json,*/*"),
                    "Origin": "https://www.incomeblastetfs.com",
                    "Referer": f"https://www.incomeblastetfs.com/etf/{symbol.lower()}",
                },
                follow_redirects=True,
            )
        response.raise_for_status()
        payload = response.json()
        rows, composition_date = self._parse_public_api_payload(payload, symbol=symbol)
        if not rows:
            raise ValueError(f"Tuttle public fund API returned no holdings rows for {symbol}.")
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json=payload,
            source_url=str(response.url),
            source_identifier=issuer_product_id or symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "json",
                "route_resolution": "issuer_public_product_page_fund_api",
                "snapshot_provenance": "tuttle_native_current_holdings_api",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @classmethod
    def _parse_public_api_payload(
        cls,
        payload: Any,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        holdings = payload.get("holdings") if isinstance(payload, dict) else None
        if not isinstance(holdings, list):
            return [], None
        rows: list[CanonicalHoldingRow] = []
        composition_date: date | None = None
        for position, raw in enumerate(holdings, start=1):
            if not isinstance(raw, dict):
                continue
            row_date = _parse_issuer_date(raw.get("as_of_date"))
            if row_date and (composition_date is None or row_date > composition_date):
                composition_date = row_date
            raw_symbol = _clean(raw.get("security_ticker"))
            name = _clean(raw.get("security_name"))
            security_id = _clean(raw.get("security_id"))
            row_type, holding_type = cls._classify_holding(symbol=raw_symbol, name=name)
            clean_symbol = (
                raw_symbol.upper()
                if holding_type not in {"cash", "fixed_income", "option", "swap"}
                and raw_symbol
                and re.fullmatch(r"[A-Z][A-Z0-9.-]{0,11}", raw_symbol.upper())
                else None
            )
            weight = _decimal(raw.get("weight"))
            # IncomeBlast returns percentage points (for example 105.95),
            # whereas canonical CSV weights are fractions of NAV.
            if weight is not None and abs(weight) > Decimal("1"):
                weight /= Decimal("100")
            rows.append(
                CanonicalHoldingRow(
                    symbol=clean_symbol,
                    name=name,
                    cusip=security_id if _looks_like_cusip(security_id) else None,
                    isin=security_id
                    if security_id and re.fullmatch(r"[A-Z]{2}[A-Z0-9]{9}[0-9]", security_id)
                    else None,
                    weight=weight,
                    shares=_decimal(raw.get("quantity")),
                    market_value=_decimal(raw.get("market_value")),
                    currency=_clean(raw.get("currency")),
                    country=_clean(raw.get("country")),
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=f"{symbol}:{position}:{security_id or raw_symbol or name or 'holding'}",
                    extra_data={
                        key: value for key, value in raw.items() if value not in (None, "")
                    },
                )
            )
        return rows, composition_date

    def source_request_headers(self, *, source_url: str) -> dict[str, str]:
        return {
            **_holdings_request_headers(accept="text/csv,*/*"),
            "Referer": "https://www.incomeblastetfs.com/",
        }

    @staticmethod
    def _classify_holding(*, symbol: str | None, name: str | None) -> tuple[str, str]:
        text = " ".join(part.upper() for part in (symbol, name) if part)
        if "CASH&OTHER" in text or "CASH & OTHER" in text or text == "CASH":
            return "cash", "cash"
        if "TREASURY BILL" in text or re.fullmatch(
            r"91279[A-Z0-9]{4}", (symbol or "").strip().upper()
        ):
            return "security", "fixed_income"
        if re.search(r"\b\d{6}[CP]\d{8}\b", text) or re.search(r"\b[CP]\s*$", text):
            return "security", "option"
        if "-TRS-" in text or " SWAP " in f" {text} ":
            return "security", "swap"
        if "FUND" in text:
            return "security", "fund"
        return "security", "equity"


