class BaronHoldingsAdapter(IssuerCsvHoldingsAdapter):
    product_index_url = "https://www.baroncapitalgroup.com/"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        page_or_csv_url = source_url or self.product_index_url
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            if self._is_csv_url(page_or_csv_url):
                holdings_url = page_or_csv_url
            else:
                page_url, page_text = await self._fetch_product_page(
                    client,
                    page_or_csv_url,
                )
                holdings_url = self._discover_holdings_url(
                    page_text,
                    symbol=normalized_symbol,
                    base_url=page_url,
                )
            if not holdings_url:
                raise ValueError(f"Baron product pages did not expose holdings CSV for {symbol}.")
            holdings_url, response_text = await self._fetch_holdings_csv(client, holdings_url)
        rows = self._parse_baron_csv(response_text)
        if not rows:
            raise ValueError(f"Baron holdings CSV did not expose rows for {symbol}.")
        composition_date = self._composition_date_from_url(holdings_url)
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response_text,
            raw_json=None,
            source_url=holdings_url,
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "issuer_product_page_linked_holdings_csv",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    def source_request_headers(self, *, source_url: str) -> dict[str, str]:
        headers = _holdings_request_headers(accept="text/csv,*/*")
        headers["Referer"] = self.product_index_url
        return headers

    async def _fetch_product_page(
        self,
        client: httpx.AsyncClient,
        source_url: str,
    ) -> tuple[str, str]:
        headers = _issuer_page_request_headers(accept="text/html,*/*")
        try:
            response = await client.get(
                source_url,
                headers=headers,
                follow_redirects=True,
            )
            response.raise_for_status()
            return source_url, response.text
        except httpx.HTTPStatusError as exc:
            if exc.response.status_code != 403:
                raise

        response = await self._requests_get_with_timeout_retry(source_url, headers=headers)
        if response.status_code == 404:
            recovered = await self._recover_stale_dated_csv_with_requests(
                source_url,
                headers=headers,
            )
            if recovered is not None:
                return recovered
        response.raise_for_status()
        return source_url, response.text

    async def _fetch_holdings_csv(
        self,
        client: httpx.AsyncClient,
        source_url: str,
    ) -> tuple[str, str]:
        headers = self.source_request_headers(source_url=source_url)
        try:
            response = await client.get(
                source_url,
                headers=headers,
                follow_redirects=True,
            )
            response.raise_for_status()
            return source_url, response.text
        except httpx.HTTPStatusError as exc:
            if exc.response.status_code == 404:
                recovered = await self._recover_stale_dated_csv(client, source_url, headers=headers)
                if recovered is not None:
                    return recovered
            if exc.response.status_code != 403:
                raise

        response = await self._requests_get_with_timeout_retry(source_url, headers=headers)
        if response.status_code == 404:
            recovered = await self._recover_stale_dated_csv_with_requests(
                source_url,
                headers=headers,
            )
            if recovered is not None:
                return recovered
        response.raise_for_status()
        return source_url, response.text

    @staticmethod
    async def _requests_get_with_timeout_retry(
        source_url: str,
        *,
        headers: dict[str, str],
    ) -> requests.Response:
        for attempt in range(3):
            try:
                return await asyncio.to_thread(
                    requests.get,
                    source_url,
                    headers=headers,
                    allow_redirects=True,
                    timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS,
                )
            except requests.exceptions.Timeout:
                if attempt == 2:
                    raise
                await asyncio.sleep(0.25 * (attempt + 1))
        raise AssertionError("unreachable")

    @staticmethod
    async def _recover_stale_dated_csv(
        client: httpx.AsyncClient,
        source_url: str,
        *,
        headers: dict[str, str],
    ) -> tuple[str, str] | None:
        """Recover only a stale issuer-declared Baron daily filename within one week."""
        match = re.search(r"(?P<prefix>-HOLDINGS-)(?P<day>\d{8})(?P<suffix>-0\.csv)$", source_url)
        if match is None:
            return None
        try:
            declared_day = datetime.strptime(match.group("day"), "%Y%m%d").date()
        except ValueError:
            return None
        for offset in range(1, 8):
            candidate_day = (declared_day + timedelta(days=offset)).strftime("%Y%m%d")
            candidate_url = (
                f"{source_url[:match.start('day')]}{candidate_day}{source_url[match.end('day') :]}"
            )
            response = await client.get(candidate_url, headers=headers, follow_redirects=True)
            if response.status_code == 404:
                continue
            response.raise_for_status()
            return candidate_url, response.text
        return None

    @staticmethod
    async def _recover_stale_dated_csv_with_requests(
        source_url: str,
        *,
        headers: dict[str, str],
    ) -> tuple[str, str] | None:
        match = re.search(r"(?P<prefix>-HOLDINGS-)(?P<day>\d{8})(?P<suffix>-0\.csv)$", source_url)
        if match is None:
            return None
        try:
            declared_day = datetime.strptime(match.group("day"), "%Y%m%d").date()
        except ValueError:
            return None
        for offset in range(1, 8):
            candidate_day = (declared_day + timedelta(days=offset)).strftime("%Y%m%d")
            candidate_url = (
                f"{source_url[:match.start('day')]}{candidate_day}{source_url[match.end('day') :]}"
            )
            response = await asyncio.to_thread(
                requests.get,
                candidate_url,
                headers=headers,
                allow_redirects=True,
                timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS,
            )
            if response.status_code == 404:
                continue
            response.raise_for_status()
            return candidate_url, response.text
        return None

    @staticmethod
    def _is_csv_url(value: str) -> bool:
        return value.split("?", 1)[0].lower().endswith(".csv")

    @staticmethod
    def _discover_holdings_url(raw_html: str, *, symbol: str, base_url: str) -> str | None:
        candidates: list[tuple[date, str]] = []
        for pattern in (
            re.compile(
                rf"""(?P<url>https?://[^\s"'<>)]*{re.escape(symbol)}-HOLDINGS-(?P<date>\d{{8}})-0\.csv)""",
                re.IGNORECASE,
            ),
            re.compile(
                rf"""(?P<url>[^\s"'<>)]*{re.escape(symbol)}-HOLDINGS-(?P<date>\d{{8}})-0\.csv)""",
                re.IGNORECASE,
            ),
        ):
            for match in pattern.finditer(raw_html):
                parsed_date = BaronHoldingsAdapter._parse_compact_yyyymmdd(match.group("date"))
                if parsed_date is None:
                    continue
                candidates.append((parsed_date, urljoin(base_url, match.group("url"))))
            if candidates:
                break
        if not candidates:
            return None
        candidates.sort(key=lambda item: item[0], reverse=True)
        return candidates[0][1]

    @staticmethod
    def _composition_date_from_url(source_url: str) -> date | None:
        match = re.search(r"-HOLDINGS-(\d{8})-0\.csv", source_url, flags=re.IGNORECASE)
        if not match:
            return None
        return BaronHoldingsAdapter._parse_compact_yyyymmdd(match.group(1))

    @staticmethod
    def _parse_compact_yyyymmdd(value: str) -> date | None:
        try:
            return datetime.strptime(value, "%Y%m%d").date()
        except ValueError:
            return None

    @staticmethod
    def _parse_baron_csv(raw_csv: str) -> list[CanonicalHoldingRow]:
        reader = csv.DictReader(StringIO(raw_csv.strip()))
        rows: list[CanonicalHoldingRow] = []
        for index, item in enumerate(reader, start=1):
            symbol = _clean(item.get("Ticker"))
            name = _clean(item.get("Holding"))
            if not symbol and not name:
                continue
            cash_like = (symbol or "").strip().upper() in {
                "CASH",
                "USD",
                "US DOLLAR",
            } or "CASH" in (name or "").strip().upper()
            rows.append(
                CanonicalHoldingRow(
                    symbol=None if cash_like else symbol,
                    name=name,
                    cusip=_clean(item.get("CUSIP")),
                    isin=_clean(item.get("ISIN")),
                    sedol=_clean(item.get("SEDOL")),
                    weight=_decimal(item.get("Weight (%)")),
                    shares=_decimal(item.get("Quantity")),
                    market_value=_decimal(item.get("Market Value ($)")),
                    currency=_clean(item.get("Currency Code")),
                    holding_type="cash" if cash_like else "equity",
                    row_type="cash" if cash_like else "security",
                    source_row_id=str(index),
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        return rows


class BrandesHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Parse Brandes ETF holdings from the public iframe data CSV."""

    holdings_url = "https://etfs.brandes.com/assets/data/6c11_Report.csv"
    product_page_template = "https://www.brandes.com/etfs/fund-detail/{slug}"
    fund_slugs = {
        "BINV": "brandes-international-etf",
        "BSMC": "brandes-us-small-mid-cap-value-etf",
        "BUSA": "brandes-us-value-etf",
    }

    def resolve_source_url(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> str | None:
        explicit = super().resolve_source_url(
            symbol=symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        return explicit or self.holdings_url

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        resolved_url = self.resolve_source_url(
            symbol=normalized_symbol,
            issuer_product_id=issuer_product_id,
            source_url=source_url,
            identifiers=identifiers,
        )
        if not resolved_url:
            raise ValueError(f"Brandes did not expose a holdings CSV route for {symbol}.")
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                resolved_url,
                headers=self.source_request_headers(source_url=resolved_url),
                follow_redirects=True,
            )
        response.raise_for_status()
        rows, composition_date = self._parse_brandes_csv(
            response.text,
            symbol=normalized_symbol,
        )
        if not rows:
            raise ValueError(f"Brandes holdings CSV did not expose rows for {symbol}.")
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json=None,
            source_url=resolved_url,
            source_identifier=issuer_product_id or normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "csv",
                "route_resolution": "issuer_iframe_public_holdings_csv",
                "product_page_url": self._product_page_url(normalized_symbol),
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    def source_request_headers(self, *, source_url: str) -> dict[str, str]:
        headers = _holdings_request_headers(accept="text/csv,*/*")
        headers["Referer"] = "https://etfs.brandes.com/busa"
        return headers

    @classmethod
    def _product_page_url(cls, symbol: str) -> str | None:
        slug = cls.fund_slugs.get(symbol)
        if not slug:
            return None
        return cls.product_page_template.format(slug=slug)

    @classmethod
    def _parse_brandes_csv(
        cls,
        raw_csv: str,
        *,
        symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        reader = csv.DictReader(StringIO(raw_csv.strip()))
        rows: list[CanonicalHoldingRow] = []
        composition_dates: list[date] = []
        expected_basket_ticker = f"{symbol}.P"
        for index, item in enumerate(reader, start=1):
            basket_ticker = (_clean(item.get("Basket Ticker")) or "").upper()
            if basket_ticker != expected_basket_ticker:
                continue
            parsed_date = cls._parse_iso_date(item.get("Basket Evaluation Date"))
            if parsed_date:
                composition_dates.append(parsed_date)
            asset_group = _clean(item.get("Fund Accounting Asset Group Code"))
            symbol_value = _clean(item.get("Ticker"))
            name = _clean(item.get("Security Description"))
            holding_type = cls._holding_type(
                asset_group=asset_group, name=name, symbol=symbol_value
            )
            row_type = "cash" if holding_type == "cash" else "security"
            if row_type == "cash":
                symbol_value = None
            rows.append(
                CanonicalHoldingRow(
                    symbol=symbol_value,
                    name=name,
                    cusip=_clean(item.get("CUSIP")),
                    isin=_clean(item.get("ISIN")),
                    sedol=_clean(item.get("SEDOL")),
                    weight=_decimal(item.get("Calculated Weight - Base")),
                    shares=_decimal(item.get("Benchmark Quantity")),
                    market_value=_decimal(item.get("Benchmark Market Value (Base)")),
                    currency=_clean(item.get("ETF Base Currency")),
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=str(index),
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        composition_date = max(composition_dates) if composition_dates else None
        return rows, composition_date

    @staticmethod
    def _parse_iso_date(value: Any) -> date | None:
        text = _clean(value)
        if not text:
            return None
        try:
            return datetime.strptime(text, "%Y-%m-%d").date()
        except ValueError:
            return None

    @staticmethod
    def _holding_type(
        *,
        asset_group: str | None,
        name: str | None,
        symbol: str | None,
    ) -> str:
        text = f"{asset_group or ''} {name or ''} {symbol or ''}".upper()
        if any(token in text for token in ["CASH", "CURRENCY", "RECEIVABLE", "PAYABLE"]):
            return "cash"
        if "BOND" in text or "FIXED" in text:
            return "fixed_income"
        if "FUTURE" in text:
            return "future"
        if "OPTION" in text:
            return "option"
        if "FOREIGN STOCK" in text or "EQUITY" in text or "STOCK" in text:
            return "equity"
        return "security"


class AppliedFinanceHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Parse Applied Finance ETF holdings from its public ETFData pages."""

    product_page_template = "https://appliedfinancefunds.com/ETF/ETFData/{symbol_upper}"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del issuer_product_id, identifiers
        normalized_symbol = symbol.strip().upper()
        product_page_url = source_url or self.product_page_template.format(
            symbol_upper=normalized_symbol
        )

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.get(
                product_page_url,
                headers=_issuer_page_request_headers(),
                follow_redirects=True,
            )
        response.raise_for_status()

        table_parser = _HTMLTableByIdParser(table_id="etf_constituents")
        table_parser.feed(response.text)
        rows = self._parse_applied_finance_rows(table_parser.rows)
        if not rows:
            raise ValueError(
                f"Applied Finance product page did not expose holdings rows for {symbol}."
            )
        composition_date = self._composition_date_from_table(table_parser.rows)
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            source_url=product_page_url,
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "html",
                "route_resolution": "issuer_public_product_page_holdings_table",
                "product_page_url": product_page_url,
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @classmethod
    def _parse_applied_finance_rows(
        cls,
        table_rows: list[list[Any]],
    ) -> list[CanonicalHoldingRow]:
        rows = parse_holdings_table(table_rows)
        for row in rows:
            row.currency = row.currency or "USD"
            row.holding_type = cls._holding_type(
                symbol=row.symbol,
                name=row.name,
                market_value=row.market_value,
            )
            row.row_type = "cash" if row.holding_type == "cash" else "security"
            if row.row_type == "cash":
                row.symbol = None
        return rows

    @staticmethod
    def _composition_date_from_table(table_rows: list[list[Any]]) -> date | None:
        rows_by_index = [
            ["" if value is None else value for value in row]
            for row in table_rows
            if any(_clean(value) for value in row)
        ]
        header_index = next(
            (
                index
                for index, row in enumerate(rows_by_index[:30])
                if "as of date" in {str(value).strip().lower() for value in row}
            ),
            None,
        )
        if header_index is None:
            return None
        header = rows_by_index[header_index]
        dates: list[date] = []
        for raw_row in rows_by_index[header_index + 1 :]:
            raw = _row_dict(header, raw_row)
            parsed = AppliedFinanceHoldingsAdapter._parse_date(raw.get("As Of Date"))
            if parsed:
                dates.append(parsed)
        return max(dates) if dates else None

    @staticmethod
    def _parse_date(value: Any) -> date | None:
        text = _clean(value)
        if text is None:
            return None
        for fmt in ("%m/%d/%Y", "%Y-%m-%d"):
            try:
                return datetime.strptime(text, fmt).date()
            except ValueError:
                continue
        return None

    @staticmethod
    def _holding_type(
        *,
        symbol: str | None,
        name: str | None,
        market_value: Decimal | None,
    ) -> str:
        text = f"{symbol or ''} {name or ''}".upper()
        if any(token in text for token in ["CASH", "CURRENCY", "RECEIVABLE", "PAYABLE"]):
            return "cash"
        if market_value == Decimal("0") and not _clean(symbol):
            return "cash"
        return "equity"


class OceanParkHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Parse Ocean Park ETF holdings from its public FilePoint-backed JSON endpoint."""

    holdings_endpoint = "https://filepoint.live/oceanpark_getholdings_cached4.php"
    product_pages = {
        "DUKQ": "https://oceanparketfs.com/domestic-etf",
        "DUKX": "https://oceanparketfs.com/international-etf",
        "DUKZ": "https://oceanparketfs.com/diversified-income-etf.html",
        "DUKH": "https://oceanparketfs.com/high-income-etf.html",
    }
    fund_ids = {
        "DUKQ": "1356",
        "DUKX": "1357",
        "DUKZ": "1358",
        "DUKH": "1359",
    }

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        fund_id = (
            _clean(issuer_product_id)
            or _identifier(identifiers or {}, "issuer_product_id", "ocean_park_fund_id")
            or self.fund_ids.get(normalized_symbol)
        )
        if not fund_id:
            raise ValueError(f"Ocean Park did not expose a fund id for {symbol}.")

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await client.post(
                self.holdings_endpoint,
                data={"fundID": fund_id},
                headers=self.source_request_headers(symbol=normalized_symbol),
                follow_redirects=True,
            )
        response.raise_for_status()
        payload = response.json()
        rows, composition_date = self._parse_ocean_park_rows(payload)
        if not rows:
            raise ValueError(f"Ocean Park holdings endpoint did not expose rows for {symbol}.")
        product_page_url = self.product_pages.get(normalized_symbol)
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json={"rows": payload} if isinstance(payload, list) else None,
            source_url=self.holdings_endpoint,
            source_identifier=fund_id,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "json",
                "route_resolution": "issuer_public_filepoint_holdings_json",
                "fund_id": fund_id,
                "product_page_url": product_page_url,
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    def source_request_headers(self, *, symbol: str) -> dict[str, str]:
        referer = self.product_pages.get(symbol, "https://oceanparketfs.com/")
        headers = _issuer_page_request_headers(
            accept="application/json, text/javascript, */*; q=0.01"
        )
        headers.update(
            {
                "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
                "Origin": "https://oceanparketfs.com",
                "Referer": referer,
                "X-Requested-With": "XMLHttpRequest",
            }
        )
        return headers

    @classmethod
    def _parse_ocean_park_rows(
        cls,
        payload: Any,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        if not isinstance(payload, list):
            return [], None
        rows: list[CanonicalHoldingRow] = []
        composition_dates: list[date] = []
        for index, item in enumerate(payload, start=1):
            if not isinstance(item, dict):
                continue
            composition_date = cls._parse_date(item.get("asOfDate"))
            if composition_date:
                composition_dates.append(composition_date)
            raw_symbol = _clean(item.get("securityTicker"))
            symbol = cls._clean_symbol(raw_symbol)
            name = _clean(
                item.get("securityDescriptionLong") or item.get("securityDescriptionShort")
            )
            row_type, holding_type = cls._classify_row(
                symbol=symbol,
                name=name,
                segment=_clean(item.get("segment")),
                category=_clean(item.get("category")),
            )
            identifier = _clean(item.get("securityIdentifier"))
            rows.append(
                CanonicalHoldingRow(
                    symbol=symbol if row_type == "security" else None,
                    name=name,
                    cusip=identifier if _looks_like_cusip(identifier) else None,
                    weight=_decimal(item.get("marketValuePercent")),
                    shares=_decimal(item.get("shares")),
                    market_value=_decimal(item.get("marketValueBase")),
                    currency=_clean(item.get("tradingCurrency") or item.get("incomeCurrency")),
                    country=_clean(item.get("country")),
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=str(index),
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        composition_date = max(composition_dates) if composition_dates else None
        return rows, composition_date

    @staticmethod
    def _clean_symbol(value: str | None) -> str | None:
        text = _clean(value)
        if text is None:
            return None
        return text.split()[0].strip().upper() or None

    @staticmethod
    def _parse_date(value: Any) -> date | None:
        text = _clean(value)
        if text is None:
            return None
        try:
            return datetime.fromisoformat(text.replace("Z", "+00:00")).date()
        except ValueError:
            return None

    @staticmethod
    def _classify_row(
        *,
        symbol: str | None,
        name: str | None,
        segment: str | None,
        category: str | None,
    ) -> tuple[str, str]:
        haystack = " ".join(part.upper() for part in (symbol, name, segment, category) if part)
        if any(
            marker in haystack
            for marker in (
                "CASH",
                "SWEEP",
                "SHORT TERM INVESTMENTS",
                "DEPOSIT ACCOUNT",
                "MONEY MARKET",
            )
        ):
            return "cash", "cash"
        return "security", "fund"


class InverdaleHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Inverdale's complete MGMT portfolio from its public Ballast feed.

    The Ballast ETF application declares this FilePoint endpoint and fund id in
    its own product script.  Keep the endpoint and validation scoped to MGMT so
    the shared FilePoint host never becomes a generic provider fallback.
    """

    SUPPORTED_SYMBOL = "MGMT"
    FUND_ID = "1247"
    PRODUCT_PAGE_URL = "https://etf.mgmtetf.com/"
    HOLDINGS_URL = "https://filepoint.live/ballast_getholdings_cached4.php"
    _EXPECTED_PORTFOLIO_NAME = "Ballast Small/Mid Cap ETF"

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        normalized_symbol = symbol.strip().upper()
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.8500"),
            # Registry probes establish that an adapter is configured.  The
            # fetch boundary below remains intentionally MGMT-only.
            status="ready" if normalized_symbol else "needs_issuer_route",
            reason=(
                "Inverdale's Ballast MGMT product page declares a complete current "
                "portfolio feed."
                if normalized_symbol == self.SUPPORTED_SYMBOL
                else "Inverdale currently has a verified public holdings route only for MGMT."
            ),
            issuer_product_id=self.FUND_ID if normalized_symbol == self.SUPPORTED_SYMBOL else None,
            source_url=self.HOLDINGS_URL if normalized_symbol == self.SUPPORTED_SYMBOL else None,
            required_identifiers=[] if normalized_symbol == self.SUPPORTED_SYMBOL else ["symbol"],
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        if normalized_symbol != self.SUPPORTED_SYMBOL:
            raise ValueError("Inverdale has a verified public holdings route only for MGMT.")
        requested_fund_id = _clean(issuer_product_id) or _identifier(
            identifiers or {}, "issuer_product_id", "inverdale_fund_id", "fund_id"
        )
        if requested_fund_id and requested_fund_id != self.FUND_ID:
            raise ValueError("Inverdale MGMT holdings must use the issuer-declared fund id.")

        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = await self._post_holdings_with_timeout_retry(
                client,
                self.HOLDINGS_URL,
                data={"fundID": self.FUND_ID},
                headers=self.source_request_headers(),
            )
        response.raise_for_status()
        payload = response.json()
        rows, composition_date = self._parse_rows(payload)
        if not rows:
            raise ValueError(
                "Inverdale's MGMT portfolio endpoint returned no complete holdings rows."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json={"rows": payload} if isinstance(payload, list) else None,
            source_url=self.HOLDINGS_URL,
            source_identifier=self.FUND_ID,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "json",
                "route_resolution": "issuer_declared_mgmt_filepoint_holdings_json",
                "product_page_url": self.PRODUCT_PAGE_URL,
                "fund_id": self.FUND_ID,
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def source_request_headers() -> dict[str, str]:
        headers = _issuer_page_request_headers(
            accept="application/json, text/javascript, */*; q=0.01"
        )
        headers.update(
            {
                "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
                "Origin": "https://etf.mgmtetf.com",
                "Referer": InverdaleHoldingsAdapter.PRODUCT_PAGE_URL,
                "X-Requested-With": "XMLHttpRequest",
            }
        )
        return headers

    @staticmethod
    async def _post_holdings_with_timeout_retry(
        client: httpx.AsyncClient,
        url: str,
        *,
        data: dict[str, str],
        headers: dict[str, str],
    ) -> httpx.Response:
        for attempt in range(3):
            try:
                return await client.post(url, data=data, headers=headers, follow_redirects=True)
            except httpx.TimeoutException:
                if attempt == 2:
                    raise
                await asyncio.sleep(0.25 * (attempt + 1))
        raise AssertionError("unreachable")

    @classmethod
    def _parse_rows(cls, payload: Any) -> tuple[list[CanonicalHoldingRow], date | None]:
        if not isinstance(payload, list):
            return [], None
        rows: list[CanonicalHoldingRow] = []
        dates: list[date] = []
        for index, item in enumerate(payload, start=1):
            if not isinstance(item, dict):
                continue
            fund_id = _clean(item.get("portfolioNumber"))
            portfolio_name = _clean(item.get("portfolioName") or item.get("portoflioName"))
            if fund_id != cls.FUND_ID or portfolio_name != cls._EXPECTED_PORTFOLIO_NAME:
                continue
            composition_date = cls._parse_date(item.get("asOfDate"))
            if composition_date:
                dates.append(composition_date)
            source_symbol = _clean(item.get("securityTicker"))
            symbol = source_symbol.split()[0].upper() if source_symbol else None
            name = _clean(
                item.get("securityDescriptionLong") or item.get("securityDescriptionShort")
            )
            row_type, holding_type = cls._classify_row(
                symbol=symbol,
                name=name,
                segment=_clean(item.get("segment")),
                category=_clean(item.get("category")),
            )
            identifier = _clean(item.get("securityIdentifier"))
            rows.append(
                CanonicalHoldingRow(
                    symbol=symbol if row_type == "security" else None,
                    name=name,
                    cusip=identifier if _looks_like_cusip(identifier) else None,
                    weight=_decimal(item.get("marketValuePercent")),
                    shares=_decimal(item.get("shares")),
                    market_value=_decimal(item.get("marketValueBase")),
                    currency=_clean(item.get("tradingCurrency") or item.get("incomeCurrency")),
                    country=_clean(item.get("country")),
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=str(index),
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        return rows, max(dates) if dates else None

    @staticmethod
    def _parse_date(value: Any) -> date | None:
        text = _clean(value)
        if text is None:
            return None
        try:
            return datetime.fromisoformat(text.replace("Z", "+00:00")).date()
        except ValueError:
            return None

    @staticmethod
    def _classify_row(
        *,
        symbol: str | None,
        name: str | None,
        segment: str | None,
        category: str | None,
    ) -> tuple[str, str]:
        haystack = " ".join(part.upper() for part in (symbol, name, segment, category) if part)
        if any(marker in haystack for marker in ("CURRENCY", "CASH", "RECEIVABLE", "PAYABLE")):
            return "cash", "cash"
        if "REIT" in haystack:
            return "security", "reit"
        return "security", "equity"


class HypatiaHoldingsAdapter(IssuerCsvHoldingsAdapter):
    """Fetch Hypatia ETF holdings from its public fund-scoped FilePoint API."""

    holdings_endpoint = "https://filepoint.live/hypatia_getholdings_cached4.php"
    product_pages = {
        "WCEO": "https://wceoetf.com/",
    }
    fund_ids = {
        "WCEO": "1473",
    }

    def probe(self, *, symbol: str, name: str, identifiers: dict[str, str]) -> HoldingsAdapterProbe:
        del name
        normalized_symbol = symbol.strip().upper()
        fund_id = _identifier(
            identifiers, "issuer_product_id", "hypatia_fund_id"
        ) or self.fund_ids.get(normalized_symbol)
        return HoldingsAdapterProbe(
            adapter_key=self.adapter_key,
            confidence=Decimal("0.9500") if fund_id else Decimal("0.5000"),
            status="ready",
            reason=(
                "Hypatia publishes this ETF's complete current holdings through its public fund API."
                if fund_id
                else "Hypatia's verified public holdings route currently covers WCEO only."
            ),
            source_url=self.product_pages.get(normalized_symbol),
            issuer_product_id=fund_id,
        )

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        del source_url
        normalized_symbol = symbol.strip().upper()
        fund_id = (
            _clean(issuer_product_id)
            or _identifier(identifiers or {}, "issuer_product_id", "hypatia_fund_id")
            or self.fund_ids.get(normalized_symbol)
        )
        product_page_url = self.product_pages.get(normalized_symbol)
        if not fund_id or not product_page_url:
            raise ValueError(
                f"Hypatia's verified issuer-native holdings route does not include {normalized_symbol}."
            )

        headers = _issuer_page_request_headers(
            accept="application/json, text/javascript, */*; q=0.01"
        )
        headers.update(
            {
                "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
                "Origin": "https://wceoetf.com",
                "Referer": product_page_url,
                "X-Requested-With": "XMLHttpRequest",
            }
        )
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            response = None
            for attempt in range(3):
                try:
                    response = await client.post(
                        self.holdings_endpoint,
                        data={"fundID": fund_id},
                        headers=headers,
                        follow_redirects=True,
                    )
                    break
                except httpx.TimeoutException:
                    if attempt == 2:
                        raise
                    await asyncio.sleep(0.25 * (attempt + 1))
            if response is None:
                raise AssertionError("unreachable")
        response.raise_for_status()
        payload = response.json()
        rows, composition_date = self._parse_hypatia_rows(payload)
        if not rows:
            raise ValueError(
                f"Hypatia's issuer holdings API did not return a complete portfolio for {normalized_symbol}."
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=response.text,
            raw_json={"rows": payload} if isinstance(payload, list) else None,
            source_url=str(getattr(response, "url", self.holdings_endpoint)),
            source_identifier=fund_id,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "json",
                "route_resolution": "hypatia_public_fund_scoped_holdings_api",
                "fund_id": fund_id,
                "product_page_url": product_page_url,
                "source_quality": "issuer_reported_daily_holdings",
                "snapshot_provenance": "issuer_native_daily_holdings_api",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "terms_note": self.config.terms_note,
            },
        )

    @classmethod
    def _parse_hypatia_rows(cls, payload: Any) -> tuple[list[CanonicalHoldingRow], date | None]:
        if not isinstance(payload, list):
            return [], None
        rows: list[CanonicalHoldingRow] = []
        composition_dates: list[date] = []
        for index, item in enumerate(payload, start=1):
            if not isinstance(item, dict):
                continue
            composition_date = cls._parse_date(item.get("asOfDate"))
            if composition_date:
                composition_dates.append(composition_date)
            segment = _clean(item.get("segment"))
            category = _clean(item.get("category"))
            raw_symbol = _clean(item.get("securityTicker"))
            row_type, holding_type = cls._classify_row(
                raw_symbol=raw_symbol,
                name=_clean(
                    item.get("securityDescriptionLong") or item.get("securityDescriptionShort")
                ),
                segment=segment,
                category=category,
            )
            identifier = _clean(item.get("securityIdentifier"))
            rows.append(
                CanonicalHoldingRow(
                    symbol=cls._clean_symbol(raw_symbol) if row_type == "security" else None,
                    name=_clean(
                        item.get("securityDescriptionLong") or item.get("securityDescriptionShort")
                    ),
                    cusip=identifier if _looks_like_cusip(identifier) else None,
                    weight=_decimal(item.get("marketValuePercent")),
                    shares=_decimal(item.get("shares")),
                    market_value=_decimal(item.get("marketValueBase")),
                    currency=_clean(item.get("tradingCurrency") or item.get("incomeCurrency")),
                    country=_clean(item.get("country")),
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=str(index),
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        return rows, max(composition_dates) if composition_dates else None

    @staticmethod
    def _clean_symbol(value: str | None) -> str | None:
        text = _clean(value)
        return text.split()[0].strip().upper() if text else None

    @staticmethod
    def _parse_date(value: Any) -> date | None:
        text = _clean(value)
        if text is None:
            return None
        try:
            return datetime.fromisoformat(text.replace("Z", "+00:00")).date()
        except ValueError:
            return None

    @staticmethod
    def _classify_row(
        *,
        raw_symbol: str | None,
        name: str | None,
        segment: str | None,
        category: str | None,
    ) -> tuple[str, str]:
        haystack = " ".join(
            value.upper() for value in (raw_symbol, name, segment, category) if value
        )
        if any(marker in haystack for marker in ("CASH", "CURRENCY", "US DOLLARS")):
            return "cash", "cash"
        return "security", "equity"


class SimplifyHoldingsAdapter(IssuerCsvHoldingsAdapter):
    product_index_url = "https://www.simplify.us/etfs"

    async def fetch_latest(
        self,
        *,
        symbol: str,
        issuer_product_id: str | None = None,
        source_url: str | None = None,
        identifiers: dict[str, str] | None = None,
    ) -> HoldingsFetchResult:
        normalized_symbol = symbol.strip().upper()
        source_page_url = source_url or self.product_index_url
        async with httpx.AsyncClient(timeout=settings.ETF_HOLDINGS_FETCH_TIMEOUT_SECONDS) as client:
            if self._is_workbook_url(source_page_url):
                workbook_url = source_page_url
            else:
                page_response = await client.get(
                    source_page_url,
                    headers=_issuer_page_request_headers(accept="text/html,*/*"),
                    follow_redirects=True,
                )
                page_response.raise_for_status()
                workbook_url = _discover_holdings_download_url(
                    str(getattr(page_response, "url", source_page_url)),
                    page_response.text,
                )
                if not workbook_url:
                    return await super().fetch_latest(
                        symbol=symbol,
                        issuer_product_id=issuer_product_id,
                        source_url=source_url,
                        identifiers=identifiers,
                    )

            workbook_response = await client.get(
                workbook_url,
                headers=_holdings_request_headers(
                    accept=(
                        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,"
                        "application/vnd.ms-excel,*/*"
                    ),
                ),
                follow_redirects=True,
            )
        workbook_response.raise_for_status()
        workbook_rows = parse_xlsx_table(workbook_response.content)
        rows, composition_date = self._parse_simplify_workbook(
            workbook_rows,
            account_symbol=normalized_symbol,
        )
        if not rows:
            return await super().fetch_latest(
                symbol=symbol,
                issuer_product_id=issuer_product_id,
                source_url=source_url,
                identifiers=identifiers,
            )
        return HoldingsFetchResult(
            rows=rows,
            raw_text=_table_to_text(workbook_rows),
            raw_json={"source_format": "xlsx", "workbook_rows": workbook_rows},
            source_url=str(getattr(workbook_response, "url", workbook_url)),
            source_identifier=normalized_symbol,
            legal_metadata={
                "source_access": self.config.source_access,
                "source_provider": self.source_provider,
                "adapter_key": self.adapter_key,
                "source_format": "xlsx",
                "route_resolution": "issuer_aggregate_holdings_xlsx",
                "composition_date": composition_date.isoformat() if composition_date else None,
                "as_of_date": composition_date.isoformat() if composition_date else None,
                "account_symbol": normalized_symbol,
                "terms_note": self.config.terms_note,
            },
        )

    @staticmethod
    def _is_workbook_url(value: str) -> bool:
        return value.lower().split("?", 1)[0].endswith((".xlsx", ".xlsm"))

    def _parse_simplify_workbook(
        self,
        workbook_rows: list[list[str]],
        *,
        account_symbol: str,
    ) -> tuple[list[CanonicalHoldingRow], date | None]:
        header_index = next(
            (
                index
                for index, row in enumerate(workbook_rows)
                if row and str(row[0]).strip().upper() == "FUND NAME"
            ),
            None,
        )
        if header_index is None:
            return [], None
        composition_date = self._parse_simplify_date(
            workbook_rows[0][-1] if workbook_rows and workbook_rows[0] else None
        )
        headers = workbook_rows[header_index]
        rows: list[CanonicalHoldingRow] = []
        for row_index, row in enumerate(workbook_rows[header_index + 1 :], start=header_index + 2):
            item = _row_dict(headers, row)
            if (_clean(item.get("FUND NAME")) or "").upper() != account_symbol:
                continue
            raw_symbol = _clean(item.get("TICKER"))
            name = _clean(item.get("SECURITY DESCRIPTION"))
            cusip = _clean(item.get("CUSIP"))
            isin = _clean(item.get("ISIN"))
            if not any([raw_symbol, name, cusip, isin]):
                continue
            holding_type = self._simplify_holding_type(raw_symbol=raw_symbol, name=name)
            row_type = "cash" if holding_type == "cash" else "security"
            rows.append(
                CanonicalHoldingRow(
                    symbol=raw_symbol if row_type != "cash" else None,
                    name=name,
                    cusip=cusip,
                    isin=isin,
                    sedol=_clean(item.get("SEDOL")),
                    weight=_decimal(item.get("Weight")),
                    shares=_decimal(item.get("Quantity")),
                    market_value=_decimal(item.get("Market Value/Exposure")),
                    holding_type=holding_type,
                    row_type=row_type,
                    source_row_id=str(row_index),
                    extra_data={
                        key: value for key, value in item.items() if value not in (None, "")
                    },
                )
            )
        return rows, composition_date

    @staticmethod
    def _simplify_holding_type(*, raw_symbol: str | None, name: str | None) -> str:
        symbol_text = (raw_symbol or "").upper()
        name_text = (name or "").upper()
        if symbol_text == "CASH" or name_text == "CASH":
            return "cash"
        if " COMDTY" in symbol_text:
            return "commodity"
        if " INDEX" in symbol_text:
            return "derivative"
        if " GOVT" in symbol_text:
            return "fixed_income"
        return "security"

    @staticmethod
    def _parse_simplify_date(value: str | None) -> date | None:
        text = _clean(value)
        if not text:
            return None
        for date_format in ("%m/%d/%Y", "%Y-%m-%d"):
            try:
                return datetime.strptime(text, date_format).date()
            except ValueError:
                continue
        return None


